# グローバルエラーハンドラー（エラーをブラウザに詳細表示）
JST = timezone(timedelta(hours=9), name='JST')


def get_jst_now():
    """公開開始/終了の比較は日本時間基準で揃える。"""
    return datetime.now(JST).replace(tzinfo=None)


def parse_proxy_service_datetime(value):
    if not value:
        return None

    if isinstance(value, datetime):
        if value.tzinfo is not None:
            return value.astimezone(JST).replace(tzinfo=None)
        return value

    if isinstance(value, str):
        raw = value.strip()
        if not raw:
            return None

        candidates = [raw, raw.replace('T', ' ')]
        if raw.endswith('Z'):
            candidates.insert(0, raw[:-1] + '+00:00')

        for candidate in candidates:
            try:
                parsed = datetime.fromisoformat(candidate)
                if parsed.tzinfo is not None:
                    return parsed.astimezone(JST).replace(tzinfo=None)
                return parsed
            except ValueError:
                continue

        normalized = raw.replace('T', ' ')
        for fmt in ('%Y-%m-%d %H:%M', '%Y-%m-%d %H:%M:%S'):
            try:
                return datetime.strptime(normalized, fmt)
            except ValueError:
                continue

    return None


def normalize_proxy_service_datetime_input(value):
    parsed = parse_proxy_service_datetime(value)
    if not parsed:
        return None
    return parsed.strftime('%Y-%m-%d %H:%M:%S')


def extract_proxy_service_purchase_buyer_name(sales_destination):
    if not sales_destination:
        return None

    destination_text = str(sales_destination).strip()
    for prefix in ('即決購入:', '即決購入：'):
        if destination_text.startswith(prefix):
            buyer_name = destination_text[len(prefix):].strip()
            return buyer_name or None

    return None


def proxy_service_row_to_dict(row):
    if row is None:
        return None
    return row if isinstance(row, dict) else dict(row)


def build_proxy_service_origin_note(original_item_id, mode='auction'):
    note_prefix = '代行仕入れサービス購入' if mode == 'fixed' else '代行仕入れサービス落札'
    return f'{note_prefix} / 元商品ID:{original_item_id}'


def is_garbled_display_text(value):
    text = str(value or '').strip()
    if not text:
        return False
    if '�' in text or '??' in text:
        return True
    mojibake_markers = ('繧', '縺', '譁', '譖', '邱', '荳', '髢', '蜃', '鬘', '竊', '蛯', '險', '雋')
    return sum(1 for marker in mojibake_markers if marker in text) >= 2


def clean_display_text(value, fallback='-'):
    text = str(value or '').strip()
    if not text:
        return fallback
    clean_lines = [line.strip() for line in text.splitlines() if line.strip() and not is_garbled_display_text(line)]
    if clean_lines:
        return '\n'.join(clean_lines)
    return fallback


@app.template_filter('clean_display')
def clean_display_filter(value, fallback='-'):
    return clean_display_text(value, fallback=fallback)


def append_proxy_service_origin_note(existing_notes, original_item_id, mode='auction'):
    origin_note = build_proxy_service_origin_note(original_item_id, mode=mode)
    notes = clean_display_text(existing_notes, fallback='').strip()
    if origin_note in notes:
        return notes
    return f'{notes}\n{origin_note}' if notes else origin_note


def lookup_proxy_service_reflected_item(cur, original_item_id, winner_user_id=None):
    note_marker = f'%元商品ID:{original_item_id}%'

    if DATABASE_URL:
        query = """
            SELECT m.id, m.user_id, m.proxy_parent_item_id, m.purchase_date, m.created_at,
                   COALESCE(u.display_name, u.username, '不明') AS owner_name
            FROM merchandise m
            LEFT JOIN users u ON u.id = m.user_id
            WHERE (m.proxy_parent_item_id = %s OR m.notes LIKE %s)
        """
        params = [original_item_id, note_marker]
        if winner_user_id:
            query += " AND m.user_id = %s"
            params.append(winner_user_id)
        query += """
            ORDER BY CASE WHEN m.proxy_parent_item_id = %s THEN 0 ELSE 1 END,
                     m.id DESC
            LIMIT 1
        """
        params.append(original_item_id)
    else:
        query = """
            SELECT m.id, m.user_id, m.proxy_parent_item_id, m.purchase_date, m.created_at,
                   COALESCE(u.display_name, u.username, '不明') AS owner_name
            FROM merchandise m
            LEFT JOIN users u ON u.id = m.user_id
            WHERE (m.proxy_parent_item_id = ? OR m.notes LIKE ?)
        """
        params = [original_item_id, note_marker]
        if winner_user_id:
            query += " AND m.user_id = ?"
            params.append(winner_user_id)
        query += """
            ORDER BY CASE WHEN m.proxy_parent_item_id = ? THEN 0 ELSE 1 END,
                     m.id DESC
            LIMIT 1
        """
        params.append(original_item_id)

    cur.execute(query, tuple(params))
    return proxy_service_row_to_dict(cur.fetchone())


def hydrate_proxy_service_reflection_state(conn, items):
    if not items:
        return items

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
    else:
        cur = conn.cursor()

    try:
        for item in items:
            needs_lookup = not item.get('reflected_item_id')
            if not needs_lookup and item.get('reflected_user_name') and item.get('reflected_at'):
                continue

            if not item.get('sale_date') and not item.get('highest_bid_user_id'):
                continue

            reflected_item = lookup_proxy_service_reflected_item(
                cur,
                item.get('id'),
                winner_user_id=item.get('highest_bid_user_id'),
            )
            if not reflected_item:
                continue

            item['reflected_item_id'] = reflected_item.get('id')
            item['reflected_user_id'] = reflected_item.get('user_id')
            item['reflected_user_name'] = reflected_item.get('owner_name')
            item['reflected_at'] = reflected_item.get('created_at') or reflected_item.get('purchase_date')
    finally:
        cur.close()

    return items


def ensure_proxy_service_keisan_columns(conn=None, cur=None):
    managed_conn = False
    managed_cursor = False

    if conn is None:
        conn = get_db()
        managed_conn = True
    if cur is None:
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
        else:
            cur = conn.cursor()
        managed_cursor = True

    try:
        column_specs = [
            (
                'proxy_service_auction_id',
                "ALTER TABLE user_keisan ADD COLUMN proxy_service_auction_id INTEGER",
                "ALTER TABLE user_keisan ADD COLUMN proxy_service_auction_id INTEGER",
            ),
        ]
        for column_name, pg_sql, sqlite_sql in column_specs:
            if _docs_column_exists(cur, 'user_keisan', column_name):
                continue
            cur.execute(pg_sql if DATABASE_URL else sqlite_sql)

        item_column_specs = [
            (
                'proxy_source_item_id',
                "ALTER TABLE user_keisan_items ADD COLUMN proxy_source_item_id INTEGER REFERENCES merchandise(id)",
                "ALTER TABLE user_keisan_items ADD COLUMN proxy_source_item_id INTEGER REFERENCES merchandise(id)",
            ),
        ]
        for column_name, pg_sql, sqlite_sql in item_column_specs:
            if _docs_column_exists(cur, 'user_keisan_items', column_name):
                continue
            cur.execute(pg_sql if DATABASE_URL else sqlite_sql)
        if managed_conn:
            conn.commit()
    finally:
        if managed_cursor:
            cur.close()
        if managed_conn:
            conn.close()


def ensure_proxy_service_auction_user_table(conn=None, cur=None):
    managed_conn = False
    managed_cursor = False

    if conn is None:
        conn = get_db()
        managed_conn = True
    if cur is None:
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
        else:
            cur = conn.cursor()
        managed_cursor = True

    try:
        if DATABASE_URL:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS proxy_service_auction_users (
                    id SERIAL PRIMARY KEY,
                    auction_id INTEGER REFERENCES proxy_service_settings(id) ON DELETE CASCADE,
                    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
                    is_enabled BOOLEAN DEFAULT TRUE,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(auction_id, user_id)
                )
                """
            )
        else:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS proxy_service_auction_users (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    auction_id INTEGER REFERENCES proxy_service_settings(id) ON DELETE CASCADE,
                    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
                    is_enabled INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(auction_id, user_id)
                )
                """
            )
        if managed_conn:
            conn.commit()
    finally:
        if managed_cursor:
            cur.close()
        if managed_conn:
            conn.close()


def _proxy_service_auction_user_count(conn, auction_id):
    ensure_proxy_service_auction_user_table(conn)

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute(
            """
            SELECT COUNT(*) AS count
            FROM proxy_service_auction_users
            WHERE auction_id = %s
              AND COALESCE(is_enabled, TRUE) = TRUE
            """,
            (auction_id,),
        )
        row = cur.fetchone()
        cur.close()
        return int((row or {}).get('count') or 0)

    cur = conn.cursor()
    cur.execute(
        """
        SELECT COUNT(*) AS count
        FROM proxy_service_auction_users
        WHERE auction_id = ?
          AND COALESCE(is_enabled, 1) = 1
        """,
        (auction_id,),
    )
    row = cur.fetchone()
    cur.close()
    return int((dict(row).get('count') if row else 0) or 0)


def proxy_service_auction_has_target_users(conn, auction_id):
    return _proxy_service_auction_user_count(conn, auction_id) > 0


