def is_proxy_service_user_allowed(conn, user_id, auction_id):
    if not user_id or not auction_id:
        return False

    ensure_proxy_service_auction_user_table(conn)

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute(
            """
            SELECT 1
            FROM proxy_service_auction_users
            WHERE auction_id = %s
              AND user_id = %s
              AND COALESCE(is_enabled, TRUE) = TRUE
            LIMIT 1
            """,
            (auction_id, user_id),
        )
        allowed = cur.fetchone() is not None
        cur.close()
        return allowed

    cur = conn.cursor()
    cur.execute(
        """
        SELECT 1
        FROM proxy_service_auction_users
        WHERE auction_id = ?
          AND user_id = ?
          AND COALESCE(is_enabled, 1) = 1
        LIMIT 1
        """,
        (auction_id, user_id),
    )
    allowed = cur.fetchone() is not None
    cur.close()
    return allowed


def sync_proxy_service_keisan_documents(conn):
    ensure_proxy_service_keisan_columns(conn)
    now = get_jst_now()
    today_value = now.strftime('%Y-%m-%d')
    updated_at_value = now.strftime('%Y-%m-%d %H:%M:%S')

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
    else:
        cur = conn.cursor()

    try:
        if DATABASE_URL:
            cur.execute(
                """
                SELECT k.id,
                       k.user_id,
                       k.proxy_service_auction_id,
                       COUNT(DISTINCT src.auction_id) AS auction_count,
                       MAX(src.auction_id) AS inferred_auction_id
                FROM user_keisan k
                LEFT JOIN user_keisan_items ki ON ki.keisan_id = k.id
                LEFT JOIN merchandise reflected ON reflected.id = ki.merchandise_id
                LEFT JOIN merchandise src ON src.id = COALESCE(ki.proxy_source_item_id, reflected.proxy_parent_item_id)
                WHERE k.is_admin_created = TRUE
                GROUP BY k.id, k.user_id, k.proxy_service_auction_id
                """
            )
        else:
            cur.execute(
                """
                SELECT k.id,
                       k.user_id,
                       k.proxy_service_auction_id,
                       COUNT(DISTINCT src.auction_id) AS auction_count,
                       MAX(src.auction_id) AS inferred_auction_id
                FROM user_keisan k
                LEFT JOIN user_keisan_items ki ON ki.keisan_id = k.id
                LEFT JOIN merchandise reflected ON reflected.id = ki.merchandise_id
                LEFT JOIN merchandise src ON src.id = COALESCE(ki.proxy_source_item_id, reflected.proxy_parent_item_id)
                WHERE k.is_admin_created = 1
                GROUP BY k.id, k.user_id, k.proxy_service_auction_id
                """
            )

        for raw_doc in cur.fetchall():
            doc = proxy_service_row_to_dict(raw_doc)
            inferred_auction_id = doc.get('inferred_auction_id')
            auction_count = int(doc.get('auction_count') or 0)
            current_auction_id = doc.get('proxy_service_auction_id')
            if not inferred_auction_id or auction_count != 1 or current_auction_id == inferred_auction_id:
                continue

            if DATABASE_URL:
                cur.execute(
                    """
                    UPDATE user_keisan
                    SET proxy_service_auction_id = %s,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                    """,
                    (inferred_auction_id, doc['id']),
                )
            else:
                cur.execute(
                    """
                    UPDATE user_keisan
                    SET proxy_service_auction_id = ?,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (inferred_auction_id, doc['id']),
                )

        if DATABASE_URL:
            cur.execute(
                """
                SELECT id, user_id, proxy_service_auction_id, status, created_at
                FROM user_keisan
                WHERE is_admin_created = TRUE
                  AND proxy_service_auction_id IS NOT NULL
                  AND status <> 'submitted'
                ORDER BY created_at ASC, id ASC
                """
            )
        else:
            cur.execute(
                """
                SELECT id, user_id, proxy_service_auction_id, status, created_at
                FROM user_keisan
                WHERE is_admin_created = 1
                  AND proxy_service_auction_id IS NOT NULL
                  AND status <> 'submitted'
                ORDER BY created_at ASC, id ASC
                """
            )

        docs_by_group = {}
        for raw_doc in cur.fetchall():
            doc = proxy_service_row_to_dict(raw_doc)
            docs_by_group.setdefault((doc.get('user_id'), doc.get('proxy_service_auction_id')), []).append(doc)

        for group_docs in docs_by_group.values():
            if len(group_docs) <= 1:
                continue

            primary_doc = group_docs[0]
            primary_id = primary_doc['id']
            duplicate_ids = [doc['id'] for doc in group_docs[1:]]
            target_ids = [doc['id'] for doc in group_docs]

            if DATABASE_URL:
                placeholders = ','.join(['%s'] * len(target_ids))
                cur.execute(
                    f"""
                    SELECT keisan_id, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                    FROM user_keisan_items
                    WHERE keisan_id IN ({placeholders})
                    ORDER BY keisan_id, item_no
                    """,
                    tuple(target_ids),
                )
            else:
                placeholders = ','.join(['?'] * len(target_ids))
                cur.execute(
                    f"""
                    SELECT keisan_id, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                    FROM user_keisan_items
                    WHERE keisan_id IN ({placeholders})
                    ORDER BY keisan_id, item_no
                    """,
                    tuple(target_ids),
                )

            combined_items = []
            seen_item_keys = set()
            for raw_item in cur.fetchall():
                item = proxy_service_row_to_dict(raw_item)
                item_key = item.get('proxy_source_item_id') or item.get('merchandise_id')
                if item_key:
                    if item_key in seen_item_keys:
                        continue
                    seen_item_keys.add(item_key)
                combined_items.append(item)

            if DATABASE_URL:
                cur.execute("DELETE FROM user_keisan_items WHERE keisan_id = ANY(%s)", (target_ids,))
            else:
                placeholders = ','.join(['?'] * len(target_ids))
                cur.execute(f"DELETE FROM user_keisan_items WHERE keisan_id IN ({placeholders})", tuple(target_ids))

            total_amount = 0
            for index, item in enumerate(combined_items, start=1):
                quantity = int(item.get('quantity') or 1)
                unit_price = int(item.get('unit_price') or 0)
                amount = int(item.get('amount') or (quantity * unit_price))
                total_amount += amount
                if DATABASE_URL:
                    cur.execute(
                        """
                        INSERT INTO user_keisan_items (
                            keisan_id, item_no, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                        """,
                        (
                            primary_id,
                            index,
                            item.get('item_name'),
                            item.get('merchandise_id'),
                            item.get('proxy_source_item_id'),
                            quantity,
                            item.get('unit'),
                            unit_price,
                            amount,
                        ),
                    )
                else:
                    cur.execute(
                        """
                        INSERT INTO user_keisan_items (
                            keisan_id, item_no, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            primary_id,
                            index,
                            item.get('item_name'),
                            item.get('merchandise_id'),
                            item.get('proxy_source_item_id'),
                            quantity,
                            item.get('unit'),
                            unit_price,
                            amount,
                        ),
                    )

            if DATABASE_URL:
                cur.execute(
                    """
                    UPDATE user_keisan
                    SET total_amount = %s,
                        status = 'draft',
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                    """,
                    (total_amount, primary_id),
                )
                if duplicate_ids:
                    cur.execute("DELETE FROM user_keisan WHERE id = ANY(%s)", (duplicate_ids,))
            else:
                cur.execute(
                    """
                    UPDATE user_keisan
                    SET total_amount = ?,
                        status = 'draft',
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = ?
                    """,
                    (total_amount, primary_id),
                )
                if duplicate_ids:
                    placeholders = ','.join(['?'] * len(duplicate_ids))
                    cur.execute(f"DELETE FROM user_keisan WHERE id IN ({placeholders})", tuple(duplicate_ids))

        if DATABASE_URL:
            cur.execute(
                """
                SELECT ki.proxy_source_item_id AS source_item_id,
                       COALESCE(NULLIF(ki.unit_price, 0), NULLIF(ki.amount, 0), 0) AS result_price,
                       k.user_id,
                       COALESCE(k.recipient_name, u.display_name, u.username, '') AS winner_name,
                       COALESCE(ps.sale_mode, 'auction') AS sale_mode
                FROM user_keisan k
                JOIN user_keisan_items ki ON ki.keisan_id = k.id
                JOIN users u ON u.id = k.user_id
                LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
                JOIN merchandise src ON src.id = ki.proxy_source_item_id
                WHERE k.is_admin_created = TRUE
                  AND k.proxy_service_auction_id IS NOT NULL
                  AND k.status = 'submitted'
                  AND ki.proxy_source_item_id IS NOT NULL
                  AND COALESCE(NULLIF(ki.unit_price, 0), NULLIF(ki.amount, 0), 0) > 0
                  AND (
                      COALESCE(src.sale_price, 0) <= 0
                      OR src.sale_date IS NULL
                      OR COALESCE(src.show_in_proxy_service, TRUE) = TRUE
                      OR COALESCE(NULLIF(src.sales_destination, ''), '') = ''
                  )
                """
            )
            source_repairs = [dict(row) for row in cur.fetchall()]
            for repair in source_repairs:
                destination_prefix = '代行仕入れ購入' if (repair.get('sale_mode') or '') == 'fixed' else '代行仕入れ落札'
                winner_name = repair.get('winner_name') or ''
                destination = f'{destination_prefix}: {winner_name}' if winner_name else destination_prefix
                cur.execute(
                    """
                    UPDATE merchandise
                    SET sale_date = COALESCE(sale_date, %s),
                        sale_price = CASE
                            WHEN COALESCE(sale_price, 0) <= 0 THEN %s
                            ELSE sale_price
                        END,
                        sales_destination = CASE
                            WHEN COALESCE(NULLIF(sales_destination, ''), '') = '' THEN %s
                            ELSE sales_destination
                        END,
                        show_in_proxy_service = FALSE,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    (today_value, repair['result_price'], destination, updated_at_value, repair['source_item_id']),
                )
        else:
            cur.execute(
                """
                SELECT ki.proxy_source_item_id AS source_item_id,
                       COALESCE(NULLIF(ki.unit_price, 0), NULLIF(ki.amount, 0), 0) AS result_price,
                       k.user_id,
                       COALESCE(k.recipient_name, u.display_name, u.username, '') AS winner_name,
                       COALESCE(ps.sale_mode, 'auction') AS sale_mode
                FROM user_keisan k
                JOIN user_keisan_items ki ON ki.keisan_id = k.id
                JOIN users u ON u.id = k.user_id
                LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
                JOIN merchandise src ON src.id = ki.proxy_source_item_id
                WHERE k.is_admin_created = 1
                  AND k.proxy_service_auction_id IS NOT NULL
                  AND k.status = 'submitted'
                  AND ki.proxy_source_item_id IS NOT NULL
                  AND COALESCE(NULLIF(ki.unit_price, 0), NULLIF(ki.amount, 0), 0) > 0
                  AND (
                      COALESCE(src.sale_price, 0) <= 0
                      OR src.sale_date IS NULL
                      OR COALESCE(src.show_in_proxy_service, 1) = 1
                      OR COALESCE(NULLIF(src.sales_destination, ''), '') = ''
                  )
                """
            )
            source_repairs = [proxy_service_row_to_dict(row) for row in cur.fetchall()]
            for repair in source_repairs:
                destination_prefix = '代行仕入れ購入' if (repair.get('sale_mode') or '') == 'fixed' else '代行仕入れ落札'
                winner_name = repair.get('winner_name') or ''
                destination = f'{destination_prefix}: {winner_name}' if winner_name else destination_prefix
                cur.execute(
                    """
                    UPDATE merchandise
                    SET sale_date = COALESCE(sale_date, ?),
                        sale_price = CASE
                            WHEN COALESCE(sale_price, 0) <= 0 THEN ?
                            ELSE sale_price
                        END,
                        sales_destination = CASE
                            WHEN COALESCE(NULLIF(sales_destination, ''), '') = '' THEN ?
                            ELSE sales_destination
                        END,
                        show_in_proxy_service = 0,
                        updated_at = ?
                    WHERE id = ?
                    """,
                    (today_value, repair['result_price'], destination, updated_at_value, repair['source_item_id']),
                )
    finally:
        cur.close()


def get_proxy_service_keisan_status_meta(status):
    status_map = {
        'draft': ('下書き', 'draft'),
        'completed': ('送付準備完了', 'ready'),
        'submitted': ('送付済み', 'sent'),
    }
    return status_map.get((status or 'draft').strip(), ('下書き', 'draft'))


def fetch_proxy_service_keisan_doc_map(conn, auction_id=None):
    ensure_proxy_service_keisan_columns(conn)

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        params = []
        query = """
            SELECT k.id, k.user_id, k.proxy_service_auction_id, k.document_no, k.issue_date,
                   k.total_amount, k.status, COALESCE(k.updated_at, k.created_at) AS updated_at,
                   ps.auction_name, ps.sale_mode, ps.end_datetime
            FROM user_keisan k
            LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
            WHERE k.is_admin_created = TRUE
              AND k.proxy_service_auction_id IS NOT NULL
        """
        if auction_id:
            query += " AND k.proxy_service_auction_id = %s"
            params.append(auction_id)
        query += """
            ORDER BY COALESCE(k.updated_at, k.created_at) DESC, k.id DESC
        """
        cur.execute(query, tuple(params))
    else:
        cur = conn.cursor()
        params = []
        query = """
            SELECT k.id, k.user_id, k.proxy_service_auction_id, k.document_no, k.issue_date,
                   k.total_amount, k.status, COALESCE(k.updated_at, k.created_at) AS updated_at,
                   ps.auction_name, ps.sale_mode, ps.end_datetime
            FROM user_keisan k
            LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
            WHERE k.is_admin_created = 1
              AND k.proxy_service_auction_id IS NOT NULL
        """
        if auction_id:
            query += " AND k.proxy_service_auction_id = ?"
            params.append(auction_id)
        query += """
            ORDER BY COALESCE(k.updated_at, k.created_at) DESC, k.id DESC
        """
        cur.execute(query, tuple(params))

    try:
        doc_map = {}
        for raw_doc in cur.fetchall():
            doc = proxy_service_row_to_dict(raw_doc)
            status_label, status_class = get_proxy_service_keisan_status_meta(doc.get('status'))
            doc['status_label'] = status_label
            doc['status_class'] = status_class
            doc_map.setdefault((doc.get('user_id'), doc.get('proxy_service_auction_id')), doc)
        return doc_map
    finally:
        cur.close()


