def upsert_proxy_service_keisan_document(
    conn,
    *,
    auction_id,
    auction_name,
    winner_user_id,
    winner_name,
    source_item,
    amount,
    reflected_item_id=None,
    now=None,
    status='draft',
):
    now = now or get_jst_now()
    ensure_proxy_service_keisan_columns(conn)

    subject = f"{auction_name or '代行仕入れサービス'} 計算書"
    today = now.strftime('%Y-%m-%d')
    updated_at_value = now.strftime('%Y-%m-%d %H:%M:%S')
    source_item_id = (source_item or {}).get('id')
    notes = '\n'.join([
        '代行仕入れサービスの終了結果から作成した計算書です。',
        f'オークションID: {auction_id}',
        f'オークション名: {auction_name or "代行仕入れサービス"}',
    ])

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
    else:
        cur = conn.cursor()

    try:
        if DATABASE_URL:
            cur.execute(
                """
                SELECT id, status
                FROM user_keisan
                WHERE user_id = %s
                  AND is_admin_created = TRUE
                  AND proxy_service_auction_id = %s
                  AND status <> 'submitted'
                ORDER BY id DESC
                LIMIT 1
                """,
                (winner_user_id, auction_id),
            )
            keisan = proxy_service_row_to_dict(cur.fetchone())
        else:
            cur.execute(
                """
                SELECT id, status
                FROM user_keisan
                WHERE user_id = ?
                  AND is_admin_created = 1
                  AND proxy_service_auction_id = ?
                  AND status <> 'submitted'
                ORDER BY id DESC
                LIMIT 1
                """,
                (winner_user_id, auction_id),
            )
            keisan = proxy_service_row_to_dict(cur.fetchone())

        created_doc = False
        item_added = False

        if not keisan:
            document_no = _generate_prefixed_document_no('AK', 'user_keisan', 'document_no')
            if DATABASE_URL:
                cur.execute(
                    """
                    INSERT INTO user_keisan (
                        document_no, user_id, issue_date, recipient_name,
                        subject, total_amount, notes, status, is_admin_created, proxy_service_auction_id
                    ) VALUES (
                        %s, %s, %s, %s,
                        %s, %s, %s, %s, TRUE, %s
                    )
                    RETURNING id, status
                    """,
                    (
                        document_no,
                        winner_user_id,
                        today,
                        winner_name,
                        subject,
                        0,
                        notes,
                        status,
                        auction_id,
                    ),
                )
                keisan = proxy_service_row_to_dict(cur.fetchone())
            else:
                cur.execute(
                    """
                    INSERT INTO user_keisan (
                        document_no, user_id, issue_date, recipient_name,
                        subject, total_amount, notes, status, is_admin_created, proxy_service_auction_id
                    ) VALUES (
                        ?, ?, ?, ?,
                        ?, ?, ?, ?, 1, ?
                    )
                    """,
                    (
                        document_no,
                        winner_user_id,
                        today,
                        winner_name,
                        subject,
                        0,
                        notes,
                        status,
                        auction_id,
                    ),
                )
                keisan = {'id': cur.lastrowid, 'status': status}
            created_doc = True

        keisan_id = keisan['id']

        existing_item = None
        if source_item_id:
            if DATABASE_URL:
                cur.execute(
                    """
                    SELECT id
                    FROM user_keisan_items
                    WHERE keisan_id = %s
                      AND proxy_source_item_id = %s
                    LIMIT 1
                    """,
                    (keisan_id, source_item_id),
                )
            else:
                cur.execute(
                    """
                    SELECT id
                    FROM user_keisan_items
                    WHERE keisan_id = ?
                      AND proxy_source_item_id = ?
                    LIMIT 1
                    """,
                    (keisan_id, source_item_id),
                )
            existing_item = proxy_service_row_to_dict(cur.fetchone())

        if not existing_item and reflected_item_id:
            if DATABASE_URL:
                cur.execute(
                    """
                    SELECT id
                    FROM user_keisan_items
                    WHERE keisan_id = %s
                      AND merchandise_id = %s
                    LIMIT 1
                    """,
                    (keisan_id, reflected_item_id),
                )
            else:
                cur.execute(
                    """
                    SELECT id
                    FROM user_keisan_items
                    WHERE keisan_id = ?
                      AND merchandise_id = ?
                    LIMIT 1
                    """,
                    (keisan_id, reflected_item_id),
                )
            existing_item = proxy_service_row_to_dict(cur.fetchone())

        if not existing_item:
            if DATABASE_URL:
                cur.execute("SELECT COALESCE(MAX(item_no), 0) AS max_item_no FROM user_keisan_items WHERE keisan_id = %s", (keisan_id,))
                next_item_no = int((proxy_service_row_to_dict(cur.fetchone()) or {}).get('max_item_no') or 0) + 1
                cur.execute(
                    """
                    INSERT INTO user_keisan_items (
                        keisan_id, item_no, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                    ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """,
                    (
                        keisan_id,
                        next_item_no,
                        source_item.get('product_name') or source_item.get('brand_name') or '商品',
                        reflected_item_id,
                        source_item_id,
                        1,
                        '点',
                        amount,
                        amount,
                    ),
                )
            else:
                cur.execute("SELECT COALESCE(MAX(item_no), 0) AS max_item_no FROM user_keisan_items WHERE keisan_id = ?", (keisan_id,))
                next_item_no = int((proxy_service_row_to_dict(cur.fetchone()) or {}).get('max_item_no') or 0) + 1
                cur.execute(
                    """
                    INSERT INTO user_keisan_items (
                        keisan_id, item_no, item_name, merchandise_id, proxy_source_item_id, quantity, unit, unit_price, amount
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        keisan_id,
                        next_item_no,
                        source_item.get('product_name') or source_item.get('brand_name') or '商品',
                        reflected_item_id,
                        source_item_id,
                        1,
                        '点',
                        amount,
                        amount,
                    ),
                )
            item_added = True

        if DATABASE_URL:
            cur.execute("SELECT COALESCE(SUM(amount), 0) AS total_amount FROM user_keisan_items WHERE keisan_id = %s", (keisan_id,))
            total_amount = int((proxy_service_row_to_dict(cur.fetchone()) or {}).get('total_amount') or 0)
        else:
            cur.execute("SELECT COALESCE(SUM(amount), 0) AS total_amount FROM user_keisan_items WHERE keisan_id = ?", (keisan_id,))
            total_amount = int((proxy_service_row_to_dict(cur.fetchone()) or {}).get('total_amount') or 0)

        next_status = keisan.get('status') or status
        if item_added and next_status == 'completed':
            next_status = 'draft'
        if created_doc:
            next_status = status

        if DATABASE_URL:
            cur.execute(
                """
                UPDATE user_keisan
                SET recipient_name = %s,
                    subject = %s,
                    total_amount = %s,
                    notes = %s,
                    status = %s,
                    proxy_service_auction_id = %s,
                    updated_at = %s
                WHERE id = %s
                """,
                (
                    winner_name,
                    subject,
                    total_amount,
                    notes,
                    next_status,
                    auction_id,
                    updated_at_value,
                    keisan_id,
                ),
            )
        else:
            cur.execute(
                """
                UPDATE user_keisan
                SET recipient_name = ?,
                    subject = ?,
                    total_amount = ?,
                    notes = ?,
                    status = ?,
                    proxy_service_auction_id = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    winner_name,
                    subject,
                    total_amount,
                    notes,
                    next_status,
                    auction_id,
                    updated_at_value,
                    keisan_id,
                ),
            )
    finally:
        cur.close()

    return {
        'keisan_id': keisan_id,
        'created_doc': created_doc,
        'item_added': item_added,
    }


def create_proxy_service_reflected_item(conn, item, reflected_by_user_id, now=None, skip_keisan=False):
    now = now or get_jst_now()
    original_item_id = item.get('id')
    winner_user_id = item.get('winner_user_id') or item.get('highest_bid_user_id')
    winner_name = item.get('winner_name') or item.get('highest_bidder') or ''
    winning_price = int(item.get('result_price') or item.get('highest_bid') or item.get('sale_price') or 0)
    auction_id = item.get('auction_id')
    auction_name = item.get('auction_name') or '代行仕入れサービス'
    note_mode = 'fixed' if item.get('sale_mode') == 'fixed' or item.get('result_code') == 'fixed_sold' else 'auction'

    if not original_item_id or not winner_user_id or winning_price <= 0:
        raise ValueError('落札情報が不足しているため、クライアントへ反映できません')

    reflected_notes = append_proxy_service_origin_note(item.get('notes'), original_item_id, mode=note_mode)
    today = now.strftime('%Y-%m-%d')
    updated_at_value = now.strftime('%Y-%m-%d %H:%M:%S')

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        existing_reflected = lookup_proxy_service_reflected_item(cur, original_item_id, winner_user_id=winner_user_id)
        if existing_reflected:
            if existing_reflected.get('proxy_parent_item_id') != original_item_id:
                cur.execute(
                    """
                    UPDATE merchandise
                    SET proxy_parent_item_id = %s,
                        updated_by = %s,
                        updated_at = %s
                    WHERE id = %s
                    """,
                    (original_item_id, reflected_by_user_id, updated_at_value, existing_reflected['id']),
                )
            reflected_item_id = existing_reflected['id']
            created_reflected_item = False
        else:
            cur.execute(
                """
                INSERT INTO merchandise (
                    user_id, purchase_date, photo_path, product_name, brand_name,
                    item_condition, store_name, supplier_detail, wholesale_price, wholesale_fee_rate,
                    purchase_price, payment_method, listing_price, expected_shipping,
                    expected_commission, model_number, additional_photos, is_listed, notes,
                    proxy_parent_item_id, updated_by, updated_at
                ) VALUES (
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s
                ) RETURNING id
                """,
                (
                    winner_user_id,
                    today,
                    item.get('photo_path'),
                    item.get('product_name'),
                    item.get('brand_name'),
                    item.get('item_condition'),
                    '代行仕入れサービス',
                    '代行仕入れサービス',
                    winning_price,
                    0,
                    winning_price,
                    '代行仕入れ',
                    item.get('listing_price') or 0,
                    item.get('expected_shipping') or 0,
                    item.get('expected_commission') or 0,
                    item.get('model_number'),
                    item.get('additional_photos'),
                    False,
                    reflected_notes,
                    original_item_id,
                    reflected_by_user_id,
                    updated_at_value,
                ),
            )
            reflected_item_id = cur.fetchone()['id']
            created_reflected_item = True
        cur.close()
    else:
        cur = conn.cursor()
        existing_reflected = lookup_proxy_service_reflected_item(cur, original_item_id, winner_user_id=winner_user_id)
        if existing_reflected:
            if existing_reflected.get('proxy_parent_item_id') != original_item_id:
                cur.execute(
                    """
                    UPDATE merchandise
                    SET proxy_parent_item_id = ?,
                        updated_by = ?,
                        updated_at = ?
                    WHERE id = ?
                    """,
                    (original_item_id, reflected_by_user_id, updated_at_value, existing_reflected['id']),
                )
            reflected_item_id = existing_reflected['id']
            created_reflected_item = False
        else:
            cur.execute(
                """
                INSERT INTO merchandise (
                    user_id, purchase_date, photo_path, product_name, brand_name,
                    item_condition, store_name, supplier_detail, wholesale_price, wholesale_fee_rate,
                    purchase_price, payment_method, listing_price, expected_shipping,
                    expected_commission, model_number, additional_photos, is_listed, notes,
                    proxy_parent_item_id, updated_by, updated_at
                ) VALUES (
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?, ?,
                    ?, ?, ?, ?, ?,
                    ?, ?, ?
                )
                """,
                (
                    winner_user_id,
                    today,
                    item.get('photo_path'),
                    item.get('product_name'),
                    item.get('brand_name'),
                    item.get('item_condition'),
                    '代行仕入れサービス',
                    '代行仕入れサービス',
                    winning_price,
                    0,
                    winning_price,
                    '代行仕入れ',
                    item.get('listing_price') or 0,
                    item.get('expected_shipping') or 0,
                    item.get('expected_commission') or 0,
                    item.get('model_number'),
                    item.get('additional_photos'),
                    0,
                    reflected_notes,
                    original_item_id,
                    reflected_by_user_id,
                    updated_at_value,
                ),
            )
            reflected_item_id = cur.lastrowid
            created_reflected_item = True
        cur.close()

    keisan_result = None
    if not skip_keisan and auction_id and reflected_item_id:
        keisan_result = upsert_proxy_service_keisan_document(
            conn,
            auction_id=auction_id,
            auction_name=auction_name,
            winner_user_id=winner_user_id,
            winner_name=winner_name,
            reflected_item_id=reflected_item_id,
            source_item=item,
            amount=winning_price,
            now=now,
            status='draft',
        )

    return {
        'created': created_reflected_item,
        'reflected_item_id': reflected_item_id,
        'winner_user_id': winner_user_id,
        'winner_name': winner_name,
        'keisan_id': (keisan_result or {}).get('keisan_id'),
        'keisan_created': (keisan_result or {}).get('created_doc', False),
        'keisan_item_added': (keisan_result or {}).get('item_added', False),
    }


def fetch_proxy_service_source_item_map(conn, item_ids):
    item_ids = [int(item_id) for item_id in set(item_ids or []) if item_id]
    if not item_ids:
        return {}

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        placeholders = ','.join(['%s'] * len(item_ids))
        cur.execute(
            f"""
            SELECT m.id, m.auction_id, m.photo_path, m.additional_photos, m.product_name, m.brand_name,
                   m.item_condition, m.purchase_price, m.listing_price, m.model_number, m.sale_date, m.sale_price,
                   m.sale_type, m.sales_destination, m.show_in_proxy_service, m.expected_shipping,
                   m.expected_commission, m.notes, ps.auction_name, COALESCE(ps.sale_mode, 'auction') AS sale_mode
            FROM merchandise m
            LEFT JOIN proxy_service_settings ps ON ps.id = m.auction_id
            WHERE m.id IN ({placeholders})
            """,
            tuple(item_ids),
        )
        rows = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        placeholders = ','.join(['?'] * len(item_ids))
        cur.execute(
            f"""
            SELECT m.id, m.auction_id, m.photo_path, m.additional_photos, m.product_name, m.brand_name,
                   m.item_condition, m.purchase_price, m.listing_price, m.model_number, m.sale_date, m.sale_price,
                   m.sale_type, m.sales_destination, m.show_in_proxy_service, m.expected_shipping,
                   m.expected_commission, m.notes, ps.auction_name, COALESCE(ps.sale_mode, 'auction') AS sale_mode
            FROM merchandise m
            LEFT JOIN proxy_service_settings ps ON ps.id = m.auction_id
            WHERE m.id IN ({placeholders})
            """,
            tuple(item_ids),
        )
        rows = [dict(row) for row in cur.fetchall()]

    cur.close()
    return {row['id']: row for row in rows}


def submit_proxy_service_keisan_document(conn, keisan_id, actor_user_id, now=None):
    now = now or get_jst_now()
    ensure_proxy_service_keisan_columns(conn)
    today = now.strftime('%Y-%m-%d')
    updated_at_value = now.strftime('%Y-%m-%d %H:%M:%S')

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute(
            """
            SELECT k.*, u.display_name AS user_name, u.username,
                   ps.auction_name, COALESCE(ps.sale_mode, 'auction') AS sale_mode
            FROM user_keisan k
            JOIN users u ON u.id = k.user_id
            LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
            WHERE k.id = %s AND k.is_admin_created = TRUE
            """,
            (keisan_id,),
        )
        keisan = proxy_service_row_to_dict(cur.fetchone())
        if not keisan:
            cur.close()
            raise ValueError('計算書が見つかりません')
        cur.execute(
            """
            SELECT ki.*, COALESCE(ki.proxy_source_item_id, reflected.proxy_parent_item_id) AS source_item_id
            FROM user_keisan_items ki
            LEFT JOIN merchandise reflected ON reflected.id = ki.merchandise_id
            WHERE ki.keisan_id = %s
            ORDER BY ki.item_no
            """,
            (keisan_id,),
        )
        items = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT k.*, u.display_name AS user_name, u.username,
                   ps.auction_name, COALESCE(ps.sale_mode, 'auction') AS sale_mode
            FROM user_keisan k
            JOIN users u ON u.id = k.user_id
            LEFT JOIN proxy_service_settings ps ON ps.id = k.proxy_service_auction_id
            WHERE k.id = ? AND k.is_admin_created = 1
            """,
            (keisan_id,),
        )
        keisan = proxy_service_row_to_dict(cur.fetchone())
        if not keisan:
            cur.close()
            raise ValueError('計算書が見つかりません')
        cur.execute(
            """
            SELECT ki.*, COALESCE(ki.proxy_source_item_id, reflected.proxy_parent_item_id) AS source_item_id
            FROM user_keisan_items ki
            LEFT JOIN merchandise reflected ON reflected.id = ki.merchandise_id
            WHERE ki.keisan_id = ?
            ORDER BY ki.item_no
            """,
            (keisan_id,),
        )
        items = [dict(row) for row in cur.fetchall()]

    if not items:
        cur.close()
        raise ValueError('計算書に商品が入っていません')

    source_item_ids = [item.get('source_item_id') for item in items if item.get('source_item_id')]
    source_item_map = fetch_proxy_service_source_item_map(conn, source_item_ids)
    missing_source_ids = [item_id for item_id in source_item_ids if item_id not in source_item_map]
    if missing_source_ids:
        cur.close()
        raise ValueError('元商品が見つからないため送付できません')

    winner_name = keisan.get('recipient_name') or keisan.get('user_name') or keisan.get('username') or ''
    reflected_count = 0
    updated_source_ids = set()

    for item in items:
        source_item_id = item.get('source_item_id')
        if not source_item_id:
            continue

        reflected_item_id = item.get('merchandise_id')
        if reflected_item_id:
            if DATABASE_URL:
                cur.execute("SELECT id FROM merchandise WHERE id = %s", (reflected_item_id,))
                existing_reflected = proxy_service_row_to_dict(cur.fetchone())
            else:
                cur.execute("SELECT id FROM merchandise WHERE id = ?", (reflected_item_id,))
                existing_reflected = proxy_service_row_to_dict(cur.fetchone())
            if not existing_reflected:
                reflected_item_id = None

        if not reflected_item_id:
            unit_price = int(item.get('unit_price') or 0)
            amount = int(item.get('amount') or 0)
            result_price = unit_price or amount
            source_item = dict(source_item_map.get(source_item_id) or {})
            source_item.update({
                'winner_user_id': keisan.get('user_id'),
                'winner_name': winner_name,
                'result_price': result_price,
                'auction_id': keisan.get('proxy_service_auction_id') or source_item.get('auction_id'),
                'auction_name': keisan.get('auction_name') or source_item.get('auction_name') or '代行仕入れサービス',
                'sale_mode': keisan.get('sale_mode') or source_item.get('sale_mode') or 'auction',
            })
            reflection_result = create_proxy_service_reflected_item(
                conn,
                source_item,
                actor_user_id,
                now=now,
                skip_keisan=True,
            )
            reflected_item_id = reflection_result.get('reflected_item_id')
            if reflection_result.get('created'):
                reflected_count += 1

        source_sale_price = int(item.get('unit_price') or item.get('amount') or 0)
        destination_name = winner_name or keisan.get('user_name') or keisan.get('username') or ''
        destination_prefix = '代行仕入れ購入' if (keisan.get('sale_mode') or '') == 'fixed' else '代行仕入れ落札'
        sales_destination = f'{destination_prefix}: {destination_name}' if destination_name else ''

        if DATABASE_URL:
            cur.execute(
                """
                UPDATE merchandise
                SET purchase_date = %s,
                    proxy_parent_item_id = %s,
                    wholesale_price = CASE
                        WHEN COALESCE(wholesale_price, 0) <= 0 THEN %s
                        ELSE wholesale_price
                    END,
                    purchase_price = CASE
                        WHEN COALESCE(purchase_price, 0) <= 0 THEN %s
                        ELSE purchase_price
                    END,
                    updated_by = %s,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
                """,
                (today, source_item_id, source_sale_price, source_sale_price, actor_user_id, reflected_item_id),
            )
            cur.execute(
                """
                UPDATE user_keisan_items
                SET merchandise_id = %s,
                    proxy_source_item_id = %s
                WHERE id = %s
                """,
                (reflected_item_id, source_item_id, item['id']),
            )
            cur.execute(
                """
                UPDATE merchandise
                SET sale_date = %s,
                    sale_price = CASE
                        WHEN COALESCE(sale_price, 0) <= 0 THEN %s
                        ELSE sale_price
                    END,
                    sales_destination = CASE
                        WHEN COALESCE(NULLIF(sales_destination, ''), '') = '' THEN %s
                        ELSE sales_destination
                    END,
                    show_in_proxy_service = FALSE,
                    updated_by = %s,
                    updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
                """,
                (today, source_sale_price, sales_destination, actor_user_id, source_item_id),
            )
        else:
            cur.execute(
                """
                UPDATE merchandise
                SET purchase_date = ?,
                    proxy_parent_item_id = ?,
                    wholesale_price = CASE
                        WHEN COALESCE(wholesale_price, 0) <= 0 THEN ?
                        ELSE wholesale_price
                    END,
                    purchase_price = CASE
                        WHEN COALESCE(purchase_price, 0) <= 0 THEN ?
                        ELSE purchase_price
                    END,
                    updated_by = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    today,
                    source_item_id,
                    source_sale_price,
                    source_sale_price,
                    actor_user_id,
                    updated_at_value,
                    reflected_item_id,
                ),
            )
            cur.execute(
                """
                UPDATE user_keisan_items
                SET merchandise_id = ?,
                    proxy_source_item_id = ?
                WHERE id = ?
                """,
                (reflected_item_id, source_item_id, item['id']),
            )
            cur.execute(
                """
                UPDATE merchandise
                SET sale_date = ?,
                    sale_price = CASE
                        WHEN COALESCE(sale_price, 0) <= 0 THEN ?
                        ELSE sale_price
                    END,
                    sales_destination = CASE
                        WHEN COALESCE(NULLIF(sales_destination, ''), '') = '' THEN ?
                        ELSE sales_destination
                    END,
                    show_in_proxy_service = 0,
                    updated_by = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (today, source_sale_price, sales_destination, actor_user_id, updated_at_value, source_item_id),
            )
        updated_source_ids.add(source_item_id)

    if DATABASE_URL:
        cur.execute(
            """
            UPDATE user_keisan
            SET status = 'submitted',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s AND is_admin_created = TRUE
            """,
            (keisan_id,),
        )
    else:
        cur.execute(
            """
            UPDATE user_keisan
            SET status = 'submitted',
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ? AND is_admin_created = 1
            """,
            (keisan_id,),
        )

    cur.close()
    return {
        'reflected_count': reflected_count,
        'updated_source_count': len(updated_source_ids),
        'auction_id': keisan.get('proxy_service_auction_id'),
    }


def prepare_proxy_service_keisan_for_item(conn, item, now=None, status='draft'):
    now = now or get_jst_now()
    item_dict = dict(item or {})
    auction_id = item_dict.get('auction_id')
    winner_user_id = item_dict.get('winner_user_id') or item_dict.get('highest_bid_user_id')
    winner_name = (
        item_dict.get('winner_name')
        or item_dict.get('highest_bidder')
        or extract_proxy_service_purchase_buyer_name(item_dict.get('sales_destination'))
        or ''
    )
    amount = normalize_proxy_service_price_value(
        item_dict.get('result_price')
        or item_dict.get('highest_bid')
        or item_dict.get('sale_price')
        or item_dict.get('listing_price')
        or item_dict.get('purchase_price')
    )
    auction_name = item_dict.get('auction_name') or '代行仕入れサービス'

    if not auction_id:
        raise ValueError('オークション情報が不足しているため、計算書へ追加できません')
    if not winner_user_id:
        raise ValueError('落札ユーザーが確定していないため、計算書へ追加できません')
    if amount <= 0:
        raise ValueError('落札金額が不足しているため、計算書へ追加できません')

    return upsert_proxy_service_keisan_document(
        conn,
        auction_id=auction_id,
        auction_name=auction_name,
        winner_user_id=winner_user_id,
        winner_name=winner_name,
        source_item=item_dict,
        amount=amount,
        reflected_item_id=None,
        now=now,
        status=status,
    )


def get_proxy_service_auction_state(settings, now=None):
    settings_dict = dict(settings or {})
    now = now or get_jst_now()
    start_dt = parse_proxy_service_datetime(settings_dict.get('start_datetime'))
    end_dt = parse_proxy_service_datetime(settings_dict.get('end_datetime'))
    is_public = bool(settings_dict.get('is_public'))
    sale_mode = settings_dict.get('sale_mode') or 'auction'

    is_not_started = bool(start_dt and now < start_dt)
    is_ended = bool(end_dt and now >= end_dt)
    is_open = is_public and not is_not_started and not is_ended

    if not is_public:
        status = 'private'
        status_label = '非公開'
    elif is_not_started:
        status = 'scheduled'
        status_label = '開始前'
    elif is_ended:
        status = 'ended'
        status_label = '締切済み'
    else:
        status = 'open'
        status_label = '公開中'

    return {
        'status': status,
        'status_label': status_label,
        'is_public': is_public,
        'sale_mode': sale_mode,
        'start_datetime': start_dt,
        'end_datetime': end_dt,
        'is_not_started': is_not_started,
        'is_ended': is_ended,
        'is_open': is_open,
        'has_schedule': bool(start_dt or end_dt),
        'has_started': not is_not_started,
    }


def normalize_proxy_service_price_value(value):
    try:
        normalized = int(value or 0)
    except (TypeError, ValueError):
        return 0
    return max(0, normalized)


def extract_proxy_service_price_input(data, key):
    if data is None:
        return False, 0

    try:
        has_key = key in data
    except TypeError:
        has_key = data.get(key) is not None

    if not has_key:
        return False, 0

    return True, normalize_proxy_service_price_value(data.get(key))


def resolve_proxy_service_admin_pricing(item_data, sale_mode, data=None):
    item = proxy_service_row_to_dict(item_data) or {}
    has_listing_input, listing_input = extract_proxy_service_price_input(data, 'listing_price')
    has_max_input, max_input = extract_proxy_service_price_input(data, 'proxy_auction_max_price')

    current_listing_price = normalize_proxy_service_price_value(item.get('listing_price'))
    current_max_price = normalize_proxy_service_price_value(item.get('proxy_auction_max_price'))
    purchase_price = normalize_proxy_service_price_value(item.get('purchase_price'))

    default_listing_price = current_listing_price or purchase_price
    next_listing_price = listing_input if has_listing_input else default_listing_price
    if next_listing_price <= 0 and purchase_price > 0:
        next_listing_price = purchase_price

    next_max_price = max_input if has_max_input else current_max_price

    if purchase_price and next_listing_price < purchase_price:
        raise ValueError(f'開始価格・販売価格は仕入れ価格（¥{purchase_price:,}）以上で設定してください')

    if sale_mode == 'fixed':
        next_max_price = 0
    elif next_max_price and next_max_price < next_listing_price:
        raise ValueError(f'最高価格は開始価格（¥{next_listing_price:,}）以上で設定してください')

    return {
        'listing_price': next_listing_price,
        'proxy_auction_max_price': next_max_price,
        'purchase_price': purchase_price,
        'display_listing_price': f'¥{next_listing_price:,}' if next_listing_price else '¥0',
        'display_max_price': f'¥{next_max_price:,}' if next_max_price else '未設定',
        'default_listing_price': default_listing_price,
    }


def finalize_proxy_service_buyout(cur, merchandise_id, winner_user_id, winner_name, winning_bid, actor_user_id, now=None, is_postgres=False):
    now = now or get_jst_now()
    sale_destination = f'最高価格到達: {winner_name}' if winner_name else '最高価格到達'

    if is_postgres:
        cur.execute("""
            UPDATE merchandise
            SET sale_date = %s,
                sale_price = %s,
                sale_type = 'auction_buyout',
                sales_destination = %s,
                show_in_proxy_service = FALSE,
                updated_by = %s,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = %s AND sale_date IS NULL
        """, (now.date(), winning_bid, sale_destination, actor_user_id, merchandise_id))
        if cur.rowcount == 0:
            return False
        cur.execute("""
            UPDATE users
            SET proxy_service_budget = GREATEST(0, COALESCE(proxy_service_budget, 0) - %s)
            WHERE id = %s
        """, (winning_bid, winner_user_id))
        return True

    cur.execute("""
        UPDATE merchandise
        SET sale_date = ?,
            sale_price = ?,
            sale_type = 'auction_buyout',
            sales_destination = ?,
            show_in_proxy_service = 0,
            updated_by = ?,
            updated_at = ?
        WHERE id = ? AND sale_date IS NULL
    """, (
        now.strftime('%Y-%m-%d'),
        winning_bid,
        sale_destination,
        actor_user_id,
        now.strftime('%Y-%m-%d %H:%M:%S'),
        merchandise_id,
    ))
    if cur.rowcount == 0:
        return False
    cur.execute("""
        UPDATE users
        SET proxy_service_budget = MAX(0, COALESCE(proxy_service_budget, 0) - ?)
        WHERE id = ?
    """, (winning_bid, winner_user_id))
    return True


def fetch_proxy_service_items(conn, auction_id):
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("""
            SELECT m.id, m.user_id, m.photo_path, m.additional_photos, m.product_name, m.brand_name,
                   m.item_condition, m.purchase_price, m.listing_price, m.model_number, m.sale_date, m.sale_price,
                   m.sale_type, m.sales_destination, m.show_in_proxy_service, m.auction_id,
                   m.expected_shipping, m.expected_commission, m.notes, m.proxy_auction_max_price,
                   COALESCE(u.display_name, u.username, '不明') as owner_name,
                   (SELECT bid_amount FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bid,
                   (SELECT bidder_name FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bidder,
                   (SELECT user_id FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bid_user_id,
                   (SELECT COUNT(*) FROM proxy_service_bids WHERE merchandise_id = m.id) as bid_count,
                   (SELECT MAX(created_at) FROM proxy_service_bids WHERE merchandise_id = m.id) as last_bid_at,
                   (SELECT child.id FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_item_id,
                   (SELECT child.user_id FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_user_id,
                   (SELECT COALESCE(u2.display_name, u2.username, '不明')
                    FROM merchandise child
                    LEFT JOIN users u2 ON u2.id = child.user_id
                    WHERE child.proxy_parent_item_id = m.id
                    ORDER BY child.id DESC
                    LIMIT 1) as reflected_user_name,
                   (SELECT child.created_at FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_at
            FROM merchandise m
            LEFT JOIN users u ON m.user_id = u.id
            WHERE m.auction_id = %s
              AND (m.user_id IS NULL OR COALESCE(u.role, '') NOT IN ('user'))
            ORDER BY CASE WHEN m.sale_date IS NULL THEN 0 ELSE 1 END, m.id DESC
        """, (auction_id,))
        items = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        cur.execute("""
            SELECT m.id, m.user_id, m.photo_path, m.additional_photos, m.product_name, m.brand_name,
                   m.item_condition, m.purchase_price, m.listing_price, m.model_number, m.sale_date, m.sale_price,
                   m.sale_type, m.sales_destination, m.show_in_proxy_service, m.auction_id,
                   m.expected_shipping, m.expected_commission, m.notes, m.proxy_auction_max_price,
                   COALESCE(u.display_name, u.username, '不明') as owner_name,
                   (SELECT bid_amount FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bid,
                   (SELECT bidder_name FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bidder,
                   (SELECT user_id FROM proxy_service_bids WHERE merchandise_id = m.id ORDER BY bid_amount DESC, id ASC LIMIT 1) as highest_bid_user_id,
                   (SELECT COUNT(*) FROM proxy_service_bids WHERE merchandise_id = m.id) as bid_count,
                   (SELECT MAX(created_at) FROM proxy_service_bids WHERE merchandise_id = m.id) as last_bid_at,
                   (SELECT child.id FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_item_id,
                   (SELECT child.user_id FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_user_id,
                   (SELECT COALESCE(u2.display_name, u2.username, '不明')
                    FROM merchandise child
                    LEFT JOIN users u2 ON u2.id = child.user_id
                    WHERE child.proxy_parent_item_id = m.id
                    ORDER BY child.id DESC
                    LIMIT 1) as reflected_user_name,
                   (SELECT child.created_at FROM merchandise child WHERE child.proxy_parent_item_id = m.id ORDER BY child.id DESC LIMIT 1) as reflected_at
            FROM merchandise m
            LEFT JOIN users u ON m.user_id = u.id
            WHERE m.auction_id = ?
              AND (m.user_id IS NULL OR COALESCE(u.role, '') NOT IN ('user'))
            ORDER BY CASE WHEN m.sale_date IS NULL THEN 0 ELSE 1 END, m.id DESC
        """, (auction_id,))
        items = [dict(row) for row in cur.fetchall()]

    cur.close()
    return hydrate_proxy_service_reflection_state(conn, items)


def annotate_proxy_service_items(items, settings, now=None, current_user_id=None):
    auction_state = get_proxy_service_auction_state(settings, now=now)
    sale_mode = auction_state['sale_mode']
    winner_result_codes = {'auction_closed_with_bid', 'auction_finalized', 'fixed_sold'}

    annotated_items = []
    winner_results = []
    summary = {
        'total_items': 0,
        'active_count': 0,
        'sold_count': 0,
        'winner_count': 0,
        'pending_finalize_count': 0,
        'pending_reflection_count': 0,
        'reflected_count': 0,
        'no_bid_count': 0,
    }

    for raw_item in items or []:
        item = dict(raw_item)
        bid_count = int(item.get('bid_count') or 0)
        highest_bid = item.get('highest_bid')
        sale_price = item.get('sale_price')
        purchase_price = normalize_proxy_service_price_value(item.get('purchase_price'))
        listing_price = normalize_proxy_service_price_value(item.get('listing_price'))
        max_price = normalize_proxy_service_price_value(item.get('proxy_auction_max_price'))
        winner_user_id = item.get('highest_bid_user_id')
        winner_name = item.get('highest_bidder')
        is_sold = bool(item.get('sale_date'))
        is_buyout_sale = bool((item.get('sale_type') or '') == 'auction_buyout')

        result_code = 'scheduled'
        status_label = '開始前'
        status_class = 'scheduled'
        ended_method_label = ''
        result_price = highest_bid or sale_price or listing_price or purchase_price or 0

        if sale_mode == 'fixed':
            purchase_buyer_name = extract_proxy_service_purchase_buyer_name(item.get('sales_destination'))
            if purchase_buyer_name:
                winner_name = purchase_buyer_name

            if is_sold:
                result_code = 'fixed_sold'
                status_label = '購入成立'
                status_class = 'won'
                ended_method_label = '即決購入'
                result_price = sale_price or highest_bid or item.get('listing_price') or 0
            elif auction_state['is_ended']:
                result_code = 'fixed_closed_unsold'
                status_label = '販売終了'
                status_class = 'closed'
                ended_method_label = '時間締切'
                result_price = item.get('listing_price') or 0
            elif auction_state['is_open']:
                result_code = 'fixed_open'
                status_label = '販売中'
                status_class = 'open'
                result_price = item.get('listing_price') or 0
        else:
            if is_sold and highest_bid:
                result_code = 'auction_finalized'
                status_label = '売り切れ' if is_buyout_sale else '落札確定'
                status_class = 'won'
                ended_method_label = '最高価格到達' if is_buyout_sale else '管理画面で落札確定'
                result_price = sale_price or highest_bid
            elif auction_state['is_ended'] and highest_bid:
                result_code = 'auction_finalized'
                status_label = '落札確定'
                status_class = 'won'
                ended_method_label = '時間締切'
                result_price = highest_bid
            elif auction_state['is_ended']:
                result_code = 'auction_closed_no_bid'
                status_label = '入札なし'
                status_class = 'muted'
                ended_method_label = '時間締切'
                result_price = None
            elif auction_state['is_open']:
                result_code = 'auction_open'
                status_label = '入札受付中'
                status_class = 'open'
                result_price = highest_bid or item.get('listing_price') or 0

        reflected_item_id = item.get('reflected_item_id')
        is_reflected_to_client = bool(reflected_item_id)
        reflected_user_name = item.get('reflected_user_name') or winner_name
        reflected_at_display = format_optional_datetime(item.get('reflected_at'), fallback='-')

        if is_reflected_to_client and result_code == 'fixed_sold':
            reflection_status_label = '自動反映済み'
            reflection_status_class = 'won'
        elif is_reflected_to_client:
            reflection_status_label = '反映済み'
            reflection_status_class = 'won'
        elif result_code == 'auction_finalized':
            reflection_status_label = '未反映'
            reflection_status_class = 'scheduled'
        elif result_code == 'auction_closed_with_bid':
            reflection_status_label = '未反映'
            reflection_status_class = 'scheduled'
        elif result_code == 'fixed_sold':
            reflection_status_label = '要確認'
            reflection_status_class = 'scheduled'
        else:
            reflection_status_label = '対象外'
            reflection_status_class = 'muted'

        item['bid_count'] = bid_count
        item['has_bid'] = bid_count > 0
        item['is_sold'] = is_sold
        item['purchase_price'] = purchase_price
        item['minimum_listing_price'] = purchase_price
        item['default_listing_price'] = listing_price or purchase_price
        item['price_label'] = '販売価格' if sale_mode == 'fixed' else '開始価格'
        item['proxy_auction_max_price'] = max_price
        item['has_proxy_auction_max_price'] = bool(max_price > 0 and sale_mode == 'auction')
        item['is_buyout_sale'] = is_buyout_sale
        item['sold_message'] = '最高価格に到達したため売り切れました' if is_buyout_sale else '売り切れました'
        item['winner_user_id'] = winner_user_id
        item['winner_name'] = winner_name
        item['result_code'] = result_code
        item['status_label'] = status_label
        item['status_class'] = status_class
        item['ended_method_label'] = ended_method_label
        item['result_price'] = result_price
        item['is_action_locked'] = not auction_state['is_open'] or is_sold
        item['is_user_winner'] = bool(current_user_id and winner_user_id == current_user_id and result_code in winner_result_codes)
        item['user_result_label'] = '購入成立' if result_code == 'fixed_sold' else '落札'
        item['is_reflected_to_client'] = is_reflected_to_client
        item['reflection_status_label'] = reflection_status_label
        item['reflection_status_class'] = reflection_status_class
        item['reflected_item_id'] = reflected_item_id
        item['reflected_user_name'] = reflected_user_name
        item['reflected_at_display'] = reflected_at_display
        item['can_reflect_to_client'] = bool(result_code == 'auction_finalized' and not is_reflected_to_client)
        annotated_items.append(item)

        summary['total_items'] += 1
        if result_code in ('auction_open', 'fixed_open'):
            summary['active_count'] += 1
        if is_sold:
            summary['sold_count'] += 1
        if result_code in ('auction_closed_with_bid', 'auction_finalized', 'fixed_sold'):
            summary['winner_count'] += 1
        if item['can_reflect_to_client']:
            summary['pending_reflection_count'] += 1
        if is_reflected_to_client:
            summary['reflected_count'] += 1
        if result_code in ('auction_closed_no_bid', 'fixed_closed_unsold'):
            summary['no_bid_count'] += 1

        if item['is_user_winner']:
            winner_results.append(item)

    return annotated_items, summary, winner_results


def fetch_proxy_service_target_users(conn, auction_id):
    ensure_proxy_service_auction_user_table(conn)
    use_auction_scope = proxy_service_auction_has_user_config(conn, auction_id)

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        if use_auction_scope:
            cur.execute(
                """
                SELECT u.id, u.username, u.display_name, u.role,
                       CASE
                           WHEN psu.user_id IS NOT NULL AND COALESCE(psu.is_enabled, TRUE) = TRUE THEN TRUE
                           ELSE FALSE
                       END AS is_selected
                FROM users u
                LEFT JOIN proxy_service_auction_users psu
                  ON u.id = psu.user_id
                 AND psu.auction_id = %s
                ORDER BY
                    CASE u.role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 ELSE 3 END,
                    u.id
                """,
                (auction_id,),
            )
        else:
            cur.execute(
                """
                SELECT u.id, u.username, u.display_name, u.role,
                       CASE WHEN psu.user_id IS NOT NULL THEN TRUE ELSE FALSE END AS is_selected
                FROM users u
                LEFT JOIN proxy_service_users psu ON u.id = psu.user_id
                ORDER BY
                    CASE u.role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 ELSE 3 END,
                    u.id
                """
            )
        users = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        if use_auction_scope:
            cur.execute(
                """
                SELECT u.id, u.username, u.display_name, u.role,
                       CASE
                           WHEN psu.user_id IS NOT NULL AND COALESCE(psu.is_enabled, 1) = 1 THEN 1
                           ELSE 0
                       END AS is_selected
                FROM users u
                LEFT JOIN proxy_service_auction_users psu
                  ON u.id = psu.user_id
                 AND psu.auction_id = ?
                ORDER BY
                    CASE u.role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 ELSE 3 END,
                    u.id
                """,
                (auction_id,),
            )
        else:
            cur.execute(
                """
                SELECT u.id, u.username, u.display_name, u.role,
                       CASE WHEN psu.user_id IS NOT NULL THEN 1 ELSE 0 END AS is_selected
                FROM users u
                LEFT JOIN proxy_service_users psu ON u.id = psu.user_id
                ORDER BY
                    CASE u.role WHEN 'owner' THEN 1 WHEN 'admin' THEN 2 ELSE 3 END,
                    u.id
                """
            )
        users = [dict(row) for row in cur.fetchall()]

    cur.close()
    return users, use_auction_scope


def build_proxy_service_live_snapshot(items, auction_state):
    snapshot_items = []
    for item in items or []:
        snapshot_items.append({
            'id': item.get('id'),
            'is_sold': bool(item.get('is_sold')),
            'highest_bid': normalize_proxy_service_price_value(item.get('highest_bid')),
            'highest_bidder': item.get('highest_bidder') or '',
            'result_price': normalize_proxy_service_price_value(item.get('result_price')),
            'bid_count': int(item.get('bid_count') or 0),
            'status_label': item.get('status_label') or '',
            'ended_method_label': item.get('ended_method_label') or '',
        })

    return {
        'auction_status': auction_state.get('status'),
        'sale_mode': auction_state.get('sale_mode'),
        'item_count': len(snapshot_items),
        'items': snapshot_items,
    }


def decorate_proxy_service_result_items(conn, auction_id, result_items):
    keisan_doc_map = fetch_proxy_service_keisan_doc_map(conn, auction_id=auction_id)
    keisan_item_map = fetch_proxy_service_keisan_item_map(conn, auction_id=auction_id)
    keisan_summary = {
        'total_docs': 0,
        'draft_count': 0,
        'completed_count': 0,
        'submitted_count': 0,
    }
    action_summary = {
        'pending_prepare_count': 0,
        'prepared_count': 0,
        'submitted_count': 0,
        'needs_attention_count': 0,
    }

    for doc in keisan_doc_map.values():
        keisan_summary['total_docs'] += 1
        if doc.get('status') == 'submitted':
            keisan_summary['submitted_count'] += 1
        elif doc.get('status') == 'completed':
            keisan_summary['completed_count'] += 1
        else:
            keisan_summary['draft_count'] += 1

    for item in result_items:
        keisan_item = keisan_item_map.get(item.get('id'))
        item['is_in_keisan_doc'] = bool(keisan_item)
        item['keisan_doc_id'] = keisan_item.get('keisan_id') if keisan_item else None
        item['keisan_doc_no'] = keisan_item.get('document_no') if keisan_item else ''
        item['keisan_status_label'] = keisan_item.get('status_label') if keisan_item else ''
        item['keisan_status_class'] = keisan_item.get('status_class') if keisan_item else 'muted'
        item['keisan_issue_date_display'] = keisan_item.get('issue_date') if keisan_item else '-'
        item['can_prepare_keisan'] = bool(
            item.get('result_code') in ('auction_finalized', 'fixed_sold')
            and not keisan_item
            and not item.get('is_reflected_to_client')
        )

        if item.get('is_reflected_to_client'):
            item['reflection_status_label'] = '商品反映済み'
            item['reflection_status_class'] = 'won'
            if item.get('result_code') in ('auction_finalized', 'fixed_sold'):
                action_summary['submitted_count'] += 1
        elif keisan_item and keisan_item.get('status') == 'submitted':
            item['reflection_status_label'] = '書類送付済み'
            item['reflection_status_class'] = 'won'
            if item.get('result_code') in ('auction_finalized', 'fixed_sold'):
                action_summary['submitted_count'] += 1
        elif keisan_item and keisan_item.get('status') == 'completed':
            item['reflection_status_label'] = '送付待ち'
            item['reflection_status_class'] = 'scheduled'
            action_summary['prepared_count'] += 1
            action_summary['needs_attention_count'] += 1
        elif keisan_item:
            item['reflection_status_label'] = '書類作成中'
            item['reflection_status_class'] = 'scheduled'
            action_summary['pending_prepare_count'] += 1
            action_summary['needs_attention_count'] += 1
        elif item.get('result_code') == 'auction_finalized':
            item['reflection_status_label'] = '書類未追加'
            item['reflection_status_class'] = 'scheduled'
            action_summary['pending_prepare_count'] += 1
            action_summary['needs_attention_count'] += 1
        elif item.get('result_code') == 'fixed_sold':
            item['reflection_status_label'] = '書類未作成'
            item['reflection_status_class'] = 'scheduled'
            action_summary['pending_prepare_count'] += 1
            action_summary['needs_attention_count'] += 1
        elif item.get('result_code') == 'auction_closed_with_bid':
            item['reflection_status_label'] = '計算書未作成'
            item['reflection_status_class'] = 'scheduled'
        else:
            item['reflection_status_label'] = item.get('reflection_status_label') or '対象外'
            item['reflection_status_class'] = item.get('reflection_status_class') or 'muted'

    for item in result_items:
        keisan_item = keisan_item_map.get(item.get('id'))
        if item.get('is_reflected_to_client'):
            item['reflection_status_label'] = '商品反映済み'
            item['reflection_status_class'] = 'won'
        elif keisan_item and keisan_item.get('status') == 'submitted':
            item['reflection_status_label'] = '書類送付済み'
            item['reflection_status_class'] = 'won'
        elif keisan_item and keisan_item.get('status') == 'completed':
            item['reflection_status_label'] = '送付準備完了'
            item['reflection_status_class'] = 'scheduled'
        elif keisan_item:
            item['reflection_status_label'] = '書類下書き'
            item['reflection_status_class'] = 'scheduled'
        elif item.get('result_code') in ('auction_finalized', 'fixed_sold'):
            item['reflection_status_label'] = '書類未作成'
            item['reflection_status_class'] = 'scheduled'
        elif item.get('result_code') == 'auction_closed_with_bid':
            item['reflection_status_label'] = '計算書未作成'
            item['reflection_status_class'] = 'scheduled'
        else:
            item['reflection_status_label'] = item.get('reflection_status_label') or '対象外'
            item['reflection_status_class'] = item.get('reflection_status_class') or 'muted'

    return result_items, keisan_summary, action_summary


def build_proxy_service_client_document_groups(result_items, keisan_doc_map, auction_id):
    groups = {}

    for raw_item in result_items or []:
        item = dict(raw_item or {})
        winner_user_id = item.get('winner_user_id')
        if not winner_user_id:
            continue

        result_code = item.get('result_code')
        if result_code not in {'auction_finalized', 'fixed_sold'}:
            continue

        group = groups.setdefault(
            winner_user_id,
            {
                'winner_user_id': winner_user_id,
                'winner_name': item.get('winner_name') or '未設定',
                'won_items': [],
                'needs_prepare_count': 0,
                'reflected_item_count': 0,
                'submitted_item_count': 0,
                'draft_item_count': 0,
                'completed_item_count': 0,
                'total_amount': 0,
                'item_names': [],
            },
        )

        group['won_items'].append(item)
        group['total_amount'] += int(item.get('result_price') or 0)
        if item.get('product_name'):
            group['item_names'].append(item.get('product_name'))
        if item.get('can_prepare_keisan'):
            group['needs_prepare_count'] += 1
        if item.get('is_reflected_to_client'):
            group['reflected_item_count'] += 1
        elif item.get('keisan_doc_id'):
            keisan_status = (item.get('keisan_status_class') or '').strip()
            if keisan_status == 'sent':
                group['submitted_item_count'] += 1
            elif keisan_status == 'ready':
                group['completed_item_count'] += 1
            else:
                group['draft_item_count'] += 1

    client_groups = []
    for winner_user_id, group in groups.items():
        doc = keisan_doc_map.get((winner_user_id, auction_id)) or {}
        won_items = group['won_items']
        item_names = group['item_names']
        item_name_summary = ' / '.join(item_names[:3]) if item_names else '-'
        if len(item_names) > 3:
            item_name_summary += f' ほか{len(item_names) - 3}点'

        client_groups.append(
            {
                **group,
                'won_item_count': len(won_items),
                'pending_finalize_count': 0,
                'won_items': won_items,
                'pending_finalize_items': [],
                'item_name_summary': item_name_summary,
                'document_id': doc.get('id'),
                'document_no': doc.get('document_no') or '',
                'document_status': doc.get('status') or '',
                'document_status_label': doc.get('status_label') or '未作成',
                'document_status_class': doc.get('status_class') or 'muted',
                'document_issue_date_display': doc.get('issue_date') or '-',
                'has_document': bool(doc),
                'can_prepare_document': bool(group['needs_prepare_count']),
                'can_send_document': bool(doc and doc.get('status') == 'completed'),
                'is_document_submitted': bool(doc and doc.get('status') == 'submitted'),
                'user_products_ready': bool(
                    group['reflected_item_count'] > 0 or (doc and doc.get('status') == 'submitted')
                ),
            }
        )

    client_groups.sort(
        key=lambda group: (
            0 if group.get('can_prepare_document') else 1 if group.get('can_send_document') else 2,
            -(group.get('won_item_count') or 0),
            (group.get('winner_name') or ''),
        )
    )
    return client_groups


def build_proxy_service_history_datasets(conn, now=None, keyword='', sale_mode='all', date_from='', date_to=''):
    now = now or get_jst_now()
    keyword = (keyword or '').strip().lower()
    sale_mode = sale_mode if sale_mode in {'all', 'auction', 'fixed'} else 'all'
    date_from = (date_from or '').strip()
    date_to = (date_to or '').strip()

    sync_proxy_service_keisan_documents(conn)

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute(
            """
            SELECT ps.*,
                   (SELECT COUNT(*) FROM merchandise m WHERE m.auction_id = ps.id) AS item_count,
                   (SELECT COUNT(*) FROM proxy_service_bids b
                    JOIN merchandise m ON b.merchandise_id = m.id
                    WHERE m.auction_id = ps.id) AS bid_count
            FROM proxy_service_settings ps
            ORDER BY ps.id DESC
            """
        )
        auctions = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT ps.*,
                   (SELECT COUNT(*) FROM merchandise m WHERE m.auction_id = ps.id) AS item_count,
                   (SELECT COUNT(*) FROM proxy_service_bids b
                    JOIN merchandise m ON b.merchandise_id = m.id
                    WHERE m.auction_id = ps.id) AS bid_count
            FROM proxy_service_settings ps
            ORDER BY ps.id DESC
            """
        )
        auctions = [dict(row) for row in cur.fetchall()]

    cur.close()

    pending_history = []
    archived_history = []
    overall_summary = {
        'auction_count': 0,
        'item_count': 0,
        'bid_count': 0,
        'pending_auction_count': 0,
        'pending_attention_count': 0,
        'archive_auction_count': 0,
        'winner_count': 0,
        'draft_doc_count': 0,
        'completed_doc_count': 0,
        'submitted_count': 0,
        'submitted_doc_count': 0,
        'pending_reflection_count': 0,
    }

    for auction in auctions:
        auction_state = get_proxy_service_auction_state(auction, now=now)
        if auction_state.get('status') != 'ended':
            continue

        result_items, result_summary, _ = annotate_proxy_service_items(
            fetch_proxy_service_items(conn, auction['id']),
            auction,
            now=now,
        )
        result_items, keisan_summary, action_summary = decorate_proxy_service_result_items(conn, auction['id'], result_items)

        winner_names = []
        item_names = []
        for item in result_items:
            if item.get('winner_name'):
                winner_names.append(item.get('winner_name'))
            if item.get('product_name'):
                item_names.append(item.get('product_name'))

        search_blob = ' '.join(
            [
                str(auction.get('id') or ''),
                auction.get('auction_name') or '',
                auction.get('page_title') or '',
                ' '.join(winner_names),
                ' '.join(item_names),
            ]
        ).lower()

        if keyword and keyword not in search_blob:
            continue
        if sale_mode != 'all' and (auction.get('sale_mode') or 'auction') != sale_mode:
            continue
        ended_at = auction_state.get('end_datetime') or parse_proxy_service_datetime(auction.get('end_datetime'))
        ended_date = ended_at.date().isoformat() if hasattr(ended_at, 'date') else ''
        if date_from and ended_date and ended_date < date_from:
            continue
        if date_to and ended_date and ended_date > date_to:
            continue

        card = dict(auction)
        card['status'] = auction_state.get('status')
        card['status_label'] = auction_state.get('status_label')
        card['sale_mode'] = auction_state.get('sale_mode')
        card['sale_mode_label'] = '早い者勝ち' if auction_state.get('sale_mode') == 'fixed' else 'オークション'
        card['start_display'] = format_optional_datetime(auction_state.get('start_datetime'), fallback='未設定')
        card['end_display'] = format_optional_datetime(auction_state.get('end_datetime'), fallback='未設定')
        card['winner_count'] = result_summary.get('winner_count', 0)
        card['pending_finalize_count'] = result_summary.get('pending_finalize_count', 0)
        card['pending_prepare_count'] = action_summary.get('pending_prepare_count', 0)
        card['prepared_count'] = action_summary.get('prepared_count', 0)
        card['submitted_count'] = action_summary.get('submitted_count', 0)
        card['attention_count'] = (
            int(card.get('pending_finalize_count') or 0)
            + int(card.get('pending_prepare_count') or 0)
            + int(card.get('prepared_count') or 0)
        )
        card['draft_doc_count'] = keisan_summary.get('draft_count', 0)
        card['completed_doc_count'] = keisan_summary.get('completed_count', 0)
        card['submitted_doc_count'] = keisan_summary.get('submitted_count', 0)
        card['winner_names'] = winner_names[:5]
        card['winner_names_summary'] = ' / '.join(winner_names[:3]) if winner_names else '-'
        card['item_names_summary'] = ' / '.join(item_names[:3]) if item_names else '-'
        card['is_pending_followup'] = card['attention_count'] > 0

        overall_summary['item_count'] += int(card.get('item_count') or 0)
        overall_summary['bid_count'] += int(card.get('bid_count') or 0)
        overall_summary['winner_count'] += int(card.get('winner_count') or 0)
        overall_summary['draft_doc_count'] += int(card.get('draft_doc_count') or 0)
        overall_summary['completed_doc_count'] += int(card.get('completed_doc_count') or 0)
        overall_summary['submitted_count'] += int(card.get('submitted_count') or 0)
        overall_summary['submitted_doc_count'] += int(card.get('submitted_doc_count') or 0)
        overall_summary['pending_reflection_count'] += int(card.get('pending_prepare_count') or 0)

        if card['is_pending_followup']:
            pending_history.append(card)
            overall_summary['pending_auction_count'] += 1
            overall_summary['pending_attention_count'] += int(card.get('attention_count') or 0)
        else:
            archived_history.append(card)
            overall_summary['archive_auction_count'] += 1

    pending_history.sort(key=lambda auction: (parse_proxy_service_datetime(auction.get('end_datetime')) or now, auction.get('id') or 0), reverse=True)
    archived_history.sort(key=lambda auction: (parse_proxy_service_datetime(auction.get('end_datetime')) or now, auction.get('id') or 0), reverse=True)
    overall_summary['auction_count'] = len(pending_history) + len(archived_history)

    return {
        'pending_history': pending_history,
        'archived_history': archived_history,
        'summary': overall_summary,
        'filters': {
            'keyword': keyword,
            'sale_mode': sale_mode,
            'date_from': date_from,
            'date_to': date_to,
        },
    }


def count_proxy_service_user_bids(conn, auction_id, user_id):
    if not auction_id or not user_id:
        return 0

    if DATABASE_URL:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT COUNT(*) AS bid_count
            FROM proxy_service_bids b
            JOIN merchandise m ON b.merchandise_id = m.id
            WHERE m.auction_id = %s
              AND b.user_id = %s
            """,
            (auction_id, user_id),
        )
    else:
        cur = conn.cursor()
        cur.execute(
            """
            SELECT COUNT(*) AS bid_count
            FROM proxy_service_bids b
            JOIN merchandise m ON b.merchandise_id = m.id
            WHERE m.auction_id = ?
              AND b.user_id = ?
            """,
            (auction_id, user_id),
        )
    row = cur.fetchone()
    cur.close()
    if isinstance(row, dict):
        return int(row.get('bid_count') or 0)
    if row is None:
        return 0
    try:
        return int(row[0] or 0)
    except (TypeError, IndexError, ValueError):
        return 0


def build_public_proxy_service_sections(conn, now=None, current_user_id=None, allow_all=False):
    now = now or get_jst_now()

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("""
            SELECT *
            FROM proxy_service_settings
            ORDER BY id DESC
        """)
        raw_auctions = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        cur.execute("""
            SELECT *
            FROM proxy_service_settings
            ORDER BY id DESC
        """)
        raw_auctions = [dict(row) for row in cur.fetchall()]

    cur.close()

    current_auctions = []
    upcoming_auctions = []
    history_auctions = []

    for auction in raw_auctions:
        if not allow_all:
            if not current_user_id:
                continue
            if not is_proxy_service_user_allowed(conn, current_user_id, auction.get('id')):
                continue
        auction_state = get_proxy_service_auction_state(auction, now=now)
        annotated_items, summary, winner_results = annotate_proxy_service_items(
            fetch_proxy_service_items(conn, auction['id']),
            auction,
            now=now,
            current_user_id=current_user_id,
        )

        has_visible_history = bool(
            annotated_items and (
                auction_state['is_ended']
                or summary['winner_count']
                or summary['pending_finalize_count']
                or summary['no_bid_count']
            )
        )

        display_state = dict(auction_state)
        if display_state['status'] == 'private' and has_visible_history:
            display_state['status'] = 'ended'
            display_state['status_label'] = '締切済み'
            display_state['is_open'] = False
            display_state['is_ended'] = True

        auction_dict = dict(auction)
        auction_dict.update(display_state)
        auction_dict['item_count'] = len(annotated_items)
        auction_dict['active_item_count'] = summary['active_count']
        auction_dict['winner_count'] = summary['winner_count']
        auction_dict['no_bid_count'] = summary['no_bid_count']
        auction_dict['user_result_count'] = len(winner_results)
        auction_dict['user_bid_count'] = count_proxy_service_user_bids(conn, auction['id'], current_user_id) if current_user_id else 0
        auction_dict['is_user_participant'] = bool(auction_dict['user_bid_count'] or auction_dict['user_result_count'])
        auction_dict['has_visible_history'] = has_visible_history
        auction_dict['result_summary'] = summary
        auction_dict['preview_items'] = annotated_items[:3]
        auction_dict['preview_count'] = len(auction_dict['preview_items'])
        auction_dict['remaining_preview_count'] = max(0, len(annotated_items) - auction_dict['preview_count'])

        if display_state['status'] == 'open':
            current_auctions.append(auction_dict)
        elif display_state['status'] == 'scheduled':
            upcoming_auctions.append(auction_dict)
        elif has_visible_history and (allow_all or auction_dict['is_user_participant']):
            history_auctions.append(auction_dict)

    current_auctions.sort(key=lambda auction: (auction.get('end_datetime') or now, auction.get('id') or 0))
    upcoming_auctions.sort(key=lambda auction: (auction.get('start_datetime') or now, auction.get('id') or 0))
    history_auctions.sort(key=lambda auction: (auction.get('end_datetime') or now, auction.get('id') or 0), reverse=True)

    return {
        'current_auctions': current_auctions,
        'upcoming_auctions': upcoming_auctions,
        'history_auctions': history_auctions,
    }

# グローバルエラーハンドラー（エラーをブラウザに詳細表示）

@app.errorhandler(500)
def internal_error(error):
    import traceback
    error_details = traceback.format_exc()
    html = f'''
    <!DOCTYPE html>
    <html>
    <head>
        <title>500 Internal Server Error</title>
        <style>
            body {{ font-family: monospace; padding: 20px; background: #1a1a2e; color: #eee; }}
            h1 {{ color: #e94560; }}
            pre {{ background: #16213e; padding: 15px; border-radius: 8px; overflow-x: auto; white-space: pre-wrap; word-wrap: break-word; }}
            .error-type {{ color: #f39c12; }}
        </style>
    </head>
    <body>
        <h1>500 Internal Server Error</h1>
        <p class="error-type">Error: {error}</p>
        <h3>Traceback:</h3>
        <pre>{error_details}</pre>
    </body>
    </html>
    '''
    return html, 500

@app.errorhandler(Exception)
def handle_exception(e):
    if isinstance(e, HTTPException):
        return e

    import traceback
    error_details = traceback.format_exc()
    html = f'''
    <!DOCTYPE html>
    <html>
    <head>
        <title>Error - {type(e).__name__}</title>
        <style>
            body {{ font-family: monospace; padding: 20px; background: #1a1a2e; color: #eee; }}
            h1 {{ color: #e94560; }}
            pre {{ background: #16213e; padding: 15px; border-radius: 8px; overflow-x: auto; white-space: pre-wrap; word-wrap: break-word; }}
            .error-type {{ color: #f39c12; font-size: 1.2em; }}
            .error-msg {{ color: #fff; margin: 10px 0; }}
        </style>
    </head>
    <body>
        <h1>Application Error</h1>
        <p class="error-type">{type(e).__name__}</p>
        <p class="error-msg">{str(e)}</p>
        <h3>Traceback:</h3>
        <pre>{error_details}</pre>
    </body>
    </html>
    '''
    return html, 500

