# ユーザークラス
class User(UserMixin):
    # 管理者が設定可能な権限一覧
    ADMIN_PERMISSION_OPTIONS = {
        'users': 'ユーザー管理',
        'shikiriosho': '精算書管理',
        'invoices': '買取明細書管理',
        'announcements': 'お知らせ管理',
        'proxy_publish': '代行仕入れオークション掲載',
        'analytics': '分析',
        'backup': 'バックアップ'
    }
    
    def __init__(
        self,
        id,
        username,
        email,
        role,
        display_name,
        admin_permissions=None,
        subscription_status=None,
        proxy_service_budget=0,
        phone='',
        postal_code='',
        address='',
        inventory_summary_period_default='all',
        requested_monthly_plan='',
        plan_change_effective_month='',
        shipping_addresses='[]',
        preferred_shipping_address_index=0,
        last_name='',
        first_name='',
    ):
        self.id = id
        self.username = username
        self.email = email
        self.role = role
        self.display_name = display_name or username
        self.subscription_status = subscription_status or 'inactive'
        self.proxy_service_budget = proxy_service_budget or 0
        self.phone = phone or ''
        self.postal_code = postal_code or ''
        self.address = address or ''
        self.inventory_summary_period_default = inventory_summary_period_default or 'all'
        self.requested_monthly_plan = requested_monthly_plan or ''
        self.plan_change_effective_month = plan_change_effective_month or ''
        self.shipping_addresses = shipping_addresses or '[]'
        self.last_name = last_name or ''
        self.first_name = first_name or ''
        try:
            self.preferred_shipping_address_index = int(preferred_shipping_address_index or 0)
        except (TypeError, ValueError):
            self.preferred_shipping_address_index = 0
        # admin_permissionsはJSON文字列またはリスト
        if admin_permissions:
            if isinstance(admin_permissions, str):
                try:
                    self.admin_permissions = json.loads(admin_permissions)
                except:
                    self.admin_permissions = []
            else:
                self.admin_permissions = admin_permissions
        else:
            self.admin_permissions = []
    
    def is_payment_overdue(self):
        """支払いが遅延しているか"""
        return self.subscription_status == 'past_due'
    
    def can_edit_merchandise(self):
        """商品の追加・編集が可能か（1ヶ月以上滞納で不可）"""
        # オーナーは常に可能
        if self.role == 'owner':
            return True
        # 支払い遅延中は編集不可（閲覧と商品処分のみ可能）
        return self.subscription_status != 'past_due'
    
    def can_participate_auction(self):
        """オークションに参加できるか"""
        # オーナーは常に参加可能、それ以外は支払い遅延時は不可
        if self.role == 'owner':
            return True
        return self.subscription_status != 'past_due'
    
    def is_owner(self):
        """オーナー権限を持っているか"""
        return self.role == 'owner'
    
    def is_admin(self):
        """管理者以上の権限を持っているか（オーナーも含む）"""
        return self.role in ['admin', 'owner']
    
    def has_permission(self, permission):
        """特定の権限を持っているか確認"""
        # オーナーは全権限を持つ
        if self.role == 'owner':
            return True
        # 管理者は設定された権限を持つ（空の場合は全権限）
        if self.role == 'admin':
            if not self.admin_permissions:
                return True  # 権限が設定されていない場合は全権限
            return permission in self.admin_permissions
        return False
    
    def get_proxy_service_used_amount(self):
        """代行仕入れサービスで過去に購入・落札した合計金額を取得"""
        conn = get_db()
        used_amount = 0
        buyer_names = [name for name in {self.display_name, self.username} if name]
        patterns = []
        for buyer_name in buyer_names:
            patterns.extend([
                f'即決購入: {buyer_name}%',
                f'即決購入：{buyer_name}%',
                f'代行仕入れ購入: {buyer_name}%',
                f'代行仕入れ落札: {buyer_name}%',
            ])
        
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            if patterns:
                conditions = ' OR '.join(['sales_destination LIKE %s'] * len(patterns))
                cur.execute(f"""
                    SELECT COALESCE(SUM(sale_price), 0) as total
                    FROM merchandise
                    WHERE sale_date IS NOT NULL
                      AND ({conditions})
                """, patterns)
            else:
                cur.execute("SELECT 0 as total")
            result = cur.fetchone()
            used_amount = result['total'] if result else 0
        else:
            cur = conn.cursor()
            if patterns:
                conditions = ' OR '.join(['sales_destination LIKE ?'] * len(patterns))
                cur.execute(f"""
                    SELECT COALESCE(SUM(sale_price), 0) as total
                    FROM merchandise
                    WHERE sale_date IS NOT NULL
                      AND ({conditions})
                """, patterns)
            else:
                cur.execute("SELECT 0 as total")
            result = cur.fetchone()
            used_amount = result[0] if result else 0
        
        cur.close()
        conn.close()
        return used_amount
    
    def get_proxy_service_remaining_budget(self):
        """代行仕入れサービスの現在残高を取得"""
        return max(0, self.proxy_service_budget or 0)
    
    def can_purchase_proxy_item(self, price):
        """代行仕入れサービスで指定金額の商品を購入できるか"""
        if self.proxy_service_budget == 0:
            return False  # 0は使えない
        remaining = self.get_proxy_service_remaining_budget()
        return remaining >= price
    
    def get_role_display(self):
        """権限の表示名を取得"""
        role_names = {
            'owner': 'オーナー',
            'admin': '管理者',
            'user': 'ユーザー'
        }
        return role_names.get(self.role, self.role)

    def can_manage_proxy_service(self):
        """代行仕入れの公開・掲載管理ができるか"""
        return self.has_permission('proxy_publish')
    
    def get_permissions_display(self):
        """権限の表示用リストを取得"""
        if self.role == 'owner':
            return ['全権限']
        if not self.admin_permissions:
            return ['全権限']
        return [self.ADMIN_PERMISSION_OPTIONS.get(p, p) for p in self.admin_permissions]

def build_user_from_record(user):
    if not user:
        return None

    try:
        admin_permissions = user['admin_permissions']
    except (KeyError, IndexError, TypeError):
        admin_permissions = None

    try:
        subscription_status = user['subscription_status']
    except (KeyError, IndexError, TypeError):
        subscription_status = 'inactive'

    try:
        proxy_service_budget = user['proxy_service_budget'] or 0
    except (KeyError, IndexError, TypeError):
        proxy_service_budget = 0

    def get_optional_user_field(field_name, default=''):
        try:
            return user[field_name] or default
        except (KeyError, IndexError, TypeError):
            return default

    return User(
        user['id'],
        user['username'],
        user['email'],
        user['role'],
        user['display_name'],
        admin_permissions,
        subscription_status,
        proxy_service_budget,
        get_optional_user_field('phone'),
        get_optional_user_field('postal_code'),
        get_optional_user_field('address'),
        get_optional_user_field('inventory_summary_period_default', 'all'),
        get_optional_user_field('requested_monthly_plan'),
        get_optional_user_field('plan_change_effective_month'),
        get_optional_user_field('shipping_addresses', '[]'),
        get_optional_user_field('preferred_shipping_address_index', 0),
        get_optional_user_field('last_name'),
        get_optional_user_field('first_name'),
    )


def ensure_user_profile_columns():
    """ユーザー自身が管理する基本情報・表示設定カラムを後方互換で追加する"""
    conn = get_db()
    try:
        cur = conn.cursor()
        if DATABASE_URL:
            for ddl in (
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(50)",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS postal_code VARCHAR(20)",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS address TEXT",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS inventory_summary_period_default VARCHAR(30) DEFAULT 'all'",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS requested_monthly_plan VARCHAR(50)",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS plan_change_effective_month VARCHAR(20)",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS plan_change_requested_at TIMESTAMP",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS shipping_addresses TEXT DEFAULT '[]'",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS preferred_shipping_address_index INTEGER DEFAULT 0",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS last_name VARCHAR(100)",
                "ALTER TABLE users ADD COLUMN IF NOT EXISTS first_name VARCHAR(100)",
            ):
                cur.execute(ddl)
        else:
            cur.execute("PRAGMA table_info(users)")
            existing_columns = {row[1] for row in cur.fetchall()}
            sqlite_columns = {
                'phone': "ALTER TABLE users ADD COLUMN phone TEXT",
                'postal_code': "ALTER TABLE users ADD COLUMN postal_code TEXT",
                'address': "ALTER TABLE users ADD COLUMN address TEXT",
                'inventory_summary_period_default': "ALTER TABLE users ADD COLUMN inventory_summary_period_default TEXT DEFAULT 'all'",
                'requested_monthly_plan': "ALTER TABLE users ADD COLUMN requested_monthly_plan TEXT",
                'plan_change_effective_month': "ALTER TABLE users ADD COLUMN plan_change_effective_month TEXT",
                'plan_change_requested_at': "ALTER TABLE users ADD COLUMN plan_change_requested_at TEXT",
                'shipping_addresses': "ALTER TABLE users ADD COLUMN shipping_addresses TEXT DEFAULT '[]'",
                'preferred_shipping_address_index': "ALTER TABLE users ADD COLUMN preferred_shipping_address_index INTEGER DEFAULT 0",
                'last_name': "ALTER TABLE users ADD COLUMN last_name TEXT",
                'first_name': "ALTER TABLE users ADD COLUMN first_name TEXT",
            }
            for column_name, ddl in sqlite_columns.items():
                if column_name not in existing_columns:
                    cur.execute(ddl)
        conn.commit()
        cur.close()
    finally:
        conn.close()


def resolve_analytics_memo_target_month(start_month='', end_month=''):
    start_month = (start_month or '').strip()
    end_month = (end_month or '').strip()
    if start_month and end_month and start_month == end_month:
        return start_month
    return end_month or start_month or get_jst_now().strftime('%Y-%m')


def ensure_analytics_memo_schema():
    conn = get_db()
    try:
        cur = conn.cursor()
        if DATABASE_URL:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS analytics_memos (
                    id SERIAL PRIMARY KEY,
                    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
                    target_month VARCHAR(7) DEFAULT '',
                    memo_text TEXT,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            cur.execute("ALTER TABLE analytics_memos ADD COLUMN IF NOT EXISTS target_month VARCHAR(7) DEFAULT ''")
            cur.execute("UPDATE analytics_memos SET target_month = '' WHERE target_month IS NULL")
            cur.execute("""
                DO $$
                DECLARE constraint_name text;
                BEGIN
                    FOR constraint_name IN
                        SELECT c.conname
                        FROM pg_constraint c
                        JOIN pg_attribute a
                          ON a.attrelid = c.conrelid
                         AND a.attnum = ANY(c.conkey)
                        WHERE c.conrelid = 'analytics_memos'::regclass
                          AND c.contype = 'u'
                        GROUP BY c.conname, c.conkey
                        HAVING array_length(c.conkey, 1) = 1
                           AND bool_or(a.attname = 'user_id')
                    LOOP
                        EXECUTE format('ALTER TABLE analytics_memos DROP CONSTRAINT %I', constraint_name);
                    END LOOP;
                END $$;
            """)
            cur.execute("""
                CREATE UNIQUE INDEX IF NOT EXISTS analytics_memos_user_month_idx
                ON analytics_memos (user_id, target_month)
            """)
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("""
                CREATE TABLE IF NOT EXISTS analytics_memos (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
                    target_month TEXT DEFAULT '',
                    memo_text TEXT,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(user_id, target_month)
                )
            """)
            cur.execute("PRAGMA table_info(analytics_memos)")
            existing_columns = {row['name'] for row in cur.fetchall()}
            if 'target_month' not in existing_columns:
                cur.execute("ALTER TABLE analytics_memos ADD COLUMN target_month TEXT DEFAULT ''")

            cur.execute("PRAGMA index_list(analytics_memos)")
            indexes = [dict(row) for row in cur.fetchall()]
            has_user_only_unique = False
            for index in indexes:
                if not index.get('unique'):
                    continue
                cur.execute(f"PRAGMA index_info({index['name']})")
                indexed_columns = [row['name'] for row in cur.fetchall()]
                if indexed_columns == ['user_id']:
                    has_user_only_unique = True
                    break

            if has_user_only_unique:
                cur.execute("DROP TABLE IF EXISTS analytics_memos_new")
                cur.execute("""
                    CREATE TABLE analytics_memos_new (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
                        target_month TEXT DEFAULT '',
                        memo_text TEXT,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        UNIQUE(user_id, target_month)
                    )
                """)
                cur.execute("""
                    INSERT OR IGNORE INTO analytics_memos_new (id, user_id, target_month, memo_text, updated_at)
                    SELECT id, user_id, COALESCE(target_month, ''), memo_text, updated_at
                    FROM analytics_memos
                """)
                cur.execute("DROP TABLE analytics_memos")
                cur.execute("ALTER TABLE analytics_memos_new RENAME TO analytics_memos")
            else:
                cur.execute("""
                    CREATE UNIQUE INDEX IF NOT EXISTS analytics_memos_user_month_idx
                    ON analytics_memos (user_id, target_month)
                """)
            cur.execute("UPDATE analytics_memos SET target_month = '' WHERE target_month IS NULL")
        conn.commit()
        cur.close()
    finally:
        conn.close()


def get_all_admin_permission_keys():
    return list(User.ADMIN_PERMISSION_OPTIONS.keys())


def normalize_submitted_admin_permissions(role, selected_permissions):
    if role != 'admin':
        return None

    valid_permissions = [
        permission for permission in (selected_permissions or [])
        if permission in User.ADMIN_PERMISSION_OPTIONS
    ]

    if not valid_permissions:
        valid_permissions = get_all_admin_permission_keys()

    return json.dumps(valid_permissions, ensure_ascii=False)


def render_permission_denied(message, title='権限が付与されていません'):
    return render_template('permission_denied.html', title=title, message=message), 403


def ensure_proxy_publish_permission_seeded():
    """既存の管理者権限設定に代行仕入れ公開権限を後方互換で追加"""
    conn = None
    try:
        conn = get_db()
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            cur.execute("""
                SELECT id, admin_permissions
                FROM users
                WHERE role = 'admin' AND admin_permissions IS NOT NULL
            """)
            rows = [dict(row) for row in cur.fetchall()]
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("""
                SELECT id, admin_permissions
                FROM users
                WHERE role = 'admin' AND admin_permissions IS NOT NULL
            """)
            rows = [dict(row) for row in cur.fetchall()]

        updated_count = 0
        for row in rows:
            raw_permissions = row.get('admin_permissions')
            if not raw_permissions:
                continue
            try:
                permissions = json.loads(raw_permissions) if isinstance(raw_permissions, str) else list(raw_permissions)
            except Exception:
                continue

            if not isinstance(permissions, list) or 'proxy_publish' in permissions:
                continue

            permissions.append('proxy_publish')
            updated_permissions = json.dumps(permissions, ensure_ascii=False)
            if DATABASE_URL:
                cur.execute(
                    "UPDATE users SET admin_permissions = %s WHERE id = %s",
                    (updated_permissions, row['id'])
                )
            else:
                cur.execute(
                    "UPDATE users SET admin_permissions = ? WHERE id = ?",
                    (updated_permissions, row['id'])
                )
            updated_count += 1

        if updated_count:
            conn.commit()

        cur.close()
        conn.close()
    except Exception as e:
        print(f"[WARN] ensure_proxy_publish_permission_seeded failed: {e}")
        if conn:
            try:
                conn.rollback()
                conn.close()
            except Exception:
                pass


def get_proxy_publish_denied_response(json_response=False):
    message = '代行仕入れの掲載・公開権限がありません'
    if json_response:
        return jsonify({'success': False, 'error': message}), 403
    return render_permission_denied(message)


def get_effective_proxy_price(item):
    if not item:
        return 0

    if isinstance(item, dict):
        wholesale_price = item.get('wholesale_price')
        listing_price = item.get('listing_price')
        purchase_price = item.get('purchase_price')
    else:
        wholesale_price = getattr(item, 'wholesale_price', 0)
        listing_price = getattr(item, 'listing_price', 0)
        purchase_price = getattr(item, 'purchase_price', 0)

    try:
        wholesale_price = int(wholesale_price or 0)
    except (TypeError, ValueError):
        wholesale_price = 0

    try:
        listing_price = int(listing_price or 0)
    except (TypeError, ValueError):
        listing_price = 0

    try:
        purchase_price = int(purchase_price or 0)
    except (TypeError, ValueError):
        purchase_price = 0

    return listing_price if listing_price > 0 else (wholesale_price if wholesale_price > 0 else purchase_price)


def resolve_default_proxy_auction_id(item_id=None):
    """商品一覧の簡易掲載ボタン用に既定の公開先オークションを決定する"""
    conn = None
    try:
        conn = get_db()
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            if item_id is not None:
                cur.execute("SELECT auction_id FROM merchandise WHERE id = %s", (item_id,))
                item_row = cur.fetchone()
                if item_row and item_row.get('auction_id'):
                    auction_id = item_row.get('auction_id')
                    cur.close()
                    conn.close()
                    return auction_id, None

            cur.execute("""
                SELECT id, is_public
                FROM proxy_service_settings
                ORDER BY CASE WHEN is_public THEN 0 ELSE 1 END, id DESC
            """)
            auctions = [dict(row) for row in cur.fetchall()]
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            if item_id is not None:
                cur.execute("SELECT auction_id FROM merchandise WHERE id = ?", (item_id,))
                item_row = cur.fetchone()
                if item_row and item_row['auction_id']:
                    auction_id = item_row['auction_id']
                    cur.close()
                    conn.close()
                    return auction_id, None

            cur.execute("""
                SELECT id, is_public
                FROM proxy_service_settings
                ORDER BY CASE WHEN is_public = 1 THEN 0 ELSE 1 END, id DESC
            """)
            auctions = [dict(row) for row in cur.fetchall()]

        cur.close()
        conn.close()

        if not auctions:
            return None, '代行仕入れ公開先のオークションがまだ作成されていません'

        public_auctions = [auction for auction in auctions if auction.get('is_public')]
        if len(public_auctions) == 1:
            return public_auctions[0]['id'], None
        if len(auctions) == 1:
            return auctions[0]['id'], None
        if len(public_auctions) > 1:
            return None, '公開中のオークションが複数あります。代行仕入れ管理画面から掲載先を選んでください'
        return None, 'オークションが複数あります。代行仕入れ管理画面から掲載先を選んでください'
    except Exception as e:
        if conn:
            try:
                conn.close()
            except Exception:
                pass
        print(f"[WARN] resolve_default_proxy_auction_id failed: {e}")
        return None, '掲載先オークションの判定中にエラーが発生しました'

