def upsert_announcement_user_status(user_id, announcement_ids, hide_banner=False, delete=False):
    if not user_id:
        return 0

    cleaned_ids = normalize_announcement_ids(announcement_ids)
    if not cleaned_ids:
        return 0

    now = get_jst_now()
    conn = get_db()
    cur = None
    try:
        cur = conn.cursor()
        if DATABASE_URL:
            cur.executemany(
                """
                INSERT INTO announcement_user_status (
                    announcement_id, user_id, banner_hidden_at, deleted_at, created_at, updated_at
                )
                VALUES (%s, %s, %s, %s, %s, %s)
                ON CONFLICT (announcement_id, user_id) DO UPDATE SET
                    banner_hidden_at = COALESCE(announcement_user_status.banner_hidden_at, EXCLUDED.banner_hidden_at),
                    deleted_at = COALESCE(EXCLUDED.deleted_at, announcement_user_status.deleted_at),
                    updated_at = EXCLUDED.updated_at
                """,
                [
                    (
                        announcement_id,
                        int(user_id),
                        now if hide_banner else None,
                        now if delete else None,
                        now,
                        now,
                    )
                    for announcement_id in cleaned_ids
                ],
            )
        else:
            now_text = now.strftime('%Y-%m-%d %H:%M:%S')
            cur.executemany(
                """
                INSERT INTO announcement_user_status (
                    announcement_id, user_id, banner_hidden_at, deleted_at, created_at, updated_at
                )
                VALUES (?, ?, ?, ?, ?, ?)
                ON CONFLICT(announcement_id, user_id) DO UPDATE SET
                    banner_hidden_at = COALESCE(banner_hidden_at, excluded.banner_hidden_at),
                    deleted_at = COALESCE(excluded.deleted_at, deleted_at),
                    updated_at = excluded.updated_at
                """,
                [
                    (
                        announcement_id,
                        int(user_id),
                        now_text if hide_banner else None,
                        now_text if delete else None,
                        now_text,
                        now_text,
                    )
                    for announcement_id in cleaned_ids
                ],
            )
        conn.commit()
        return len(cleaned_ids)
    finally:
        if cur:
            cur.close()
        conn.close()


def hide_announcement_banner_for_user(user_id, announcement_ids):
    return upsert_announcement_user_status(user_id, announcement_ids, hide_banner=True)


def delete_announcement_for_user(user_id, announcement_ids):
    count = upsert_announcement_user_status(user_id, announcement_ids, hide_banner=True, delete=True)
    if count:
        mark_announcements_read_for_user(user_id, announcement_ids)
    return count


def get_visible_announcement_ids_for_user(user):
    if not user or not getattr(user, 'is_authenticated', False):
        return []
    return [
        int(announcement.get('id') or 0)
        for announcement in get_active_announcements(user=user, limit=None)
        if int(announcement.get('id') or 0) > 0
    ]


def get_active_announcements(user=None, limit=None, for_banner=False):
    """アクティブなお知らせを取得"""
    conn = get_db()
    now = get_jst_now()
    query_limit = max(int(limit or 0), 20) if limit else 100
    
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("""
            SELECT * FROM announcements 
            WHERE is_active = TRUE
            AND (publish_at IS NULL OR publish_at <= %s)
            AND (expire_at IS NULL OR expire_at > %s)
            ORDER BY created_at DESC
            LIMIT %s
        """, (now, now, query_limit))
    else:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("""
            SELECT * FROM announcements 
            WHERE is_active = 1
            AND (publish_at IS NULL OR publish_at <= ?)
            AND (expire_at IS NULL OR expire_at > ?)
            ORDER BY created_at DESC
            LIMIT ?
        """, (now.strftime('%Y-%m-%d %H:%M:%S'), now.strftime('%Y-%m-%d %H:%M:%S'), query_limit))
    
    announcements = []
    for row in cur.fetchall():
        announcement = dict(row)
        announcement['recipient_scope'] = get_announcement_recipient_scope(announcement)
        announcement['recipient_scope_label'] = get_announcement_recipient_scope_label(announcement)
        announcement['recipient_user_ids_list'] = parse_announcement_recipient_ids(announcement.get('recipient_user_ids'))
        announcement['recipient_summary'] = get_announcement_recipient_summary(announcement)
        announcement['content_lines'] = split_announcement_content_lines(announcement.get('content'))
        if announcement_is_visible_to_user(announcement, user=user):
            announcements.append(announcement)
    cur.close()
    conn.close()

    target_user = user
    if target_user is None and has_request_context() and getattr(current_user, 'is_authenticated', False):
        target_user = current_user

    if target_user and not getattr(target_user, 'is_admin', lambda: False)() and not getattr(target_user, 'is_owner', lambda: False)():
        status_map = get_announcement_user_status_map(
            getattr(target_user, 'id', None),
            [announcement.get('id') for announcement in announcements],
        )
        filtered_announcements = []
        for announcement in announcements:
            announcement_id = int(announcement.get('id') or 0)
            user_status = status_map.get(announcement_id) or {}
            announcement['banner_hidden_at'] = user_status.get('banner_hidden_at')
            announcement['deleted_at'] = user_status.get('deleted_at')
            if user_status.get('deleted_at'):
                continue
            if for_banner and user_status.get('banner_hidden_at'):
                continue
            filtered_announcements.append(announcement)
        announcements = filtered_announcements

    read_map = {}
    if target_user and not getattr(target_user, 'is_admin', lambda: False)() and not getattr(target_user, 'is_owner', lambda: False)():
        read_map = get_announcement_read_map(
            getattr(target_user, 'id', None),
            [announcement.get('id') for announcement in announcements],
        )

    for announcement in announcements:
        read_at = read_map.get(int(announcement.get('id') or 0))
        announcement['is_read'] = bool(read_at)
        announcement['read_at'] = read_at

    if limit:
        return announcements[:limit]
    return announcements


def serialize_announcement_datetime(value):
    if value is None:
        return None
    if isinstance(value, datetime):
        return value.isoformat(timespec='seconds')

    text = str(value).strip()
    return text or None


def serialize_announcement_payload(announcement):
    return {
        'id': int(announcement.get('id') or 0),
        'title': announcement.get('title') or '',
        'content': announcement.get('content') or '',
        'content_lines': announcement.get('content_lines') or split_announcement_content_lines(announcement.get('content')),
        'announcement_type': announcement.get('announcement_type') or 'info',
        'recipient_scope': get_announcement_recipient_scope(announcement),
        'recipient_scope_label': announcement.get('recipient_scope_label') or get_announcement_recipient_scope_label(announcement),
        'recipient_summary': announcement.get('recipient_summary') or get_announcement_recipient_summary(announcement),
        'is_read': bool(announcement.get('is_read')),
        'read_at': serialize_announcement_datetime(announcement.get('read_at')),
        'banner_hidden_at': serialize_announcement_datetime(announcement.get('banner_hidden_at')),
        'deleted_at': serialize_announcement_datetime(announcement.get('deleted_at')),
        'publish_at': serialize_announcement_datetime(announcement.get('publish_at')),
        'created_at': serialize_announcement_datetime(announcement.get('created_at')),
    }


def create_targeted_system_announcement(user_id, title, content, announcement_type='info', created_by=None):
    """LINE未連携でもユーザー画面へ残せる個別のお知らせを作成する。"""
    try:
        target_user_id = int(user_id)
    except (TypeError, ValueError):
        return None
    if target_user_id <= 0:
        return None

    ensure_announcement_targeting_schema()
    ensure_announcement_delivery_schema()

    now_value = get_jst_now()
    recipient_user_ids = serialize_announcement_recipient_ids([target_user_id])
    conn = get_db()
    cur = None
    try:
        if DATABASE_URL:
            cur = conn.cursor()
            cur.execute(
                """
                INSERT INTO announcements (
                    title, content, announcement_type, is_active, publish_at,
                    created_by, recipient_scope, recipient_user_ids
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING id
                """,
                (
                    title,
                    content,
                    announcement_type or 'info',
                    True,
                    now_value,
                    created_by,
                    'selected',
                    recipient_user_ids,
                ),
            )
            row = cur.fetchone()
            announcement_id = row[0] if row else None
        else:
            cur = conn.cursor()
            cur.execute(
                """
                INSERT INTO announcements (
                    title, content, announcement_type, is_active, publish_at,
                    created_by, recipient_scope, recipient_user_ids
                )
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    title,
                    content,
                    announcement_type or 'info',
                    1,
                    now_value.strftime('%Y-%m-%d %H:%M:%S'),
                    created_by,
                    'selected',
                    recipient_user_ids,
                ),
            )
            announcement_id = cur.lastrowid
        conn.commit()
        return announcement_id
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"[WARN] create_targeted_system_announcement failed: {e}", flush=True)
        return None
    finally:
        if cur:
            cur.close()
        conn.close()

