# マスターテーブルにscopeカラムを追加するマイグレーション
def migrate_add_scope_column():
    """マスターテーブルにscopeカラムを追加（ユーザー機能/開花管理の分離用）"""
    try:
        conn = get_db()
        
        master_tables = [
            'master_brand_categories',
            'master_brands', 
            'master_suppliers',
            'master_conditions',
            'master_payment_methods',
            'master_supplier_details'
        ]
        
        if DATABASE_URL:
            cur = conn.cursor()
            for table in master_tables:
                try:
                    # カラムが存在しない場合のみ追加
                    cur.execute(f"ALTER TABLE {table} ADD COLUMN scope VARCHAR(20) DEFAULT 'admin'")
                    conn.commit()
                    print(f"Added scope column to {table}")
                except Exception as e:
                    conn.rollback()
                    if 'already exists' in str(e).lower() or 'duplicate column' in str(e).lower():
                        pass  # カラムが既に存在する場合は無視
                    else:
                        print(f"Migration warning for {table}: {e}")
        else:
            cur = conn.cursor()
            for table in master_tables:
                try:
                    # SQLiteでカラムの存在確認
                    cur.execute(f"PRAGMA table_info({table})")
                    columns = [col[1] for col in cur.fetchall()]
                    if 'scope' not in columns:
                        cur.execute(f"ALTER TABLE {table} ADD COLUMN scope TEXT DEFAULT 'admin'")
                        conn.commit()
                        print(f"Added scope column to {table}")
                except Exception as e:
                    print(f"Migration warning for {table}: {e}")
        
        if DATABASE_URL:
            try:
                cur.execute("""
                    SELECT 1
                    FROM information_schema.columns
                    WHERE table_schema = current_schema()
                      AND table_name = 'merchandise'
                      AND column_name = 'scope'
                """)
                if cur.fetchone() is None:
                    cur.execute("ALTER TABLE merchandise ADD COLUMN scope VARCHAR(20) DEFAULT 'admin'")
                    conn.commit()
                    print("Added scope column to merchandise")
                cur.execute("UPDATE merchandise SET scope = 'admin' WHERE scope IS NULL OR scope = ''")
                conn.commit()
            except Exception as e:
                conn.rollback()
                print(f"Migration warning for merchandise: {e}")
        else:
            try:
                cur.execute("PRAGMA table_info(merchandise)")
                merchandise_columns = [col[1] for col in cur.fetchall()]
                if 'scope' not in merchandise_columns:
                    cur.execute("ALTER TABLE merchandise ADD COLUMN scope TEXT DEFAULT 'admin'")
                    conn.commit()
                    print("Added scope column to merchandise")
                cur.execute("UPDATE merchandise SET scope = 'admin' WHERE scope IS NULL OR TRIM(scope) = ''")
                conn.commit()
            except Exception as e:
                print(f"Migration warning for merchandise: {e}")

        cur.close()
        conn.close()
        print("Scope column migration completed")
    except Exception as e:
        print(f"Migration error: {e}")


def ensure_merchandise_scope_column(conn):
    """商品登録・一覧で merchandise.scope が無くても自動補完する"""
    cur = None
    try:
        cur = conn.cursor()
        if DATABASE_URL:
            cur.execute("""
                SELECT 1
                FROM information_schema.columns
                WHERE table_schema = current_schema()
                  AND table_name = 'merchandise'
                  AND column_name = 'scope'
            """)
            if cur.fetchone() is None:
                cur.execute("ALTER TABLE merchandise ADD COLUMN scope VARCHAR(20) DEFAULT 'admin'")
                conn.commit()
                print("Added scope column to merchandise (guard)")
            cur.execute("UPDATE merchandise SET scope = 'admin' WHERE scope IS NULL OR scope = ''")
            conn.commit()
        else:
            cur.execute("PRAGMA table_info(merchandise)")
            merchandise_columns = [col[1] for col in cur.fetchall()]
            if 'scope' not in merchandise_columns:
                cur.execute("ALTER TABLE merchandise ADD COLUMN scope TEXT DEFAULT 'admin'")
                conn.commit()
                print("Added scope column to merchandise (guard)")
            cur.execute("UPDATE merchandise SET scope = 'admin' WHERE scope IS NULL OR TRIM(scope) = ''")
            conn.commit()
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"Merchandise scope guard warning: {e}")
    finally:
        if cur is not None:
            cur.close()

# マイグレーション実行
migrate_add_scope_column()

