@app.route('/home')
@login_required
def user_home():
    if current_user.is_admin() or current_user.is_owner():
        return redirect(url_for('admin_dashboard'))

    conn = get_db()

    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("""
            SELECT
                COUNT(CASE WHEN sale_date IS NULL THEN 1 END) AS inventory_count
            FROM merchandise
            WHERE user_id = %s
        """, (current_user.id,))
        summary_row = cur.fetchone() or {}
    else:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        cur.execute("""
            SELECT
                COUNT(CASE WHEN sale_date IS NULL THEN 1 END) AS inventory_count
            FROM merchandise
            WHERE user_id = ?
        """, (current_user.id,))
        row = cur.fetchone()
        summary_row = dict(row) if row else {}

    cur.close()
    conn.close()

    announcements = get_active_announcements(current_user, limit=None)
    proxy_service_info = {
        'budget': current_user.proxy_service_budget or 0,
        'used': current_user.get_proxy_service_used_amount(),
        'remaining': current_user.get_proxy_service_remaining_budget()
    }
    summary = {
        'inventory_count': int(summary_row.get('inventory_count') or 0)
    }
    profile_missing_fields = get_profile_missing_fields(current_user)
    announcement_payloads = [
        serialize_announcement_payload(announcement)
        for announcement in announcements
    ]

    return render_template(
        'user_home.html',
        announcements=announcements,
        announcement_payloads=announcement_payloads,
        proxy_service_info=proxy_service_info,
        summary=summary,
        profile_missing_fields=profile_missing_fields
    )

@app.route('/')
@login_required
def index():
    # 管理者/オーナーの場合は管理者商品一覧へリダイレクト
    if current_user.is_admin() or current_user.is_owner():
        return redirect(url_for('admin_dashboard'))
    
    filter_type = request.args.get('filter', '')
    search = request.args.get('search', '')
    summary_period = (request.args.get('summary_period') or 'all').strip()
    allowed_summary_periods = {'all', 'current_month', 'previous_month', 'last_3_months'}
    if summary_period not in allowed_summary_periods:
        summary_period = 'all'
    sort_mode = (request.args.get('sort') or 'priority').strip()
    allowed_sort_modes = {
        'priority',
        'newest',
        'oldest',
        'purchase_high',
        'purchase_low',
        'sale_high',
        'profit_high',
        'sold_newest',
    }
    if sort_mode not in allowed_sort_modes:
        sort_mode = 'priority'
    
    conn = get_db()
    
    # オーナー/管理者の場合、全オーナー/管理者の商品を共有表示
    is_shared_view = current_user.is_admin() or current_user.is_owner()
    shared_user_ids = []
    shared_users = {}  # user_id -> display_name のマッピング
    
    # すべてのユーザーをマッピング（最終更新者表示用）
    all_users = {}
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT id, display_name, username FROM users")
    else:
        cur = conn.cursor()
        cur.execute("SELECT id, display_name, username FROM users")
    
    for u in cur.fetchall():
        u_dict = dict(u)
        all_users[u_dict['id']] = u_dict['display_name'] or u_dict['username']
    
    if is_shared_view:
        if DATABASE_URL:
            cur.execute("SELECT id, display_name, username FROM users WHERE role IN ('owner', 'admin')")
        else:
            cur.execute("SELECT id, display_name, username FROM users WHERE role IN ('owner', 'admin')")
        
        for u in cur.fetchall():
            u_dict = dict(u)
            shared_user_ids.append(u_dict['id'])
            shared_users[u_dict['id']] = u_dict['display_name'] or u_dict['username']
    
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['%s'] * len(shared_user_ids))
            query = f"SELECT * FROM merchandise WHERE user_id IN ({placeholders})"
            params = shared_user_ids.copy()
        else:
            query = "SELECT * FROM merchandise WHERE user_id = %s"
            params = [current_user.id]
    else:
        cur = conn.cursor()
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['?'] * len(shared_user_ids))
            query = f"SELECT * FROM merchandise WHERE user_id IN ({placeholders})"
            params = shared_user_ids.copy()
        else:
            query = "SELECT * FROM merchandise WHERE user_id = ?"
            params = [current_user.id]
    
    # フィルター
    today = get_jst_now().date()
    if filter_type == 'today':
        if DATABASE_URL:
            query += " AND purchase_date = %s"
        else:
            query += " AND purchase_date = ?"
        params.append(str(today))
    elif filter_type == 'yesterday':
        yesterday = today - timedelta(days=1)
        if DATABASE_URL:
            query += " AND purchase_date = %s"
        else:
            query += " AND purchase_date = ?"
        params.append(str(yesterday))
    elif filter_type == 'week':
        week_ago = today - timedelta(days=7)
        if DATABASE_URL:
            query += " AND purchase_date >= %s"
        else:
            query += " AND purchase_date >= ?"
        params.append(str(week_ago))
    elif filter_type == 'month':
        month_ago = today - timedelta(days=30)
        if DATABASE_URL:
            query += " AND purchase_date >= %s"
        else:
            query += " AND purchase_date >= ?"
        params.append(str(month_ago))
    elif filter_type == 'sold':
        query += " AND sale_date IS NOT NULL"
    elif filter_type == 'unsold':
        query += " AND sale_date IS NULL"
    
    # 検索
    if search:
        if DATABASE_URL:
            query += " AND (product_name ILIKE %s OR store_name ILIKE %s)"
            params.extend([f'%{search}%', f'%{search}%'])
        else:
            query += " AND (product_name LIKE ? OR store_name LIKE ?)"
            params.extend([f'%{search}%', f'%{search}%'])
    
    query += " ORDER BY id DESC"
    cur.execute(query, params)
    items = cur.fetchall()
    
    # 統計
    if DATABASE_URL:
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['%s'] * len(shared_user_ids))
            cur.execute(f"""
                SELECT 
                    COUNT(*) as total_items,
                    COALESCE(SUM(purchase_price), 0) as total_purchase,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN sale_price ELSE 0 END), 0) as total_sales,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN 
                        sale_price - purchase_price - shipping_cost - commission ELSE 0 END), 0) as total_profit,
                    COUNT(CASE WHEN sale_date IS NOT NULL THEN 1 END) as sold_count,
                    COALESCE(SUM(CASE WHEN sale_date IS NULL THEN purchase_price ELSE 0 END), 0) as inventory_value
                FROM merchandise WHERE user_id IN ({placeholders})
            """, shared_user_ids)
        else:
            cur.execute("""
                SELECT 
                    COUNT(*) as total_items,
                    COALESCE(SUM(purchase_price), 0) as total_purchase,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN sale_price ELSE 0 END), 0) as total_sales,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN 
                        sale_price - purchase_price - shipping_cost - commission ELSE 0 END), 0) as total_profit,
                    COUNT(CASE WHEN sale_date IS NOT NULL THEN 1 END) as sold_count,
                    COALESCE(SUM(CASE WHEN sale_date IS NULL THEN purchase_price ELSE 0 END), 0) as inventory_value
                FROM merchandise WHERE user_id = %s
            """, (current_user.id,))
    else:
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['?'] * len(shared_user_ids))
            cur.execute(f"""
                SELECT 
                    COUNT(*) as total_items,
                    COALESCE(SUM(purchase_price), 0) as total_purchase,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN sale_price ELSE 0 END), 0) as total_sales,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN 
                        sale_price - purchase_price - shipping_cost - commission ELSE 0 END), 0) as total_profit,
                    COUNT(CASE WHEN sale_date IS NOT NULL THEN 1 END) as sold_count,
                    COALESCE(SUM(CASE WHEN sale_date IS NULL THEN purchase_price ELSE 0 END), 0) as inventory_value
                FROM merchandise WHERE user_id IN ({placeholders})
            """, shared_user_ids)
        else:
            cur.execute("""
                SELECT 
                    COUNT(*) as total_items,
                    COALESCE(SUM(purchase_price), 0) as total_purchase,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN sale_price ELSE 0 END), 0) as total_sales,
                    COALESCE(SUM(CASE WHEN sale_date IS NOT NULL THEN 
                        sale_price - purchase_price - shipping_cost - commission ELSE 0 END), 0) as total_profit,
                    COUNT(CASE WHEN sale_date IS NOT NULL THEN 1 END) as sold_count,
                    COALESCE(SUM(CASE WHEN sale_date IS NULL THEN purchase_price ELSE 0 END), 0) as inventory_value
                FROM merchandise WHERE user_id = ?
            """, (current_user.id,))

    stats = cur.fetchone()

    # 商品一覧上部の集計は、一覧検索とは別に「全期間 / 今月 / 先月 / 直近3か月」で切替できるようにする
    if DATABASE_URL:
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['%s'] * len(shared_user_ids))
            cur.execute(f"""
                SELECT purchase_date, sale_date, purchase_price, sale_price, shipping_cost, commission
                FROM merchandise
                WHERE user_id IN ({placeholders})
            """, shared_user_ids)
        else:
            cur.execute("""
                SELECT purchase_date, sale_date, purchase_price, sale_price, shipping_cost, commission
                FROM merchandise
                WHERE user_id = %s
            """, (current_user.id,))
    else:
        if is_shared_view and shared_user_ids:
            placeholders = ','.join(['?'] * len(shared_user_ids))
            cur.execute(f"""
                SELECT purchase_date, sale_date, purchase_price, sale_price, shipping_cost, commission
                FROM merchandise
                WHERE user_id IN ({placeholders})
            """, shared_user_ids)
        else:
            cur.execute("""
                SELECT purchase_date, sale_date, purchase_price, sale_price, shipping_cost, commission
                FROM merchandise
                WHERE user_id = ?
            """, (current_user.id,))

    stats_rows = [dict(row) for row in cur.fetchall()]
    period_today = get_jst_now().date()
    current_month_start = period_today.replace(day=1)
    previous_month_end = current_month_start - timedelta(days=1)
    previous_month_start = previous_month_end.replace(day=1)
    last_3_months_start = (current_month_start - timedelta(days=62)).replace(day=1)

    period_ranges = {
        'current_month': (current_month_start, period_today),
        'previous_month': (previous_month_start, previous_month_end),
        'last_3_months': (last_3_months_start, period_today),
    }
    selected_period_range = period_ranges.get(summary_period)

    def parse_summary_date(value):
        if not value:
            return None
        if isinstance(value, datetime):
            return value.date()
        if hasattr(value, 'date') and callable(value.date):
            try:
                return value.date()
            except Exception:
                pass
        value_text = str(value).strip()
        if not value_text:
            return None
        for fmt in ('%Y-%m-%d', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M:%S.%f'):
            try:
                return datetime.strptime(value_text[:26], fmt).date()
            except ValueError:
                continue
        return None

    def is_in_summary_period(value):
        if summary_period == 'all':
            return True
        parsed = parse_summary_date(value)
        if not parsed or not selected_period_range:
            return False
        start_date, end_date = selected_period_range
        return start_date <= parsed <= end_date

    computed_stats = {
        'total_items': 0,
        'total_purchase': 0,
        'total_sales': 0,
        'total_profit': 0,
        'sold_count': 0,
        'inventory_value': 0,
    }
    for row in stats_rows:
        purchase_price = int(row.get('purchase_price') or 0)
        sale_price = int(row.get('sale_price') or 0)
        shipping_cost = int(row.get('shipping_cost') or 0)
        commission = int(row.get('commission') or 0)
        purchase_in_period = is_in_summary_period(row.get('purchase_date'))
        sale_in_period = bool(row.get('sale_date')) and is_in_summary_period(row.get('sale_date'))

        if purchase_in_period:
            computed_stats['total_items'] += 1
            computed_stats['total_purchase'] += purchase_price
            if not row.get('sale_date'):
                computed_stats['inventory_value'] += purchase_price
        if sale_in_period:
            computed_stats['sold_count'] += 1
            computed_stats['total_sales'] += sale_price
            computed_stats['total_profit'] += sale_price - purchase_price - shipping_cost - commission

    stats = computed_stats
    cur.close()
    conn.close()
    
    # 売却関連申請を取得
    pending_shipping_requests = {}
    pending_completion_requests = {}
    approved_shipping_requests = {}
    shipped_shipping_requests = {}
    try:
        conn2 = get_db()
        if DATABASE_URL:
            cur2 = conn2.cursor(cursor_factory=RealDictCursor)
            cur2.execute("SELECT * FROM sale_requests ORDER BY created_at DESC")
        else:
            cur2 = conn2.cursor()
            cur2.execute("SELECT * FROM sale_requests ORDER BY created_at DESC")
        for req in cur2.fetchall():
            req_dict = dict(req)
            request_type = normalize_sale_request_type(req_dict.get('request_type'))
            req_dict['request_type'] = request_type
            req_dict['request_type_label'] = get_sale_request_type_label(request_type)
            merchandise_id = req_dict['merchandise_id']
            if req_dict.get('status') == 'pending':
                if request_type == 'completion_report':
                    pending_completion_requests.setdefault(merchandise_id, req_dict)
                else:
                    pending_shipping_requests.setdefault(merchandise_id, req_dict)
            elif req_dict.get('status') == 'approved' and request_type == 'shipping_request':
                approved_shipping_requests.setdefault(merchandise_id, req_dict)
                if normalize_shipment_status(req_dict.get('shipment_status')) == 'shipped' or req_dict.get('shipment_marked_at'):
                    shipped_shipping_requests.setdefault(merchandise_id, req_dict)
        cur2.close()
        conn2.close()
    except Exception as e:
        print(f"Error fetching pending requests: {e}")
    
    # 販売代行サービス申請を取得（承認待ち・承認済みの両方）
    sales_agency_items = {}
    try:
        conn3 = get_db()
        if DATABASE_URL:
            cur3 = conn3.cursor(cursor_factory=RealDictCursor)
            cur3.execute("""
                SELECT sari.merchandise_id, sar.id as request_id, sar.service_type, sar.status, sar.created_at
                FROM sales_agency_request_items sari
                JOIN sales_agency_requests sar ON sari.request_id = sar.id
                WHERE sar.status IN ('pending', 'approved', 'appraising', 'inspecting', 'completed')
                  AND sar.service_type IN ('wholesale', 'simultaneous', 'auction')
            """)
        else:
            cur3 = conn3.cursor()
            cur3.execute("""
                SELECT sari.merchandise_id, sar.id as request_id, sar.service_type, sar.status, sar.created_at
                FROM sales_agency_request_items sari
                JOIN sales_agency_requests sar ON sari.request_id = sar.id
                WHERE sar.status IN ('pending', 'approved', 'appraising', 'inspecting', 'completed')
                  AND sar.service_type IN ('wholesale', 'simultaneous', 'auction')
            """)
        for req in cur3.fetchall():
            req_dict = dict(req)
            req_dict['service_name'] = get_sales_agency_service_name(req_dict.get('service_type'))
            req_dict['status_label'] = get_sales_agency_status_label(
                req_dict.get('status'),
                viewer='client',
                service_type=req_dict.get('service_type'),
            )
            sales_agency_items[req_dict['merchandise_id']] = req_dict
        cur3.close()
        conn3.close()
    except Exception as e:
        print(f"Error fetching sales agency requests: {e}", flush=True)
    
    # アイテムに計算フィールド追加
    fee_settings = get_fee_settings()
    processed_items = []
    for item in items:
        item_dict = dict(item)
        if item_dict.get('photo_path'):
            item_dict['photo_path'] = item_dict['photo_path'].replace('\\', '/')
        
        # 共有ビューの場合、登録者名を追加
        if is_shared_view:
            item_dict['owner_name'] = shared_users.get(item_dict.get('user_id'), '不明')
        
        # 最終更新者名を追加
        updated_by_id = item_dict.get('updated_by')
        if updated_by_id:
            if current_user.is_admin() or current_user.is_owner():
                item_dict['updated_by_name'] = all_users.get(updated_by_id, '不明')
            else:
                item_dict['updated_by_name'] = '開花運営'
        else:
            item_dict['updated_by_name'] = '-'
        
        # 発送依頼・取引完了報告の状態を判定
        item_id = item_dict.get('id')
        shipping_request = pending_shipping_requests.get(item_id)
        completion_request = pending_completion_requests.get(item_id)
        approved_shipping_request = approved_shipping_requests.get(item_id)
        shipped_shipping_request = shipped_shipping_requests.get(item_id)

        item_dict['pending_shipping_request'] = shipping_request is not None
        item_dict['shipping_request'] = shipping_request
        item_dict['pending_completion_request'] = completion_request is not None
        item_dict['completion_request'] = completion_request
        item_dict['approved_shipping_request'] = approved_shipping_request
        item_dict['shipped_shipping_request'] = shipped_shipping_request
        item_dict['shipping_request_approved'] = bool(approved_shipping_request) or bool(shipped_shipping_request) or bool(item_dict.get('is_shipped'))
        item_dict['shipment_marked'] = bool(shipped_shipping_request) or bool(item_dict.get('is_shipped'))
        item_dict['can_send_completion_report'] = item_dict['shipment_marked'] and not item_dict.get('sale_date')

        # 既存テンプレート互換
        item_dict['pending_sale_request'] = item_dict['pending_shipping_request'] or item_dict['pending_completion_request']
        item_dict['sale_request'] = completion_request or shipping_request
        
        # 販売代行サービス申請中かどうかを判定
        if item_id in sales_agency_items:
            item_dict['pending_sales_agency'] = True
            item_dict['sales_agency_request'] = sales_agency_items[item_id]
        else:
            item_dict['pending_sales_agency'] = False
            item_dict['sales_agency_request'] = None
        
        # 削除可能かどうかを判定（オーナーは常に削除可能、管理者は1日以内のみ削除可能）
        if current_user.is_owner():
            item_dict['can_delete'] = True
        else:
            created_at = item_dict.get('created_at')
            if created_at:
                if isinstance(created_at, str):
                    try:
                        created_at = datetime.strptime(created_at, '%Y-%m-%d %H:%M:%S')
                    except:
                        try:
                            created_at = datetime.strptime(created_at, '%Y-%m-%d %H:%M:%S.%f')
                        except:
                            created_at = None
                if created_at:
                    item_dict['can_delete'] = get_jst_now() - created_at <= timedelta(days=1)
                else:
                    item_dict['can_delete'] = True
            else:
                item_dict['can_delete'] = True
        
        if item_dict.get('sale_date'):
            item_dict['profit'] = calculate_profit(
                item_dict.get('sale_price', 0) or 0,
                item_dict.get('purchase_price', 0) or 0,
                item_dict.get('shipping_cost', 0) or 0,
                item_dict.get('commission', 0) or 0
            )
            item_dict['profit_rate'] = calculate_profit_rate(item_dict['profit'], item_dict.get('purchase_price', 0) or 0)
        else:
            item_dict['expected_profit'] = calculate_expected_profit(
                item_dict.get('listing_price', 0) or 0,
                item_dict.get('purchase_price', 0) or 0,
                item_dict.get('expected_shipping', 0) or 0,
                item_dict.get('expected_commission', 0) or 0
            )

        apply_inventory_display_metrics(item_dict, scope='user', fee_settings=fee_settings)

        def resolve_status_priority(row):
            if row.get('sale_date'):
                return 90
            if row.get('pending_sales_agency'):
                return 5
            if row.get('pending_completion_request'):
                return 8
            if row.get('pending_shipping_request'):
                return 10
            if not row.get('is_listed'):
                return 12
            if row.get('can_send_completion_report'):
                return 20
            if row.get('approved_shipping_request'):
                return 25
            if row.get('appraisal_status') == 'waiting':
                return 30
            if row.get('is_listed'):
                return 40
            return 50

        item_dict['status_priority'] = resolve_status_priority(item_dict)
        sales_agency_request = item_dict.get('sales_agency_request') or {}
        if item_dict.get('sale_date') or item_dict.get('is_sold'):
            item_dict['mobile_status_label'] = '売却済み'
        elif item_dict.get('pending_completion_request'):
            item_dict['mobile_status_label'] = '取引完了報告確認中'
        elif item_dict.get('pending_shipping_request'):
            item_dict['mobile_status_label'] = '発送依頼確認中'
        elif item_dict.get('can_send_completion_report'):
            item_dict['mobile_status_label'] = '取引完了報告を送る'
        elif item_dict.get('approved_shipping_request'):
            item_dict['mobile_status_label'] = '発送準備中'
        elif item_dict.get('pending_sales_agency'):
            item_dict['mobile_status_label'] = sales_agency_request.get('status_label') or '査定待ち'
        elif item_dict.get('appraisal_status') == 'inspecting':
            item_dict['mobile_status_label'] = '査定中'
        elif item_dict.get('appraisal_status') == 'waiting':
            item_dict['mobile_status_label'] = '査定待ち'
        elif item_dict.get('is_listed'):
            item_dict['mobile_status_label'] = '認証済み'
        else:
            item_dict['mobile_status_label'] = '発送依頼を送る'
        
        # 全画像リスト（メイン + 追加）
        item_dict['all_photos'] = []
        if item_dict.get('photo_path'):
            item_dict['all_photos'].append(item_dict['photo_path'])
        if item_dict.get('additional_photos'):
            try:
                additional_list = json.loads(item_dict['additional_photos'])
                item_dict['all_photos'].extend(additional_list)
            except:
                pass
        
        processed_items.append(item_dict)

    def parse_sort_datetime(value):
        if not value:
            return datetime.min
        if isinstance(value, datetime):
            return value
        if hasattr(value, 'date') and callable(value.date):
            try:
                parsed_date = value.date()
                return datetime.combine(parsed_date, datetime.min.time())
            except Exception:
                pass
        value_text = str(value).strip()
        if not value_text:
            return datetime.min
        for fmt in ('%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
            try:
                return datetime.strptime(value_text[:26], fmt)
            except ValueError:
                continue
        return datetime.min

    def safe_sort_number(value):
        try:
            return float(value or 0)
        except (TypeError, ValueError):
            return 0.0

    def sold_sort_rank(row):
        return 1 if row.get('sale_date') else 0

    def item_sort_id(row):
        return int(row.get('id') or 0)

    def sort_timestamp(value):
        parsed = parse_sort_datetime(value)
        if parsed == datetime.min:
            return 0.0
        try:
            return parsed.timestamp()
        except (OverflowError, OSError, ValueError):
            return 0.0

    sort_handlers = {
        'priority': lambda row: (
            sold_sort_rank(row),
            int(row.get('status_priority') or 50),
            -sort_timestamp(row.get('created_at') or row.get('purchase_date')),
            -item_sort_id(row),
        ),
        'newest': lambda row: (
            sold_sort_rank(row),
            -sort_timestamp(row.get('created_at') or row.get('purchase_date')),
            -item_sort_id(row),
        ),
        'oldest': lambda row: (
            sold_sort_rank(row),
            sort_timestamp(row.get('created_at') or row.get('purchase_date')),
            item_sort_id(row),
        ),
        'purchase_high': lambda row: (
            sold_sort_rank(row),
            -safe_sort_number(row.get('wholesale_price') or row.get('purchase_price')),
            -item_sort_id(row),
        ),
        'purchase_low': lambda row: (
            sold_sort_rank(row),
            safe_sort_number(row.get('wholesale_price') or row.get('purchase_price')),
            -item_sort_id(row),
        ),
        'sale_high': lambda row: (
            sold_sort_rank(row),
            -safe_sort_number(row.get('display_sale_price') or row.get('sale_price')),
            -item_sort_id(row),
        ),
        'profit_high': lambda row: (
            sold_sort_rank(row),
            -safe_sort_number(row.get('profit') if row.get('sale_date') else row.get('expected_profit')),
            -item_sort_id(row),
        ),
        'sold_newest': lambda row: (
            0 if row.get('sale_date') else 1,
            -sort_timestamp(row.get('sale_date')),
            -item_sort_id(row),
        ),
    }
    processed_items.sort(key=sort_handlers.get(sort_mode, sort_handlers['priority']))
    
    # アクティブなお知らせを取得
    announcements = get_active_announcements(current_user, limit=5, for_banner=True)
    
    # 代行仕入れサービスの利用可能残高を取得
    proxy_service_info = {
        'budget': current_user.proxy_service_budget or 0,
        'used': current_user.get_proxy_service_used_amount(),
        'remaining': current_user.get_proxy_service_remaining_budget()
    }

    summary_period_options = get_inventory_summary_period_options()
    sort_options = [
        {'key': 'priority', 'label': 'おすすめ順（未出品・対応待ち優先）'},
        {'key': 'newest', 'label': '新しい順'},
        {'key': 'oldest', 'label': '古い順'},
        {'key': 'purchase_high', 'label': '仕入額が高い順'},
        {'key': 'purchase_low', 'label': '仕入額が低い順'},
        {'key': 'sale_high', 'label': '売上が高い順'},
        {'key': 'profit_high', 'label': '利益が高い順'},
        {'key': 'sold_newest', 'label': '売却日が新しい順'},
    ]
    is_filtered = bool(filter_type or search or summary_period != 'all' or sort_mode != 'priority')

    return render_template('index.html', items=processed_items, stats=dict(stats),
                         filter_type=filter_type, search=search, announcements=announcements,
                         is_shared_view=is_shared_view, all_users=all_users,
                         proxy_service_info=proxy_service_info,
                         summary_period=summary_period,
                         summary_period_options=summary_period_options,
                         sort_mode=sort_mode,
                         sort_options=sort_options,
                         is_filtered=is_filtered)

