@app.route('/api/report-v2/<report_type>')
@login_required
def api_report_v2(report_type):
    year = request.args.get('year', get_jst_now().year, type=int)
    month = request.args.get('month', 0, type=int)
    client_id = request.args.get('client_id', '')

    try:
        payload = build_report_v2_payload(report_type, year, month, client_id=client_id)
    except ValueError:
        return jsonify({'error': 'unsupported report type'}), 404
    except LookupError:
        return jsonify({'error': 'client_id required'}), 400

    return jsonify(payload)


@app.route('/api/report-v2/<report_type>/download')
@login_required
def api_report_v2_download(report_type):
    year = request.args.get('year', get_jst_now().year, type=int)
    month = request.args.get('month', 0, type=int)
    client_id = request.args.get('client_id', '')
    format_type = (request.args.get('format', 'csv') or 'csv').strip().lower()

    try:
        payload = build_report_v2_payload(report_type, year, month, client_id=client_id)
    except ValueError:
        return redirect(url_for('reports'))
    except LookupError:
        return redirect(url_for('reports'))

    if format_type == 'pdf':
        filename = get_report_download_filename(payload, "pdf")
        response = make_response(build_report_pdf_bytes(payload))
        response.headers['Content-Type'] = 'application/pdf'
        response.headers['Content-Disposition'] = build_download_content_disposition(filename)
        return response

    filename = get_report_download_filename(payload, "csv")
    csv_content = build_report_csv_content(payload)
    response = make_response(csv_content)
    response.headers['Content-Type'] = 'text/csv; charset=utf-8'
    response.headers['Content-Disposition'] = build_download_content_disposition(filename)
    return response


@app.route('/api/user-announcements')
@login_required
def user_announcements_api():
    """ユーザー向けのお知らせ取得API"""
    if current_user.is_admin() or current_user.is_owner():
        return jsonify({'announcements': [], 'unread_count': 0})

    announcements = [
        serialize_announcement_payload(announcement)
        for announcement in get_active_announcements(current_user, limit=None)
    ]
    unread_count = sum(1 for announcement in announcements if not announcement.get('is_read'))
    return jsonify({'announcements': announcements, 'unread_count': unread_count})


