@app.route('/admin/users')
@login_required
@permission_required('users')
def admin_users():
    ensure_user_profile_columns()
    conn = get_db()
    fee_settings = get_fee_settings()
    plan_options = get_monthly_plan_options()
    plan_label_map = {option['key']: option['label'] for option in plan_options}
    
    # 検索クエリパラメータを取得
    search_query = request.args.get('search', '').strip()
    user_order_sql = """
        CASE
            WHEN role = 'owner' THEN 0
            WHEN role = 'admin' THEN 1
            ELSE 2
        END,
        created_at DESC,
        id DESC
    """
    
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        if search_query:
            # PostgreSQL用の検索クエリ（ユーザー名、表示名、メールで検索）
            cur.execute("""
                SELECT * FROM users 
                WHERE username ILIKE %s 
                   OR display_name ILIKE %s 
                   OR email ILIKE %s
                ORDER BY """ + user_order_sql,
            (f'%{search_query}%', f'%{search_query}%', f'%{search_query}%'))
        else:
            cur.execute("SELECT * FROM users ORDER BY " + user_order_sql)
    else:
        cur = conn.cursor()
        if search_query:
            # SQLite用の検索クエリ（ユーザー名、表示名、メールで検索）
            cur.execute("""
                SELECT * FROM users 
                WHERE username LIKE ? 
                   OR display_name LIKE ? 
                   OR email LIKE ?
                ORDER BY """ + user_order_sql,
            (f'%{search_query}%', f'%{search_query}%', f'%{search_query}%'))
        else:
            cur.execute("SELECT * FROM users ORDER BY " + user_order_sql)
        
    users = [dict(u) for u in cur.fetchall()]
    
    # 各ユーザーの当月商品数を取得
    for user in users:
        if DATABASE_URL:
            cur.execute("""
                SELECT COUNT(*) as count FROM merchandise 
                WHERE user_id = %s 
                AND DATE_TRUNC('month', COALESCE(purchase_date::date, CURRENT_DATE)) = DATE_TRUNC('month', CURRENT_DATE)
            """, (user['id'],))
            result = cur.fetchone()
            user['monthly_item_count'] = result['count'] if result else 0
        else:
            cur.execute("""
                SELECT COUNT(*) as count FROM merchandise 
                WHERE user_id = ? 
                AND strftime('%Y-%m', COALESCE(purchase_date, date('now'))) = strftime('%Y-%m', 'now')
            """, (user['id'],))
            result = cur.fetchone()
            user['monthly_item_count'] = result[0] if result else 0
        
        # 月額利用料を計算（DB設定参照）
        count = user['monthly_item_count']
        user['monthly_fee'] = get_monthly_fee(count)
        user['requested_plan_label'] = plan_label_map.get(user.get('requested_monthly_plan'), '')
        
        # 開花手数料（sale_typeがnormal以外の手数料合計）
        if DATABASE_URL:
            cur.execute("""
                SELECT COALESCE(SUM(commission), 0) as total_kaika_fee
                FROM merchandise 
                WHERE user_id = %s 
                AND sale_date IS NOT NULL
                AND COALESCE(sale_type, 'normal') != 'normal'
            """, (user['id'],))
            kaika_result = cur.fetchone()
            user['kaika_fee'] = kaika_result['total_kaika_fee'] if kaika_result else 0
        else:
            cur.execute("""
                SELECT COALESCE(SUM(commission), 0) as total_kaika_fee
                FROM merchandise 
                WHERE user_id = ? 
                AND sale_date IS NOT NULL
                AND COALESCE(sale_type, 'normal') != 'normal'
            """, (user['id'],))
            kaika_result = cur.fetchone()
            user['kaika_fee'] = kaika_result[0] if kaika_result else 0
    
    cur.close()
    conn.close()
    
    return render_template('admin/users.html', users=users, search_query=search_query, fee_settings=fee_settings)

@app.route('/admin/users/<int:id>/toggle_admin')
@login_required
@admin_required
def toggle_admin(id):
    """権限を切り替え（後方互換性のため残す）"""
    return redirect(url_for('admin_set_role', id=id, role='toggle'))

@app.route('/admin/users/<int:id>/set_role/<role>')
@login_required
@permission_required('users')
def admin_set_role(id, role):
    """ユーザーの権限を設定"""
    if id == current_user.id:
        flash('自分の権限は変更できません', 'error')
        return redirect(url_for('admin_users'))
    
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT role FROM users WHERE id = %s", (id,))
        user = cur.fetchone()
    else:
        cur = conn.cursor()
        cur.execute("SELECT role FROM users WHERE id = ?", (id,))
        user = cur.fetchone()
    
    if not user:
        flash('ユーザーが見つかりません', 'error')
        cur.close()
        conn.close()
        return redirect(url_for('admin_users'))
    
    current_role = user['role'] if isinstance(user, dict) else user[0]
    
    # toggleの場合は従来の動作
    if role == 'toggle':
        if current_role == 'owner':
            flash('オーナーの権限は変更できません', 'error')
            cur.close()
            conn.close()
            return redirect(url_for('admin_users'))
        new_role = 'user' if current_role == 'admin' else 'admin'
    else:
        # オーナー権限の設定はオーナーのみ可能
        if role == 'owner' and not current_user.is_owner():
            flash('オーナー権限の付与はオーナーのみ可能です', 'error')
            cur.close()
            conn.close()
            return redirect(url_for('admin_users'))
        
        # オーナーの権限変更はオーナーのみ可能
        if current_role == 'owner' and not current_user.is_owner():
            flash('オーナーの権限変更はオーナーのみ可能です', 'error')
            cur.close()
            conn.close()
            return redirect(url_for('admin_users'))
        
        # 有効な権限値かチェック
        if role not in ['owner', 'admin', 'user']:
            flash('無効な権限です', 'error')
            cur.close()
            conn.close()
            return redirect(url_for('admin_users'))
        
        new_role = role
    
    if DATABASE_URL:
        cur.execute("UPDATE users SET role = %s WHERE id = %s", (new_role, id))
    else:
        cur.execute("UPDATE users SET role = ? WHERE id = ?", (new_role, id))
    
    conn.commit()
    cur.close()
    conn.close()
    
    role_names = {'owner': 'オーナー', 'admin': '管理者', 'user': 'ユーザー'}
    flash(f'権限を「{role_names.get(new_role, new_role)}」に変更しました', 'success')
    return redirect(url_for('admin_users'))

@app.route('/admin/users/<int:id>/toggle_tuition_exempt')
@login_required
@permission_required('users')
def toggle_tuition_exempt(id):
    """月謝免除を切り替え"""
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT tuition_exempt FROM users WHERE id = %s", (id,))
        user = cur.fetchone()
        if user:
            current_exempt = user.get('tuition_exempt', False) or False
            new_exempt = not current_exempt
            cur.execute("UPDATE users SET tuition_exempt = %s WHERE id = %s", (new_exempt, id))
    else:
        cur = conn.cursor()
        cur.execute("SELECT tuition_exempt FROM users WHERE id = ?", (id,))
        result = cur.fetchone()
        if result:
            current_exempt = bool(result[0]) if result[0] else False
            new_exempt = not current_exempt
            cur.execute("UPDATE users SET tuition_exempt = ? WHERE id = ?", (1 if new_exempt else 0, id))
    
    conn.commit()
    cur.close()
    conn.close()
    
    if new_exempt:
        flash('月謝免除に設定しました', 'success')
    else:
        flash('月謝免除を解除しました', 'info')
    
    return redirect(url_for('admin_users'))

@app.route('/admin/users/<int:id>/delete')
@login_required
@permission_required('users')
def delete_user(id):
    if id == current_user.id:
        flash('自分は削除できません', 'error')
        return redirect(url_for('admin_users'))
    
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor()
        cur.execute("""
            DELETE FROM user_kaitori_shoudaku_items
            WHERE kaitori_shoudaku_id IN (
                SELECT id FROM user_kaitori_shoudaku WHERE user_id = %s
            )
        """, (id,))
        cur.execute("DELETE FROM user_kaitori_shoudaku WHERE user_id = %s", (id,))
        cur.execute("DELETE FROM merchandise WHERE user_id = %s", (id,))
        cur.execute("DELETE FROM customers WHERE user_id = %s", (id,))
        cur.execute("DELETE FROM users WHERE id = %s", (id,))
    else:
        cur = conn.cursor()
        cur.execute("""
            DELETE FROM user_kaitori_shoudaku_items
            WHERE kaitori_shoudaku_id IN (
                SELECT id FROM user_kaitori_shoudaku WHERE user_id = ?
            )
        """, (id,))
        cur.execute("DELETE FROM user_kaitori_shoudaku WHERE user_id = ?", (id,))
        cur.execute("DELETE FROM merchandise WHERE user_id = ?", (id,))
        cur.execute("DELETE FROM customers WHERE user_id = ?", (id,))
        cur.execute("DELETE FROM users WHERE id = ?", (id,))
    
    conn.commit()
    conn.close()
    flash('ユーザーを削除しました', 'info')
    return redirect(url_for('admin_users'))

def sync_users_id_sequence(cur):
    """Keep PostgreSQL's users.id sequence ahead of imported/restored rows."""
    if not DATABASE_URL:
        return
    cur.execute(
        """
        SELECT setval(
            pg_get_serial_sequence('users', 'id'),
            COALESCE((SELECT MAX(id) FROM users), 0) + 1,
            false
        )
        """
    )

@app.route('/admin/users/add', methods=['GET', 'POST'])
@login_required
@permission_required('users')
def admin_add_user():
    ensure_user_profile_columns()
    plan_options = get_monthly_plan_options()
    summary_period_options = get_inventory_summary_period_options()
    if request.method == 'POST':
        username = (request.form.get('username') or '').strip()
        email = (request.form.get('email') or '').strip().lower()
        password = request.form.get('password')
        display_name = (request.form.get('display_name') or '').strip()
        phone = (request.form.get('phone') or '').strip()
        postal_code = (request.form.get('postal_code') or '').strip()
        address = (request.form.get('address') or '').strip()
        inventory_summary_period_default = normalize_inventory_summary_period(request.form.get('inventory_summary_period_default'))
        requested_monthly_plan = normalize_monthly_plan_key(request.form.get('requested_monthly_plan'))
        plan_effective_month = resolve_plan_effective_month(requested_monthly_plan)
        plan_change_requested_at = get_jst_now().strftime('%Y-%m-%d %H:%M:%S') if requested_monthly_plan else None
        role = request.form.get('role', 'user')
        
        # 管理者権限の設定を取得
        admin_permissions = request.form.getlist('admin_permissions')
        admin_permissions_json = normalize_submitted_admin_permissions(role, admin_permissions)
        
        # オーナー権限の付与はオーナーのみ
        if role == 'owner' and not current_user.is_owner():
            role = 'admin'
        
        if not username or not email or not password:
            flash('ユーザー名、メール、パスワードは必須です', 'error')
            return render_template('admin/user_form.html', user=None, permission_options=User.ADMIN_PERMISSION_OPTIONS, plan_options=plan_options, summary_period_options=summary_period_options)
        
        if len(password) < 6:
            flash('パスワードは6文字以上必要です', 'error')
            return render_template('admin/user_form.html', user=None, permission_options=User.ADMIN_PERMISSION_OPTIONS, plan_options=plan_options, summary_period_options=summary_period_options)
        
        conn = get_db()
        try:
            if DATABASE_URL:
                cur = conn.cursor(cursor_factory=RealDictCursor)
                cur.execute(
                    """
                    SELECT id, username, email
                    FROM users
                    WHERE LOWER(username) = LOWER(%s) OR LOWER(email) = LOWER(%s)
                    LIMIT 1
                    """,
                    (username, email),
                )
            else:
                cur = conn.cursor()
                cur.execute(
                    """
                    SELECT id, username, email
                    FROM users
                    WHERE LOWER(username) = LOWER(?) OR LOWER(email) = LOWER(?)
                    LIMIT 1
                    """,
                    (username, email),
                )
            duplicate_user = cur.fetchone()
            cur.close()
            if duplicate_user:
                duplicate_email = duplicate_user.get('email') if isinstance(duplicate_user, dict) else duplicate_user['email']
                duplicate_username = duplicate_user.get('username') if isinstance(duplicate_user, dict) else duplicate_user['username']
                if (duplicate_email or '').lower() == email:
                    flash('すでにこのメールアドレスは使用されています。別のメールアドレスを入力してください。', 'error')
                elif (duplicate_username or '').lower() == username.lower():
                    flash('すでにこのログインIDは使用されています。別のログインIDを入力してください。', 'error')
                else:
                    flash('ログインIDまたはメールアドレスが既に使用されています。入力内容を確認してください。', 'error')
                return render_template('admin/user_form.html', user=None, permission_options=User.ADMIN_PERMISSION_OPTIONS, plan_options=plan_options, summary_period_options=summary_period_options)

            if DATABASE_URL:
                cur = conn.cursor()
                sync_users_id_sequence(cur)
                cur.execute('''
                    INSERT INTO users (
                        username, email, password_hash, role, display_name, phone, postal_code, address,
                        inventory_summary_period_default, requested_monthly_plan, plan_change_effective_month,
                        plan_change_requested_at, admin_permissions
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ''', (
                    username, email, generate_password_hash(password), role, display_name or username, phone, postal_code, address,
                    inventory_summary_period_default, requested_monthly_plan, plan_effective_month, plan_change_requested_at, admin_permissions_json
                ))
            else:
                cur = conn.cursor()
                cur.execute('''
                    INSERT INTO users (
                        username, email, password_hash, role, display_name, phone, postal_code, address,
                        inventory_summary_period_default, requested_monthly_plan, plan_change_effective_month,
                        plan_change_requested_at, admin_permissions
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ''', (
                    username, email, generate_password_hash(password), role, display_name or username, phone, postal_code, address,
                    inventory_summary_period_default, requested_monthly_plan, plan_effective_month, plan_change_requested_at, admin_permissions_json
                ))
            conn.commit()
            flash('ユーザーを作成しました', 'success')
            return redirect(url_for('admin_users'))
        except Exception as e:
            conn.rollback()
            error_text = str(e).lower()
            if 'unique' in error_text or 'duplicate' in error_text:
                flash('ログインIDまたはメールアドレスが既に使用されています。入力内容を確認してください。', 'error')
            else:
                print(f"[ERROR] admin_add_user failed: {e}", flush=True)
                flash('クライアント追加中にエラーが発生しました。入力内容を確認してもう一度お試しください。', 'error')
        finally:
            conn.close()
    
    return render_template('admin/user_form.html', user=None, permission_options=User.ADMIN_PERMISSION_OPTIONS, plan_options=plan_options, summary_period_options=summary_period_options)

