@app.route('/admin/shikiriosho/send-bulk', methods=['POST'])
@login_required
@permission_required('shikiriosho')
def admin_shikiriosho_send_bulk():
    """完成済みの精算書をまとめて送信済みにする"""
    send_scope = request.form.get('send_scope', 'selected')
    selected_ids = []
    for raw_id in request.form.getlist('document_ids'):
        try:
            selected_ids.append(int(raw_id))
        except (TypeError, ValueError):
            continue

    conn = get_db()
    updated_count = 0
    try:
        if DATABASE_URL:
            cur = conn.cursor()
            if send_scope == 'all':
                cur.execute(
                    """
                    UPDATE shikiriosho
                    SET status = 'sent', updated_at = CURRENT_TIMESTAMP
                    WHERE status = 'completed'
                    """,
                )
            elif selected_ids:
                cur.execute(
                    """
                    UPDATE shikiriosho
                    SET status = 'sent', updated_at = CURRENT_TIMESTAMP
                    WHERE status = 'completed' AND id = ANY(%s)
                    """,
                    (selected_ids,),
                )
            else:
                flash('送信対象の精算書を選択してください', 'warning')
                return redirect(url_for('admin_shikiriosho_list'))
            updated_count = cur.rowcount or 0
        else:
            cur = conn.cursor()
            if send_scope == 'all':
                cur.execute(
                    """
                    UPDATE shikiriosho
                    SET status = 'sent', updated_at = CURRENT_TIMESTAMP
                    WHERE status = 'completed'
                    """
                )
            elif selected_ids:
                placeholders = ','.join(['?'] * len(selected_ids))
                cur.execute(
                    f"""
                    UPDATE shikiriosho
                    SET status = 'sent', updated_at = CURRENT_TIMESTAMP
                    WHERE status = 'completed' AND id IN ({placeholders})
                    """,
                    tuple(selected_ids),
                )
            else:
                flash('送信対象の精算書を選択してください', 'warning')
                return redirect(url_for('admin_shikiriosho_list'))
            updated_count = cur.rowcount or 0

        conn.commit()
        flash(f'精算書を{updated_count}件送信済みにしました', 'success')
    except Exception as exc:
        conn.rollback()
        flash(f'精算書の一括送信に失敗しました: {exc}', 'error')
    finally:
        try:
            cur.close()
        except Exception:
            pass
        conn.close()

    return redirect(url_for('admin_shikiriosho_list'))


