@app.route('/documents')
@login_required
def documents():
    """統合書類管理ページ"""
    active_tab = (request.args.get('tab') or 'kaitori').strip()
    if active_tab not in {'kaitori', 'mitsumori', 'shoudaku', 'shikiri', 'keisan'}:
        active_tab = 'kaitori'
    conn = get_db()
    
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        
        # 買取明細書
        cur.execute("""
            SELECT * FROM invoices WHERE sender_id = %s ORDER BY created_at DESC
        """, (current_user.id,))
        invoices = [dict(row) for row in cur.fetchall()]
        
        # ユーザー見積依頼書
        cur.execute("""
            SELECT * FROM user_mitsumori
            WHERE user_id = %s
              AND COALESCE(status, 'draft') NOT IN ('draft', 'in_progress')
            ORDER BY created_at DESC
        """, (current_user.id,))
        user_mitsumori_list = [dict(row) for row in cur.fetchall()]

        cur.execute("""
            SELECT * FROM user_kaitori_shoudaku
            WHERE user_id = %s
              AND COALESCE(status, 'draft') <> 'draft'
            ORDER BY created_at DESC
        """, (current_user.id,))
        user_kaitori_shoudaku_list = [dict(row) for row in cur.fetchall()]
        
        # ユーザー計算書
        cur.execute("""
            SELECT * FROM user_keisan WHERE user_id = %s ORDER BY created_at DESC
        """, (current_user.id,))
        user_keisan_list = [dict(row) for row in cur.fetchall()]

        cur.execute("""
            SELECT s.*, u.display_name as sender_display_name
            FROM shikiriosho s
            LEFT JOIN users u ON s.sender_id = u.id
            WHERE s.recipient_id = %s
            ORDER BY s.issue_date DESC, s.id DESC
        """, (current_user.id,))
        shikiriosho_list = [dict(row) for row in cur.fetchall()]
    else:
        cur = conn.cursor()
        
        # 買取明細書
        cur.execute("""
            SELECT * FROM invoices WHERE sender_id = ? ORDER BY created_at DESC
        """, (current_user.id,))
        invoices = [dict(row) for row in cur.fetchall()]
        
        # ユーザー見積依頼書
        cur.execute("""
            SELECT * FROM user_mitsumori
            WHERE user_id = ?
              AND COALESCE(status, 'draft') NOT IN ('draft', 'in_progress')
            ORDER BY created_at DESC
        """, (current_user.id,))
        user_mitsumori_list = [dict(row) for row in cur.fetchall()]

        cur.execute("""
            SELECT * FROM user_kaitori_shoudaku
            WHERE user_id = ?
              AND COALESCE(status, 'draft') <> 'draft'
            ORDER BY created_at DESC
        """, (current_user.id,))
        user_kaitori_shoudaku_list = [dict(row) for row in cur.fetchall()]
        
        # ユーザー計算書
        cur.execute("""
            SELECT * FROM user_keisan WHERE user_id = ? ORDER BY created_at DESC
        """, (current_user.id,))
        user_keisan_list = [dict(row) for row in cur.fetchall()]

        cur.execute("""
            SELECT s.*, u.display_name as sender_display_name
            FROM shikiriosho s
            LEFT JOIN users u ON s.sender_id = u.id
            WHERE s.recipient_id = ?
            ORDER BY s.issue_date DESC, s.id DESC
        """, (current_user.id,))
        shikiriosho_list = [dict(row) for row in cur.fetchall()]
    
    cur.close()
    conn.close()
    
    return render_template('documents.html',
                          invoices=invoices,
                          user_mitsumori_list=user_mitsumori_list,
                          user_kaitori_shoudaku_list=user_kaitori_shoudaku_list,
                          user_keisan_list=user_keisan_list,
                          shikiriosho_list=shikiriosho_list,
                          active_tab=active_tab)


