@login_required
def admin_line_scheduled_toggle(id):
    """定期送信メッセージの有効/無効切り替え"""
    if not current_user.is_owner():
        return jsonify({'success': False, 'error': '権限がありません'}), 403
    
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT is_enabled FROM line_scheduled_messages WHERE id = %s", (id,))
        msg = cur.fetchone()
        if msg:
            new_value = not msg['is_enabled']
            cur.execute("UPDATE line_scheduled_messages SET is_enabled = %s WHERE id = %s", (new_value, id))
    else:
        cur = conn.cursor()
        cur.execute("SELECT is_enabled FROM line_scheduled_messages WHERE id = ?", (id,))
        msg = cur.fetchone()
        if msg:
            new_value = 0 if msg[0] else 1
            cur.execute("UPDATE line_scheduled_messages SET is_enabled = ? WHERE id = ?", (new_value, id))
    
    conn.commit()
    cur.close()
    conn.close()
    
    return jsonify({'success': True})

@app.route('/admin/line/preview-report', methods=['POST'])
@login_required
def admin_line_preview_report():
    """レポートのプレビュー生成"""
    if not current_user.is_owner():
        return jsonify({'success': False, 'error': '権限がありません'}), 403
    
    data = request.get_json()
    message_content = data.get('message_content', '')
    report_type = data.get('report_type', '')
    
    try:
        if report_type == 'weekly_report':
            report_data = generate_weekly_report()
            preview = message_content.replace('{weekly_report}', report_data)
        elif report_type == 'monthly_report':
            report_data = generate_monthly_report()
            preview = message_content.replace('{monthly_report}', report_data)
        elif report_type == 'monthly_fee':
            report_data = generate_monthly_fee_report()
            preview = message_content.replace('{monthly_fee}', report_data)
        else:
            preview = message_content
        
        return jsonify({'success': True, 'preview': preview})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})


@app.route('/admin/line-v2')
@login_required
def admin_line_dashboard_v2():
    if not current_user.is_owner():
        flash('この機能はオーナーのみ利用できます', 'error')
        return redirect(url_for('index'))

    ensure_line_multi_account_schema()
    accounts = fetch_line_accounts()
    active_accounts_count = sum(1 for account in accounts if account.get('is_enabled'))

    conn = get_db()
    try:
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            cur.execute("SELECT COUNT(*) AS count FROM users WHERE line_user_id IS NOT NULL")
            linked_users = (cur.fetchone() or {}).get('count', 0)
            cur.execute(
                """
                SELECT lsm.*, la.account_name
                FROM line_scheduled_messages lsm
                LEFT JOIN line_accounts la ON lsm.line_account_id = la.id
                ORDER BY lsm.id DESC
                """
            )
            scheduled_messages = [dict(row) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT lml.*, la.account_name, u.display_name AS sent_by_name
                FROM line_message_logs lml
                LEFT JOIN line_accounts la ON lml.line_account_id = la.id
                LEFT JOIN users u ON lml.sent_by = u.id
                ORDER BY lml.sent_at DESC
                LIMIT 20
                """
            )
            logs = [dict(row) for row in cur.fetchall()]
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("SELECT COUNT(*) AS count FROM users WHERE line_user_id IS NOT NULL")
            linked_users = dict(cur.fetchone())['count']
            cur.execute(
                """
                SELECT lsm.*, la.account_name
                FROM line_scheduled_messages lsm
                LEFT JOIN line_accounts la ON lsm.line_account_id = la.id
                ORDER BY lsm.id DESC
                """
            )
            scheduled_messages = [dict(row) for row in cur.fetchall()]
            cur.execute(
                """
                SELECT lml.*, la.account_name, u.display_name AS sent_by_name
                FROM line_message_logs lml
                LEFT JOIN line_accounts la ON lml.line_account_id = la.id
                LEFT JOIN users u ON lml.sent_by = u.id
                ORDER BY lml.sent_at DESC
                LIMIT 20
                """
            )
            logs = [dict(row) for row in cur.fetchall()]
    finally:
        cur.close()
        conn.close()

    return render_template(
        'admin/line_dashboard_v2.html',
        accounts=accounts,
        active_accounts_count=active_accounts_count,
        linked_users=linked_users,
        scheduled_messages=scheduled_messages,
        logs=logs,
    )


