@app.route('/stripe/webhook', methods=['POST'])
def stripe_webhook():
    """Stripe Webhookエンドポイント"""
    if not STRIPE_ENABLED:
        return jsonify({'error': 'Stripe not enabled'}), 400
    
    payload = request.get_data()
    sig_header = request.headers.get('Stripe-Signature')
    
    try:
        if STRIPE_WEBHOOK_SECRET:
            event = stripe.Webhook.construct_event(
                payload, sig_header, STRIPE_WEBHOOK_SECRET
            )
        else:
            event = json.loads(payload)
    except ValueError as e:
        return jsonify({'error': 'Invalid payload'}), 400
    except stripe.error.SignatureVerificationError as e:
        return jsonify({'error': 'Invalid signature'}), 400
    
    # イベント処理
    event_type = event['type']
    
    # サブスクリプション作成完了
    if event_type == 'customer.subscription.created':
        subscription = event['data']['object']
        customer_id = subscription['customer']
        subscription_id = subscription['id']
        
        conn = get_db()
        cur = conn.cursor()
        
        current_period_end = datetime.fromtimestamp(subscription['current_period_end'])
        now = get_jst_now()
        
        if DATABASE_URL:
            cur.execute("""
                UPDATE users 
                SET stripe_subscription_id = %s,
                    subscription_status = 'active',
                    last_payment_date = %s,
                    next_payment_date = %s
                WHERE stripe_customer_id = %s
            """, (subscription_id, now, current_period_end, customer_id))
        else:
            cur.execute("""
                UPDATE users 
                SET stripe_subscription_id = ?,
                    subscription_status = 'active',
                    last_payment_date = ?,
                    next_payment_date = ?
                WHERE stripe_customer_id = ?
            """, (subscription_id, now, current_period_end, customer_id))
        
        conn.commit()
        cur.close()
        conn.close()
    
    # サブスクリプション更新（毎月の支払い成功）
    elif event_type == 'invoice.payment_succeeded':
        invoice = event['data']['object']
        subscription_id = invoice.get('subscription')
        
        if subscription_id:
            conn = get_db()
            cur = conn.cursor()
            
            # サブスクリプション情報を取得して次回支払日を更新
            try:
                subscription = stripe.Subscription.retrieve(subscription_id)
                current_period_end = datetime.fromtimestamp(subscription['current_period_end'])
                now = get_jst_now()
                
                if DATABASE_URL:
                    cur.execute("""
                        UPDATE users 
                        SET subscription_status = 'active',
                            last_payment_date = %s,
                            next_payment_date = %s
                        WHERE stripe_subscription_id = %s
                    """, (now, current_period_end, subscription_id))
                else:
                    cur.execute("""
                        UPDATE users 
                        SET subscription_status = 'active',
                            last_payment_date = ?,
                            next_payment_date = ?
                        WHERE stripe_subscription_id = ?
                    """, (now, current_period_end, subscription_id))
                
                conn.commit()
            except Exception as e:
                print(f"Webhook invoice.payment_succeeded error: {e}")
            finally:
                cur.close()
                conn.close()
    
    # 支払い失敗
    elif event_type == 'invoice.payment_failed':
        invoice = event['data']['object']
        subscription_id = invoice.get('subscription')
        
        if subscription_id:
            conn = get_db()
            cur = conn.cursor(cursor_factory=RealDictCursor) if DATABASE_URL else conn.cursor()
            
            # ユーザー情報を取得
            if DATABASE_URL:
                cur.execute("""
                    SELECT id, display_name, username, line_user_id, email, overdue_since 
                    FROM users WHERE stripe_subscription_id = %s
                """, (subscription_id,))
            else:
                cur.execute("""
                    SELECT id, display_name, username, line_user_id, email, overdue_since 
                    FROM users WHERE stripe_subscription_id = ?
                """, (subscription_id,))
            
            user = cur.fetchone()
            
            if user:
                user_dict = dict(user) if DATABASE_URL else {
                    'id': user[0], 'display_name': user[1], 'username': user[2],
                    'line_user_id': user[3], 'email': user[4], 'overdue_since': user[5]
                }
                
                # 未払い開始日を記録（初回のみ）
                if DATABASE_URL:
                    cur.execute("""
                        UPDATE users 
                        SET subscription_status = 'past_due',
                            overdue_since = COALESCE(overdue_since, CURRENT_TIMESTAMP)
                        WHERE stripe_subscription_id = %s
                    """, (subscription_id,))
                else:
                    cur.execute("""
                        UPDATE users 
                        SET subscription_status = 'past_due',
                            overdue_since = COALESCE(overdue_since, CURRENT_TIMESTAMP)
                        WHERE stripe_subscription_id = ?
                    """, (subscription_id,))
                
                # LINE通知送信
                line_user_id = user_dict.get('line_user_id')
                display_name = user_dict.get('display_name') or user_dict.get('username') or 'ユーザー'
                
                if line_user_id:
                    message = f"""⚠️ 月謝のお支払いが確認できませんでした

{display_name}様

今月の月謝のお支払いが確認できませんでした。
お早めにお支払いをお願いいたします。

━━━━━━━━━━━━━━━━━
【重要なお知らせ】
━━━━━━━━━━━━━━━━━
・未払い期間中は画面の閲覧と商品処分のみ可能です
・商品の追加・編集はできなくなります
・3ヶ月以上未払いが続くと、ログインができなくなり商品は自動的に管理者へ移管されます

ご不明点がございましたらお問い合わせください。"""
                    try:
                        send_line_push(line_user_id, message)
                    except Exception as e:
                        print(f"LINE notification error: {e}")
            else:
                # ユーザーが見つからない場合は従来の処理
                if DATABASE_URL:
                    cur.execute("""
                        UPDATE users SET subscription_status = 'past_due'
                        WHERE stripe_subscription_id = %s
                    """, (subscription_id,))
                else:
                    cur.execute("""
                        UPDATE users SET subscription_status = 'past_due'
                        WHERE stripe_subscription_id = ?
                    """, (subscription_id,))
            
            conn.commit()
            cur.close()
            conn.close()
    
    # サブスクリプションキャンセル
    elif event_type == 'customer.subscription.deleted':
        subscription = event['data']['object']
        subscription_id = subscription['id']
        
        conn = get_db()
        cur = conn.cursor()
        
        if DATABASE_URL:
            cur.execute("""
                UPDATE users 
                SET stripe_subscription_id = NULL,
                    subscription_status = 'canceled'
                WHERE stripe_subscription_id = %s
            """, (subscription_id,))
        else:
            cur.execute("""
                UPDATE users 
                SET stripe_subscription_id = NULL,
                    subscription_status = 'canceled'
                WHERE stripe_subscription_id = ?
            """, (subscription_id,))
        
        conn.commit()
        cur.close()
        conn.close()
    
    # サブスクリプション更新（プラン変更など）
    elif event_type == 'customer.subscription.updated':
        subscription = event['data']['object']
        subscription_id = subscription['id']
        status = subscription['status']
        
        conn = get_db()
        cur = conn.cursor()
        
        current_period_end = datetime.fromtimestamp(subscription['current_period_end'])
        
        # Stripeのステータスをマッピング
        status_map = {
            'active': 'active',
            'past_due': 'past_due',
            'canceled': 'canceled',
            'unpaid': 'unpaid',
            'trialing': 'active'
        }
        mapped_status = status_map.get(status, status)
        
        if DATABASE_URL:
            cur.execute("""
                UPDATE users 
                SET subscription_status = %s,
                    next_payment_date = %s
                WHERE stripe_subscription_id = %s
            """, (mapped_status, current_period_end, subscription_id))
        else:
            cur.execute("""
                UPDATE users 
                SET subscription_status = ?,
                    next_payment_date = ?
                WHERE stripe_subscription_id = ?
            """, (mapped_status, current_period_end, subscription_id))
        
        conn.commit()
        cur.close()
        conn.close()
    
    return jsonify({'received': True})

# ===================
# 月末バッチ処理（料金自動更新）
# ===================

@app.route('/admin/stripe/batch-update', methods=['POST'])
@login_required
@admin_required
def admin_stripe_batch_update():
    """月末バッチ処理：全ユーザーの料金プランを商品数に基づいて自動更新"""
    if not STRIPE_ENABLED or not STRIPE_SECRET_KEY:
        return jsonify({'success': False, 'error': 'Stripe連携が設定されていません'})
    
    conn = get_db()
    results = {
        'processed': 0,
        'updated': 0,
        'unchanged': 0,
        'errors': 0,
        'details': []
    }
    
    try:
        if DATABASE_URL:
            from psycopg2.extras import RealDictCursor
            cur = conn.cursor(cursor_factory=RealDictCursor)
            # サブスク登録済みユーザーを取得
            cur.execute("""
                SELECT u.id, u.username, u.display_name, u.email,
                       u.stripe_customer_id, u.stripe_subscription_id,
                       COUNT(m.id) as item_count
                FROM users u
                LEFT JOIN merchandise m ON u.id = m.user_id
                WHERE u.stripe_subscription_id IS NOT NULL
                  AND u.subscription_status = 'active'
                GROUP BY u.id
            """)
            users = cur.fetchall()
            users = [dict(row) for row in users]
        else:
            cur = conn.cursor()
            cur.execute("""
                SELECT u.id, u.username, u.display_name, u.email,
                       u.stripe_customer_id, u.stripe_subscription_id,
                       COUNT(m.id) as item_count
                FROM users u
                LEFT JOIN merchandise m ON u.id = m.user_id
                WHERE u.stripe_subscription_id IS NOT NULL
                  AND u.subscription_status = 'active'
                GROUP BY u.id
            """)
            users = [dict(row) for row in cur.fetchall()]
        
        for user in users:
            results['processed'] += 1
            user_name = user.get('display_name') or user.get('username')
            subscription_id = user.get('stripe_subscription_id')
            
            try:
                # 現在の商品数から新しい月額を計算
                item_count = user.get('item_count', 0) or 0
                new_monthly_fee = get_monthly_fee(item_count)
                
                # 現在のサブスクリプション情報を取得
                subscription = stripe.Subscription.retrieve(subscription_id)
                current_price_id = subscription['items']['data'][0]['price']['id']
                current_price = stripe.Price.retrieve(current_price_id)
                current_fee = current_price.unit_amount
                
                if current_fee == new_monthly_fee:
                    # 料金変更なし
                    results['unchanged'] += 1
                    results['details'].append({
                        'user': user_name,
                        'status': 'unchanged',
                        'fee': current_fee,
                        'item_count': item_count
                    })
                else:
                    # 料金変更あり → プラン更新
                    new_price_id = get_or_create_stripe_price(new_monthly_fee)
                    if new_price_id:
                        stripe.Subscription.modify(
                            subscription_id,
                            items=[{
                                'id': subscription['items']['data'][0]['id'],
                                'price': new_price_id,
                            }],
                            proration_behavior='none',  # 日割り計算なし（月末締めなので）
                            metadata={
                                'previous_fee': str(current_fee),
                                'new_fee': str(new_monthly_fee),
                                'updated_at': get_jst_now().isoformat(),
                                'batch_update': 'true'
                            }
                        )
                        
                        results['updated'] += 1
                        results['details'].append({
                            'user': user_name,
                            'status': 'updated',
                            'previous_fee': current_fee,
                            'new_fee': new_monthly_fee,
                            'item_count': item_count
                        })
                    else:
                        results['errors'] += 1
                        results['details'].append({
                            'user': user_name,
                            'status': 'error',
                            'error': '料金プランの作成に失敗'
                        })
                        
            except Exception as e:
                results['errors'] += 1
                results['details'].append({
                    'user': user_name,
                    'status': 'error',
                    'error': str(e)
                })
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': f"処理完了: {results['processed']}件処理, {results['updated']}件更新, {results['unchanged']}件変更なし, {results['errors']}件エラー",
            'results': results
        })
        
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        })

@app.route('/api/stripe/batch-update', methods=['POST'])
def api_stripe_batch_update():
    """外部からのバッチ実行用API（cronやスケジューラー用）
    
    セキュリティのため、環境変数BATCH_API_KEYを設定し、
    リクエストヘッダーにX-API-Key: <key>を含める必要があります。
    """
    api_key = os.environ.get('BATCH_API_KEY', '')
    request_key = request.headers.get('X-API-Key', '')
    
    if not api_key or api_key != request_key:
        return jsonify({'success': False, 'error': 'Invalid API key'}), 401
    
    if not STRIPE_ENABLED or not STRIPE_SECRET_KEY:
        return jsonify({'success': False, 'error': 'Stripe not configured'}), 400
    
    conn = get_db()
    results = {
        'processed': 0,
        'updated': 0,
        'unchanged': 0,
        'errors': 0,
        'timestamp': get_jst_now().isoformat()
    }
    
    try:
        if DATABASE_URL:
            from psycopg2.extras import RealDictCursor
            cur = conn.cursor(cursor_factory=RealDictCursor)
            cur.execute("""
                SELECT u.id, u.username, u.display_name,
                       u.stripe_subscription_id,
                       COUNT(m.id) as item_count
                FROM users u
                LEFT JOIN merchandise m ON u.id = m.user_id
                WHERE u.stripe_subscription_id IS NOT NULL
                  AND u.subscription_status = 'active'
                GROUP BY u.id
            """)
            users = cur.fetchall()
            users = [dict(row) for row in users]
        else:
            cur = conn.cursor()
            cur.execute("""
                SELECT u.id, u.username, u.display_name,
                       u.stripe_subscription_id,
                       COUNT(m.id) as item_count
                FROM users u
                LEFT JOIN merchandise m ON u.id = m.user_id
                WHERE u.stripe_subscription_id IS NOT NULL
                  AND u.subscription_status = 'active'
                GROUP BY u.id
            """)
            users = [dict(row) for row in cur.fetchall()]
        
        for user in users:
            results['processed'] += 1
            subscription_id = user.get('stripe_subscription_id')
            
            try:
                item_count = user.get('item_count', 0) or 0
                new_monthly_fee = get_monthly_fee(item_count)
                
                subscription = stripe.Subscription.retrieve(subscription_id)
                current_price_id = subscription['items']['data'][0]['price']['id']
                current_price = stripe.Price.retrieve(current_price_id)
                current_fee = current_price.unit_amount
                
                if current_fee == new_monthly_fee:
                    results['unchanged'] += 1
                else:
                    new_price_id = get_or_create_stripe_price(new_monthly_fee)
                    if new_price_id:
                        stripe.Subscription.modify(
                            subscription_id,
                            items=[{
                                'id': subscription['items']['data'][0]['id'],
                                'price': new_price_id,
                            }],
                            proration_behavior='none'
                        )
                        results['updated'] += 1
                    else:
                        results['errors'] += 1
                        
            except Exception as e:
                results['errors'] += 1
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'results': results
        })
        
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

# ===================
# 月末自動スケジューラー
# ===================

def run_monthly_batch_update():
    """月末バッチ処理（スケジューラーから呼び出し）"""
    if not STRIPE_ENABLED or not STRIPE_SECRET_KEY:
        print(f"[{get_jst_now()}] Monthly batch skipped: Stripe not configured")
        return
    
    print(f"[{get_jst_now()}] Starting monthly batch update...")
    
    with app.app_context():
        conn = get_db()
        results = {'processed': 0, 'updated': 0, 'unchanged': 0, 'errors': 0}
        
        try:
            if DATABASE_URL:
                from psycopg2.extras import RealDictCursor
                cur = conn.cursor(cursor_factory=RealDictCursor)
                cur.execute("""
                    SELECT u.id, u.username, u.display_name,
                           u.stripe_subscription_id,
                           COUNT(m.id) as item_count
                    FROM users u
                    LEFT JOIN merchandise m ON u.id = m.user_id
                    WHERE u.stripe_subscription_id IS NOT NULL
                      AND u.subscription_status = 'active'
                    GROUP BY u.id
                """)
                users = cur.fetchall()
                users = [dict(row) for row in users]
            else:
                cur = conn.cursor()
                cur.execute("""
                    SELECT u.id, u.username, u.display_name,
                           u.stripe_subscription_id,
                           COUNT(m.id) as item_count
                    FROM users u
                    LEFT JOIN merchandise m ON u.id = m.user_id
                    WHERE u.stripe_subscription_id IS NOT NULL
                      AND u.subscription_status = 'active'
                    GROUP BY u.id
                """)
                users = [dict(row) for row in cur.fetchall()]
            
            for user in users:
                results['processed'] += 1
                subscription_id = user.get('stripe_subscription_id')
                user_name = user.get('display_name') or user.get('username')
                
                try:
                    item_count = user.get('item_count', 0) or 0
                    new_monthly_fee = get_monthly_fee(item_count)
                    
                    subscription = stripe.Subscription.retrieve(subscription_id)
                    current_price_id = subscription['items']['data'][0]['price']['id']
                    current_price = stripe.Price.retrieve(current_price_id)
                    current_fee = current_price.unit_amount
                    
                    if current_fee == new_monthly_fee:
                        results['unchanged'] += 1
                    else:
                        new_price_id = get_or_create_stripe_price(new_monthly_fee)
                        if new_price_id:
                            stripe.Subscription.modify(
                                subscription_id,
                                items=[{
                                    'id': subscription['items']['data'][0]['id'],
                                    'price': new_price_id,
                                }],
                                proration_behavior='none'
                            )
                            results['updated'] += 1
                            print(f"  Updated {user_name}: ¥{current_fee:,} → ¥{new_monthly_fee:,}")
                        else:
                            results['errors'] += 1
                            
                except Exception as e:
                    results['errors'] += 1
                    print(f"  Error for {user_name}: {e}")
            
            cur.close()
            conn.close()
            
            print(f"[{get_jst_now()}] Monthly batch completed: "
                  f"{results['processed']} processed, {results['updated']} updated, "
                  f"{results['unchanged']} unchanged, {results['errors']} errors")
            
        except Exception as e:
            print(f"[{get_jst_now()}] Monthly batch failed: {e}")

# スケジューラー初期化
scheduler = None

def init_scheduler():
    """スケジューラーを初期化"""
    global scheduler
    
    if not SCHEDULER_ENABLED:
        print("APScheduler not installed, skipping scheduler initialization")
        return
    
    # 既にスケジューラーが動作中の場合はスキップ
    if scheduler is not None and scheduler.running:
        return
    
    scheduler = BackgroundScheduler(timezone='Asia/Tokyo')
    
    # 月末23:59に実行（毎月最終日）
    # day='last' は月の最終日を意味する
    scheduler.add_job(
        run_monthly_batch_update,
        CronTrigger(day='last', hour=23, minute=59, timezone='Asia/Tokyo'),
        id='monthly_subscription_update',
        name='月末サブスクリプション料金更新',
        replace_existing=True
    )
    
    # LINE定期送信（毎分チェック）
    scheduler.add_job(
        run_scheduled_line_messages,
        CronTrigger(minute='*', timezone='Asia/Tokyo'),
        id='line_scheduled_messages',
        name='LINE定期送信',
        replace_existing=True
    )
    
    # 未払い商品の自動移動（毎日午前3時に実行）
    scheduler.add_job(
        check_and_transfer_overdue_items,
        CronTrigger(hour=3, minute=0, timezone='Asia/Tokyo'),
        id='overdue_items_transfer',
        name='未払い商品自動移動',
        replace_existing=True
    )
    
    # 長期在庫商品の自動移動（毎日午前4時に実行）
    scheduler.add_job(
        check_and_transfer_long_term_items,
        CronTrigger(hour=4, minute=0, timezone='Asia/Tokyo'),
        id='long_term_items_transfer',
        name='長期在庫商品自動移動',
        replace_existing=True
    )
    
    scheduler.start()
    print(f"[{get_jst_now()}] Scheduler started: Monthly batch will run on last day of each month at 23:59 JST")
    print(f"[{get_jst_now()}] Scheduler started: LINE scheduled messages will be checked every minute")
    print(f"[{get_jst_now()}] Scheduler started: Overdue items check will run daily at 03:00 JST")

