@app.route('/admin/inquiries')
@login_required
def admin_inquiries():
    """管理者：問い合わせ一覧"""
    if not current_user.is_admin():
        flash('アクセス権限がありません', 'error')
        return redirect(url_for('index'))
    
    status_filter = request.args.get('status', '')
    
    try:
        conn = get_db()
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            if status_filter:
                cur.execute('''
                    SELECT i.id, i.user_id, i.category, i.title, i.content, i.status,
                           i.created_at, i.updated_at,
                           u.display_name, u.username,
                           (SELECT COUNT(*) FROM inquiry_replies WHERE inquiry_id = i.id) as reply_count
                    FROM inquiries i
                    JOIN users u ON i.user_id = u.id
                    WHERE i.status = %s
                    ORDER BY 
                        CASE WHEN i.status = 'new' THEN 0 
                             WHEN i.status = 'in_progress' THEN 1 
                             ELSE 2 END,
                        i.updated_at DESC
                ''', (status_filter,))
            else:
                cur.execute('''
                    SELECT i.id, i.user_id, i.category, i.title, i.content, i.status,
                           i.created_at, i.updated_at,
                           u.display_name, u.username,
                           (SELECT COUNT(*) FROM inquiry_replies WHERE inquiry_id = i.id) as reply_count
                    FROM inquiries i
                    JOIN users u ON i.user_id = u.id
                    ORDER BY 
                        CASE WHEN i.status = 'new' THEN 0 
                             WHEN i.status = 'in_progress' THEN 1 
                             ELSE 2 END,
                        i.updated_at DESC
                ''')
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            if status_filter:
                cur.execute('''
                    SELECT i.*, u.display_name, u.username,
                           (SELECT COUNT(*) FROM inquiry_replies WHERE inquiry_id = i.id) as reply_count
                    FROM inquiries i
                    JOIN users u ON i.user_id = u.id
                    WHERE i.status = ?
                    ORDER BY 
                        CASE WHEN i.status = 'new' THEN 0 
                             WHEN i.status = 'in_progress' THEN 1 
                             ELSE 2 END,
                        i.updated_at DESC
                ''', (status_filter,))
            else:
                cur.execute('''
                    SELECT i.*, u.display_name, u.username,
                           (SELECT COUNT(*) FROM inquiry_replies WHERE inquiry_id = i.id) as reply_count
                    FROM inquiries i
                    JOIN users u ON i.user_id = u.id
                    ORDER BY 
                        CASE WHEN i.status = 'new' THEN 0 
                             WHEN i.status = 'in_progress' THEN 1 
                             ELSE 2 END,
                        i.updated_at DESC
                ''')
        
        rows = cur.fetchall()
        inquiries = []
        for row in rows:
            inquiry = dict(row)
            # datetime を文字列に変換
            if inquiry.get('created_at') and hasattr(inquiry['created_at'], 'strftime'):
                inquiry['created_at'] = inquiry['created_at'].strftime('%Y-%m-%d %H:%M:%S')
            if inquiry.get('updated_at') and hasattr(inquiry['updated_at'], 'strftime'):
                inquiry['updated_at'] = inquiry['updated_at'].strftime('%Y-%m-%d %H:%M:%S')
            inquiries.append(inquiry)
        
        # 新着件数を取得（存在するユーザーの問い合わせのみ）
        if DATABASE_URL:
            cur.execute("""
                SELECT COUNT(*) as count FROM inquiries i
                JOIN users u ON i.user_id = u.id
                WHERE i.status = 'new'
            """)
            result = cur.fetchone()
            new_count = result['count'] if result and isinstance(result, dict) else (result[0] if result else 0)
        else:
            cur.execute("""
                SELECT COUNT(*) FROM inquiries i
                JOIN users u ON i.user_id = u.id
                WHERE i.status = 'new'
            """)
            result = cur.fetchone()
            new_count = result[0] if result else 0
        
        cur.close()
        conn.close()
        
        return render_template('admin/inquiries.html',
                             inquiries=inquiries,
                             categories=INQUIRY_CATEGORIES,
                             statuses=INQUIRY_STATUS,
                             status_filter=status_filter,
                             new_count=new_count)
    except Exception as e:
        import traceback
        traceback.print_exc()
        print(f"[ERROR] admin_inquiries error: {e}", flush=True)
        flash(f'問い合わせの読み込みでエラーが発生しました: {str(e)[:100]}', 'error')
        return render_template('admin/inquiries.html',
                             inquiries=[],
                             categories=INQUIRY_CATEGORIES,
                             statuses=INQUIRY_STATUS,
                             status_filter='',
                             new_count=0)

@app.route('/admin/inquiry/<int:id>')
@login_required
def admin_inquiry_view(id):
    """管理者：問い合わせ詳細"""
    if not current_user.is_admin():
        flash('アクセス権限がありません', 'error')
        return redirect(url_for('index'))
    
    try:
        conn = get_db()
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            cur.execute('''
                SELECT i.*, u.display_name, u.username, u.email
                FROM inquiries i
                JOIN users u ON i.user_id = u.id
                WHERE i.id = %s
            ''', (id,))
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute('''
                SELECT i.*, u.display_name, u.username, u.email
                FROM inquiries i
                JOIN users u ON i.user_id = u.id
                WHERE i.id = ?
            ''', (id,))
        
        inquiry = cur.fetchone()
        if not inquiry:
            cur.close()
            conn.close()
            flash('お問い合わせが見つかりません', 'error')
            return redirect(url_for('admin_inquiries'))
        
        inquiry = dict(inquiry)
        if inquiry.get('status') == 'new':
            if DATABASE_URL:
                cur.execute(
                    "UPDATE inquiries SET status = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
                    ('in_progress', id)
                )
            else:
                cur.execute(
                    "UPDATE inquiries SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                    ('in_progress', id)
                )
            conn.commit()
            inquiry['status'] = 'in_progress'
            inquiry['updated_at'] = get_jst_now().strftime('%Y-%m-%d %H:%M:%S')
        # datetime を文字列に変換
        if inquiry.get('created_at') and hasattr(inquiry['created_at'], 'strftime'):
            inquiry['created_at'] = inquiry['created_at'].strftime('%Y-%m-%d %H:%M:%S')
        if inquiry.get('updated_at') and hasattr(inquiry['updated_at'], 'strftime'):
            inquiry['updated_at'] = inquiry['updated_at'].strftime('%Y-%m-%d %H:%M:%S')
        image_paths = parse_inquiry_image_paths(inquiry.get('image_path'))
        
        # 返信を取得
        if DATABASE_URL:
            cur.execute('''
                SELECT r.*, u.display_name, u.username, u.role
                FROM inquiry_replies r
                JOIN users u ON r.user_id = u.id
                WHERE r.inquiry_id = %s
                ORDER BY r.created_at ASC
            ''', (id,))
        else:
            cur.execute('''
                SELECT r.*, u.display_name, u.username, u.role
                FROM inquiry_replies r
                JOIN users u ON r.user_id = u.id
                WHERE r.inquiry_id = ?
                ORDER BY r.created_at ASC
            ''', (id,))
        
        replies = []
        for row in cur.fetchall():
            reply = dict(row)
            if reply.get('created_at') and hasattr(reply['created_at'], 'strftime'):
                reply['created_at'] = reply['created_at'].strftime('%Y-%m-%d %H:%M:%S')
            replies.append(reply)
        
        cur.close()
        conn.close()
        
        return render_template('admin/inquiry_view.html',
                             inquiry=inquiry,
                             image_paths=image_paths,
                             replies=replies,
                             categories=INQUIRY_CATEGORIES,
                             statuses=INQUIRY_STATUS)
    except Exception as e:
        print(f"[ERROR] admin_inquiry_view: {e}", flush=True)
        flash('問い合わせの読み込みでエラーが発生しました', 'error')
        return redirect(url_for('admin_inquiries'))

@app.route('/admin/inquiry/<int:id>/reply', methods=['POST'])
@login_required
def admin_inquiry_reply(id):
    """管理者：問い合わせに返信"""
    if not current_user.is_admin():
        flash('アクセス権限がありません', 'error')
        return redirect(url_for('index'))
    
    content = request.form.get('content', '').strip()
    new_status = request.form.get('status', '')
    
    if not content:
        flash('返信内容を入力してください', 'error')
        return redirect(url_for('admin_inquiry_view', id=id))
    
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor()
        # 返信を追加
        cur.execute('''
            INSERT INTO inquiry_replies (inquiry_id, user_id, content, is_admin_reply)
            VALUES (%s, %s, %s, TRUE)
        ''', (id, current_user.id, content))
        
        # ステータス更新
        if new_status:
            cur.execute('UPDATE inquiries SET status = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s', (new_status, id))
        else:
            cur.execute('UPDATE inquiries SET updated_at = CURRENT_TIMESTAMP WHERE id = %s', (id,))
    else:
        cur = conn.cursor()
        cur.execute('''
            INSERT INTO inquiry_replies (inquiry_id, user_id, content, is_admin_reply)
            VALUES (?, ?, ?, 1)
        ''', (id, current_user.id, content))
        
        if new_status:
            cur.execute('UPDATE inquiries SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', (new_status, id))
        else:
            cur.execute('UPDATE inquiries SET updated_at = CURRENT_TIMESTAMP WHERE id = ?', (id,))
    
    conn.commit()
    cur.close()
    conn.close()
    
    flash('返信を送信しました', 'success')
    return redirect(url_for('admin_inquiry_view', id=id))

@app.route('/admin/inquiry/<int:id>/status', methods=['POST'])
@login_required
def admin_inquiry_status(id):
    """管理者：ステータス変更"""
    if not current_user.is_admin():
        return jsonify({'success': False, 'error': 'アクセス権限がありません'}), 403
    
    data = request.get_json()
    new_status = data.get('status', '')
    
    if new_status not in INQUIRY_STATUS:
        return jsonify({'success': False, 'error': '無効なステータスです'}), 400
    
    conn = get_db()
    if DATABASE_URL:
        cur = conn.cursor()
        cur.execute('UPDATE inquiries SET status = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s', (new_status, id))
    else:
        cur = conn.cursor()
        cur.execute('UPDATE inquiries SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?', (new_status, id))
    
    conn.commit()
    cur.close()
    conn.close()
    
    return jsonify({'success': True, 'status': new_status, 'status_label': INQUIRY_STATUS[new_status]})

# 管理者サイドバーの通知数は1リクエスト内で使い回す
def get_admin_sidebar_counts():
    defaults = {
        'unread_inquiry_count': 0,
        'pending_disposal_count': 0,
        'sale_requests_by_type': {},
        'pending_sale_request_count': 0,
        'sales_agency_by_service': {},
        'pending_sales_agency_count': 0,
    }
    if not has_request_context() or not current_user.is_authenticated or not current_user.is_admin():
        return defaults.copy()
    if hasattr(g, 'admin_sidebar_counts'):
        return g.admin_sidebar_counts

    counts = {
        'unread_inquiry_count': 0,
        'pending_disposal_count': 0,
        'sale_requests_by_type': {},
        'pending_sale_request_count': 0,
        'sales_agency_by_service': {},
        'pending_sales_agency_count': 0,
    }
    conn = None
    cur = None
    try:
        conn = get_db()
        cur = conn.cursor()

        cur.execute("""
            SELECT COUNT(*)
            FROM inquiries i
            JOIN users u ON i.user_id = u.id
            WHERE i.status = 'new'
        """)
        row = cur.fetchone()
        counts['unread_inquiry_count'] = int(row[0] if row else 0)

        cur.execute("SELECT COUNT(*) FROM item_disposal_requests WHERE status = 'pending'")
        row = cur.fetchone()
        counts['pending_disposal_count'] = int(row[0] if row else 0)

        cur.execute("""
            SELECT request_type, COUNT(*)
            FROM sale_requests
            WHERE status = 'pending'
            GROUP BY request_type
        """)
        sale_counts = {}
        for request_type, count in cur.fetchall():
            sale_counts[normalize_sale_request_type(request_type)] = int(count or 0)
        counts['sale_requests_by_type'] = sale_counts
        counts['pending_sale_request_count'] = sum(sale_counts.values())

        cur.execute("""
            SELECT service_type, COUNT(*)
            FROM sales_agency_requests
            WHERE status = 'pending'
            GROUP BY service_type
        """)
        agency_counts = {}
        for service_type, count in cur.fetchall():
            agency_counts[(service_type or '').strip()] = int(count or 0)
        counts['sales_agency_by_service'] = agency_counts
        counts['pending_sales_agency_count'] = sum(agency_counts.values())
    except Exception as e:
        print(f"get_admin_sidebar_counts error: {e}", flush=True)
    finally:
        if cur:
            try:
                cur.close()
            except Exception:
                pass
        if conn:
            try:
                conn.close()
            except Exception:
                pass

    g.admin_sidebar_counts = counts
    return counts


