@login_required
@admin_required
def admin_documents_history_v2():
    filters = {
        'doc_type': request.args.get('doc_type', 'all'),
        'client': request.args.get('client', '').strip(),
        'status': request.args.get('status', 'all'),
        'direction': request.args.get('direction', 'all'),
        'service_type': request.args.get('service_type', 'all'),
        'date_from': request.args.get('date_from', '').strip(),
        'date_to': request.args.get('date_to', '').strip(),
        'keyword': request.args.get('keyword', '').strip(),
    }
    all_rows = [normalize_admin_document_history_row_v2(row) for row in fetch_admin_document_history_rows_with_vendor_statements_v2()]
    for row in all_rows:
        if row.get('detail_url') or not row.get('detail_endpoint') or not row.get('id'):
            continue
        row['detail_url'] = url_for(row['detail_endpoint'], id=row['id'])
    history_rows = apply_admin_document_history_filters_v2(all_rows, filters)
    client_options = sorted({row.get('client_name') for row in all_rows if row.get('client_name') and row.get('client_name') != '-'})
    status_options = sorted({(row.get('status'), row.get('status_label')) for row in all_rows if row.get('status')})
    document_type_options = [
        ('shikiriosho', '精算書'),
        ('user_mitsumori', '見積り依頼書 / 業者向け依頼書'),
        ('user_kaitori_shoudaku', '買取依頼書'),
        ('invoice', '買取明細書'),
        ('user_keisan', 'オークション計算書'),
        ('admin_kaitori_shoudaku', '業者買取明細書'),
    ]
    document_type_cards = build_admin_document_type_cards_v2(all_rows)

    def count_document_history(direction=None, doc_type=None, document_key=None):
        return sum(
            1
            for row in all_rows
            if (direction in (None, 'all') or row.get('direction_key') == direction)
            and (doc_type in (None, 'all') or row.get('kind') == doc_type)
            and (document_key in (None, 'all') or row.get('document_key') == document_key)
        )

    document_history_category_cards = [
        {
            'step': '1',
            'title': 'クライアントから届いた依頼書',
            'copy': 'クライアントから届いた見積依頼書・買取依頼書を確認します。',
            'count_label': f"{count_document_history(direction='client_incoming')}件",
            'url': url_for('admin_documents_history', direction='client_incoming'),
        },
        {
            'step': '2',
            'title': '開花から業者への依頼書',
            'copy': '開花から業者へ送った依頼書の履歴を確認します。',
            'count_label': f"{count_document_history(direction='vendor_outgoing')}件",
            'url': url_for('admin_documents_history', direction='vendor_outgoing'),
        },
        {
            'step': '3',
            'title': '業者から届いた回答書類',
            'copy': '業者から戻ってきた回答書類・明細を確認します。',
            'count_label': f"{count_document_history(direction='vendor_incoming')}件",
            'url': url_for('admin_documents_history', direction='vendor_incoming'),
        },
        {
            'step': '4',
            'title': 'クライアントへ返送した書類',
            'copy': 'クライアントへ返送した買取明細書・精算書・計算書の履歴を確認します。',
            'count_label': f"{count_document_history(doc_type='invoice', direction='client_outgoing')}件",
            'url': url_for('admin_documents_history', doc_type='invoice', direction='client_outgoing'),
        },
        {
            'step': '5',
            'title': 'クライアント返信確認',
            'copy': 'クライアント側から届いた見積依頼書や確認書類を後から確認します。',
            'count_label': f"{count_document_history(doc_type='user_mitsumori', direction='client_outgoing')}件",
            'url': url_for('admin_documents_history', doc_type='user_mitsumori', direction='client_outgoing'),
        },
        {
            'step': '6',
            'title': '精算書',
            'copy': '精算書の作成・送付履歴をクライアント別に確認します。',
            'count_label': f"{count_document_history(doc_type='shikiriosho', direction='client_outgoing')}件",
            'url': url_for('admin_documents_history', doc_type='shikiriosho', direction='client_outgoing'),
        },
        {
            'step': '7',
            'title': '計算書',
            'copy': '代行仕入れで作成した計算書と送付履歴を確認します。',
            'count_label': f"{count_document_history(doc_type='user_keisan', direction='client_outgoing')}件",
            'url': url_for('admin_documents_history', doc_type='user_keisan', direction='client_outgoing'),
        },
    ]
    return render_template(
        'admin/documents_history.html',
        history_rows=history_rows,
        filters=filters,
        client_options=client_options,
        status_options=status_options,
        document_type_options=document_type_options,
        document_type_cards=document_type_cards,
        document_history_category_cards=document_history_category_cards,
        service_types=SALES_AGENCY_SERVICE_TYPES,
    )


app.view_functions['admin_documents_dashboard'] = admin_documents_dashboard_v2
app.view_functions['admin_documents_history'] = admin_documents_history_v2
if 'admin_documents_history' not in {rule.endpoint for rule in app.url_map.iter_rules()}:
    app.add_url_rule('/admin/documents/history', endpoint='admin_documents_history', view_func=admin_documents_history_v2)


@app.route('/admin/auction-keisan/send-bulk', methods=['POST'])
@login_required
@admin_required
def admin_auction_keisan_send_bulk():
    selected_ids = []
    for raw_id in request.form.getlist('document_ids'):
        try:
            selected_ids.append(int(raw_id))
        except (TypeError, ValueError):
            continue

    send_scope = request.form.get('send_scope', 'selected')
    auction_id = request.form.get('auction_id', type=int)
    conn = get_db()
    updated_count = 0
    reflected_count = 0

    try:
        now = get_jst_now()
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            params = []
            query = """
                SELECT id, proxy_service_auction_id
                FROM user_keisan
                WHERE is_admin_created = TRUE
                  AND status = 'completed'
                  AND proxy_service_auction_id IS NOT NULL
            """
            if auction_id:
                query += " AND proxy_service_auction_id = %s"
                params.append(auction_id)
            if send_scope != 'all':
                if not selected_ids:
                    flash('送付する計算書を選択してください', 'error')
                    cur.close()
                    conn.close()
                    if auction_id:
                        return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
                    return redirect(url_for('admin_auction_keisan_list'))
                placeholders = ','.join(['%s'] * len(selected_ids))
                query += f" AND id IN ({placeholders})"
                params.extend(selected_ids)
            query += " ORDER BY id"
            cur.execute(query, tuple(params))
            target_docs = [dict(row) for row in cur.fetchall()]
        else:
            cur = conn.cursor()
            params = []
            query = """
                SELECT id, proxy_service_auction_id
                FROM user_keisan
                WHERE is_admin_created = 1
                  AND status = 'completed'
                  AND proxy_service_auction_id IS NOT NULL
            """
            if auction_id:
                query += " AND proxy_service_auction_id = ?"
                params.append(auction_id)
            if send_scope != 'all':
                if not selected_ids:
                    flash('送付する計算書を選択してください', 'error')
                    cur.close()
                    conn.close()
                    if auction_id:
                        return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
                    return redirect(url_for('admin_auction_keisan_list'))
                placeholders = ','.join(['?'] * len(selected_ids))
                query += f" AND id IN ({placeholders})"
                params.extend(selected_ids)
            query += " ORDER BY id"
            cur.execute(query, tuple(params))
            target_docs = [dict(row) for row in cur.fetchall()]

        if not target_docs:
            cur.close()
            conn.close()
            flash('送付対象の計算書はありませんでした', 'info')
            if auction_id:
                return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
            return redirect(url_for('admin_auction_keisan_list'))

        for doc in target_docs:
            result = submit_proxy_service_keisan_document(conn, doc.get('id'), current_user.id, now=now)
            updated_count += 1
            reflected_count += int(result.get('reflected_count') or 0)

        conn.commit()
        cur.close()
        conn.close()
        flash(f'{updated_count}件の書類を送付し、{reflected_count}件をユーザー商品へ反映しました', 'success')
        if auction_id:
            return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
        return redirect(url_for('admin_auction_keisan_list'))
    except Exception as e:
        conn.rollback()
        conn.close()
        flash(f'一括送付中にエラーが発生しました: {str(e)}', 'error')
        if auction_id:
            return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
        return redirect(url_for('admin_auction_keisan_list'))

    try:
        if DATABASE_URL:
            cur = conn.cursor()
            params = []
            where_sql = """
                WHERE is_admin_created = TRUE
                  AND status = 'completed'
                  AND proxy_service_auction_id IS NOT NULL
            """
            if auction_id:
                where_sql += " AND proxy_service_auction_id = %s"
                params.append(auction_id)

            if send_scope == 'all':
                cur.execute(
                    f"""
                    UPDATE user_keisan
                    SET status = 'submitted', updated_at = CURRENT_TIMESTAMP
                    {where_sql}
                    """,
                    tuple(params),
                )
                updated_count = cur.rowcount
            elif selected_ids:
                placeholders = ','.join(['%s'] * len(selected_ids))
                cur.execute(
                    f"""
                    UPDATE user_keisan
                    SET status = 'submitted', updated_at = CURRENT_TIMESTAMP
                    {where_sql}
                      AND id IN ({placeholders})
                    """,
                    tuple(params + selected_ids),
                )
                updated_count = cur.rowcount
        else:
            cur = conn.cursor()
            params = []
            where_sql = """
                WHERE is_admin_created = 1
                  AND status = 'completed'
                  AND proxy_service_auction_id IS NOT NULL
            """
            if auction_id:
                where_sql += " AND proxy_service_auction_id = ?"
                params.append(auction_id)

            if send_scope == 'all':
                cur.execute(
                    f"""
                    UPDATE user_keisan
                    SET status = 'submitted', updated_at = CURRENT_TIMESTAMP
                    {where_sql}
                    """,
                    tuple(params),
                )
                updated_count = cur.rowcount
            elif selected_ids:
                placeholders = ','.join(['?'] * len(selected_ids))
                cur.execute(
                    f"""
                    UPDATE user_keisan
                    SET status = 'submitted', updated_at = CURRENT_TIMESTAMP
                    {where_sql}
                      AND id IN ({placeholders})
                    """,
                    tuple(params + selected_ids),
                )
                updated_count = cur.rowcount

        conn.commit()
    finally:
        cur.close()
        conn.close()

    if send_scope != 'all' and not selected_ids:
        flash('送付する計算書を選択してください', 'error')
    elif updated_count:
        flash(f'{updated_count}件の書類を送付しました', 'success')
    else:
        flash('送付対象の計算書はありませんでした', 'info')

    if auction_id:
        return redirect(url_for('admin_proxy_service_document_history', auction_id=auction_id))
    return redirect(url_for('admin_auction_keisan_list'))

