# アプリ起動時にスケジューラーを初期化
# Gunicorn等で複数ワーカーの場合、重複起動を防ぐ
import atexit

if os.environ.get('WERKZEUG_RUN_MAIN') == 'true' or not app.debug:
    init_scheduler()

# アプリ終了時にスケジューラーを停止
@atexit.register
def shutdown_scheduler():
    global scheduler
    if scheduler is not None and scheduler.running:
        scheduler.shutdown(wait=False)
        print(f"[{get_jst_now()}] Scheduler stopped")

@app.route('/item/<int:id>/download_all')
@login_required
def download_all_images(id):
    import io
    import zipfile
    
    # DB接続
    conn = get_db()
    item = None
    
    try:
        if DATABASE_URL:
            cur = conn.cursor(cursor_factory=RealDictCursor)
            cur.execute("SELECT * FROM merchandise WHERE id = %s", (id,))
            item_data = cur.fetchone()
            if item_data:
                item = dict(item_data)
        else:
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute("SELECT * FROM merchandise WHERE id = ?", (id,))
            item_data = cur.fetchone()
            if item_data:
                item = dict(item_data)
    except Exception as e:
        print(f"DB Error: {e}")
    finally:
        if 'cur' in locals():
            cur.close()
        conn.close()
    
    if not item:
        flash('商品が見つかりません', 'error')
        return redirect(request.referrer or url_for('index'))
        
    photos = []
    if item.get('photo_path'):
        photos.append(item['photo_path'])
        
    if item.get('additional_photos'):
        try:
            additional = json.loads(item['additional_photos'])
            if isinstance(additional, list):
                photos.extend(additional)
        except:
            # JSONデコード失敗時、カンマ区切りとして処理（後方互換性）
            if isinstance(item['additional_photos'], str):
                photos.extend([p.strip() for p in item['additional_photos'].split(',') if p.strip()])
            
    if not photos:
        flash('画像がありません', 'warning')
        return redirect(request.referrer or url_for('index'))

    memory_file = io.BytesIO()
    with zipfile.ZipFile(memory_file, 'w', zipfile.ZIP_DEFLATED) as zf:
        for i, photo_path in enumerate(photos):
            filename = os.path.basename(photo_path)
            abs_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            
            if os.path.exists(abs_path):
                ext = os.path.splitext(filename)[1]
                zip_filename = f"image_{i+1:03d}{ext}"
                try:
                    zf.write(abs_path, zip_filename)
                except Exception as e:
                    print(f"Error adding file to zip: {e}")
    
    memory_file.seek(0)
    
    # ファイル名生成（英数字のみ）
    safe_name = "".join([c for c in item.get('product_name', '') if c.isalnum() or c in (' ', '-', '_')]).strip()
    if not safe_name:
        safe_name = f"item_{id}"
        
    return send_file(
        memory_file,
        mimetype='application/zip',
        as_attachment=True,
        download_name=f"{safe_name}_images.zip"
    )


def add_source_endpoint_fallback(endpoint, rule, target_endpoint, methods):
    if endpoint in app.view_functions or target_endpoint not in app.view_functions:
        return
    app.add_url_rule(
        rule,
        endpoint=endpoint,
        view_func=app.view_functions[target_endpoint],
        methods=methods,
    )


